AUDIT_RUNNER_ALLOWED_ENV = {
    "HOME",
    "LANG",
    "LC_ALL",
    "LC_CTYPE",
    "PATH",
    "PIP_CACHE_DIR",
    "PIP_CONFIG_FILE",
    "PIP_NO_INDEX",
    "PYTHONDONTWRITEBYTECODE",
    "PYTHONHASHSEED",
    "PYTHONNOUSERSITE",
    "SBOM_EXCLUDED_CVES_FILE",
    "TMPDIR",
    "TZ",
    "XDG_CACHE_HOME",
}


def _audit_version_key(value: str) -> tuple[tuple[int, int | str], ...]:
    _require(
        isinstance(value, str) and bool(value),
        "wheel dependency version is missing",
    )
    tokens = re.findall(r"[0-9]+|[A-Za-z]+", value)
    _require(tokens, "wheel dependency version is invalid: %s" % value)
    return tuple(
        (0, int(token)) if token.isdigit() else (1, token.lower()) for token in tokens
    )


def _audit_version_satisfies(version: str, constraints: str) -> bool:
    if not constraints:
        return True
    selected = _audit_version_key(version)
    for raw_constraint in constraints.split(","):
        constraint = raw_constraint.strip()
        match = re.fullmatch(r"(===|==|!=|~=|>=|<=|>|<)\s*(\S+)", constraint)
        _require(
            match is not None,
            "unsupported wheel dependency constraint: %s" % constraint,
        )
        operator, required_text = match.groups()
        required = _audit_version_key(required_text)
        if operator in ("==", "==="):
            accepted = version == required_text
        elif operator == "!=":
            accepted = version != required_text
        elif operator == ">=":
            accepted = selected >= required
        elif operator == "<=":
            accepted = selected <= required
        elif operator == ">":
            accepted = selected > required
        elif operator == "<":
            accepted = selected < required
        else:
            numeric = [int(item) for item in re.findall(r"[0-9]+", required_text)]
            _require(
                len(numeric) >= 2,
                "compatible-release constraint is too broad: %s" % constraint,
            )
            upper = (
                (numeric[0] + 1,)
                if len(numeric) == 2
                else tuple(numeric[:-2] + [numeric[-2] + 1])
            )
            selected_numeric = tuple(
                int(item) for item in re.findall(r"[0-9]+", version)
            )
            accepted = selected >= required and selected_numeric < upper
        if not accepted:
            return False
    return True


def _audit_parse_metadata_requirement(
    value: str,
) -> tuple[str, set[str], str, str]:
    requirement, separator, marker = value.partition(";")
    match = re.fullmatch(
        r"\s*([A-Za-z0-9][A-Za-z0-9_.-]*)"
        r"(?:\[([A-Za-z0-9_.-]+(?:\s*,\s*[A-Za-z0-9_.-]+)*)\])?"
        r"\s*(.*?)\s*",
        requirement,
    )
    _require(match is not None, "wheel METADATA requirement is invalid: %s" % value)
    name, extras_raw, constraints = match.groups()
    constraints = constraints.strip()
    if constraints.startswith("(") and constraints.endswith(")"):
        constraints = constraints[1:-1].strip()
    extras = {
        item.strip().lower() for item in (extras_raw or "").split(",") if item.strip()
    }
    return (
        _audit_canonical_package_name(name),
        extras,
        constraints,
        marker.strip() if separator else "",
    )


def _audit_marker_comparison(
    variable: str,
    operator: str,
    expected: str,
    selected_extras: set[str],
) -> bool:
    if variable == "extra":
        actual: str | tuple[tuple[int, int | str], ...] = ""
        comparisons = [
            (item == expected if operator == "==" else item != expected)
            for item in selected_extras
        ]
        return any(comparisons) if comparisons else operator == "!="
    if variable == "python_version":
        actual = _audit_version_key(
            "%s.%s" % (sys.version_info.major, sys.version_info.minor)
        )
        wanted: str | tuple[tuple[int, int | str], ...] = _audit_version_key(expected)
    elif variable == "platform_system":
        actual = platform.system()
        wanted = expected
    else:
        raise ReleaseError("unsupported wheel environment marker: %s" % variable)
    if operator == "==":
        return actual == wanted
    if operator == "!=":
        return actual != wanted
    _require(
        variable == "python_version",
        "unsupported wheel marker comparison: %s %s" % (variable, operator),
    )
    if operator == "<":
        return actual < wanted
    if operator == "<=":
        return actual <= wanted
    if operator == ">":
        return actual > wanted
    if operator == ">=":
        return actual >= wanted
    raise ReleaseError("unsupported wheel marker operator: %s" % operator)


def _audit_marker_applies(marker: str, selected_extras: set[str]) -> bool:
    if not marker:
        return True
    groups = re.split(r"\s+or\s+", marker, flags=re.IGNORECASE)
    for group in groups:
        accepted = True
        for raw_clause in re.split(r"\s+and\s+", group, flags=re.IGNORECASE):
            clause = raw_clause.strip()
            while clause.startswith("(") and clause.endswith(")"):
                clause = clause[1:-1].strip()
            match = re.fullmatch(
                r"(extra|python_version|platform_system)\s*"
                r"(==|!=|<=|>=|<|>)\s*(['\"])(.*?)\3",
                clause,
            )
            _require(
                match is not None,
                "unsupported wheel environment marker: %s" % marker,
            )
            if not _audit_marker_comparison(
                match.group(1),
                match.group(2),
                match.group(4),
                selected_extras,
            ):
                accepted = False
                break
        if accepted:
            return True
    return False


def _audit_wheel_tag_supported(filename: str, wheel_tags: set[str]) -> None:
    stem = filename.removesuffix(".whl")
    parts = stem.rsplit("-", 3)
    _require(len(parts) == 4, "locked wheel filename has no compatibility tag")
    filename_tag = "-".join(parts[-3:])
    filename_python, filename_abi, filename_platform = parts[-3:]
    expanded_filename_tags = {
        "%s-%s-%s" % (python_tag, abi_tag, platform_tag)
        for python_tag in filename_python.split(".")
        for abi_tag in filename_abi.split(".")
        for platform_tag in filename_platform.split(".")
    }
    _require(
        filename_tag in wheel_tags or expanded_filename_tags <= wheel_tags,
        "locked wheel filename and WHEEL tags disagree",
    )
    current_cp = "cp%s%s" % (sys.version_info.major, sys.version_info.minor)
    machine = platform.machine().lower().replace("-", "_")
    supported = False
    for raw_tag in wheel_tags:
        tag_parts = raw_tag.split("-")
        _require(len(tag_parts) == 3, "wheel compatibility tag is malformed")
        python_tag, abi_tag, platform_tag = tag_parts
        python_tags = set(python_tag.split("."))
        if (
            platform_tag == "any"
            and abi_tag == "none"
            and (
                "py3" in python_tags
                or "py2" in python_tags
                and "py3" in python_tags
                or current_cp in python_tags
            )
        ):
            supported = True
            continue
        if current_cp not in python_tags or abi_tag not in (
            current_cp,
            "abi3",
            "none",
        ):
            continue
        if sys.platform == "darwin":
            supported = platform_tag.startswith("macosx_") and (
                platform_tag.endswith("_" + machine)
                or platform_tag.endswith("_universal2")
            )
        elif sys.platform.startswith("linux"):
            supported = platform_tag.startswith(
                ("manylinux", "musllinux", "linux")
            ) and platform_tag.endswith("_" + machine)
    _require(supported, "locked wheel is incompatible with this release host")


def _audit_extract_verified_wheel(
    *,
    artifact: dict[str, Any],
    payload: bytes,
    destination: Path,
) -> dict[str, Any]:
    try:
        archive = zipfile.ZipFile(io.BytesIO(payload))
    except zipfile.BadZipFile as exc:
        raise ReleaseError("locked release-tool artifact is not a valid wheel") from exc
    with archive:
        infos = archive.infolist()
        _require(infos, "locked release-tool wheel is empty")
        names: set[str] = set()
        total_size = 0
        for info in infos:
            name = info.filename
            pure = PurePosixPath(name)
            _require(
                name not in names
                and "\\" not in name
                and not pure.is_absolute()
                and all(part not in ("", ".", "..") for part in pure.parts),
                "locked wheel contains an unsafe or duplicate path",
            )
            names.add(name)
            total_size += info.file_size
            _require(
                total_size <= 512 * 1024 * 1024,
                "locked wheel expands beyond the audit safety limit",
            )
            mode = info.external_attr >> 16
            _require(
                not stat_module.S_ISLNK(mode),
                "locked wheel contains a symlink",
            )
            _require(
                not bool(info.flag_bits & 0x1),
                "locked wheel contains an encrypted member",
            )

        metadata_names = [
            name
            for name in names
            if name.endswith(".dist-info/METADATA")
            and len(PurePosixPath(name).parts) == 2
        ]
        wheel_names = [
            name
            for name in names
            if name.endswith(".dist-info/WHEEL") and len(PurePosixPath(name).parts) == 2
        ]
        _require(
            len(metadata_names) == 1 and len(wheel_names) == 1,
            "locked wheel must contain one METADATA and one WHEEL record",
        )
        metadata = BytesParser().parsebytes(archive.read(metadata_names[0]))
        _require(
            _audit_canonical_package_name(str(metadata.get("Name", "")))
            == _audit_canonical_package_name(artifact["name"])
            and str(metadata.get("Version", "")) == artifact["version"],
            "locked wheel Name/Version disagrees with the lock",
        )
        wheel_text = archive.read(wheel_names[0]).decode("utf-8", errors="strict")
        wheel_tags = {
            line.split(":", 1)[1].strip()
            for line in wheel_text.splitlines()
            if line.startswith("Tag:")
        }
        _require(wheel_tags, "locked wheel contains no compatibility tags")
        _audit_wheel_tag_supported(artifact["filename"], wheel_tags)

        destination.mkdir(mode=0o700)
        for info in infos:
            if info.is_dir():
                (destination / PurePosixPath(info.filename)).mkdir(
                    mode=0o700,
                    parents=True,
                    exist_ok=True,
                )
                continue
            output = destination / PurePosixPath(info.filename)
            output.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
            output.write_bytes(archive.read(info))
    return {
        "requirements": list(metadata.get_all("Requires-Dist", [])),
        "tree_sha256": _audit_sha256_tree(destination),
    }


def _audit_validate_wheel_dependency_graph(
    lock: dict[str, Any],
    metadata_by_name: dict[str, dict[str, Any]],
) -> None:
    artifacts = {
        _audit_canonical_package_name(artifact["name"]): artifact
        for artifact in lock["artifacts"]
    }
    selected_extras = {name: set() for name in artifacts}
    queue = ["esp-idf-sbom"]
    visited_extras: dict[str, frozenset[str]] = {}
    metadata_edges: dict[str, set[str]] = {}
    while queue:
        name = queue.pop(0)
        snapshot = frozenset(selected_extras[name])
        if visited_extras.get(name) == snapshot:
            continue
        visited_extras[name] = snapshot
        active: set[str] = set()
        for raw_requirement in metadata_by_name[name]["requirements"]:
            dependency, extras, constraints, marker = _audit_parse_metadata_requirement(
                raw_requirement
            )
            if not _audit_marker_applies(marker, selected_extras[name]):
                continue
            _require(
                dependency in artifacts,
                "wheel METADATA dependency is absent from the locked closure: %s"
                % dependency,
            )
            _require(
                _audit_version_satisfies(
                    artifacts[dependency]["version"],
                    constraints,
                ),
                "locked wheel version does not satisfy METADATA: %s" % dependency,
            )
            active.add(dependency)
            before = set(selected_extras[dependency])
            selected_extras[dependency].update(extras)
            if selected_extras[dependency] != before:
                queue.append(dependency)
            if dependency not in visited_extras:
                queue.append(dependency)
        metadata_edges[name] = active

    _require(
        set(visited_extras) == set(artifacts),
        "wheel METADATA closure is incomplete or contains unreachable artifacts",
    )
    for name, artifact in artifacts.items():
        locked_edges = {
            _audit_locked_requirement(requirement)[0]
            for requirement in _audit_artifact_requirements(artifact)
        }
        _require(
            metadata_edges.get(name, set()) == locked_edges,
            "wheel METADATA dependency graph disagrees with release-tools.lock",
        )


def _audit_prepare_locked_wheels(
    *,
    lock: dict[str, Any],
    wheelhouse: Path,
    destination: Path,
) -> tuple[list[str], list[dict[str, str]], dict[str, str]]:
    _require(not wheelhouse.is_symlink(), "release-tool wheelhouse is a symlink")
    _require(wheelhouse.is_dir(), "release-tool wheelhouse is missing")
    expected_filenames = {artifact["filename"] for artifact in lock["artifacts"]}
    actual_wheels = {
        path.name for path in wheelhouse.iterdir() if path.name.endswith(".whl")
    }
    _require(
        actual_wheels == expected_filenames,
        "release-tool wheelhouse must contain exactly the locked wheels",
    )
    destination.mkdir(mode=0o700)
    module_paths: list[str] = []
    identities: list[dict[str, str]] = []
    tree_hashes: dict[str, str] = {}
    metadata_by_name: dict[str, dict[str, Any]] = {}
    for artifact in sorted(
        lock["artifacts"],
        key=lambda item: _audit_canonical_package_name(item["name"]),
    ):
        candidate = wheelhouse / artifact["filename"]
        _audit_no_symlink_components(
            wheelhouse,
            candidate,
            "locked release-tool wheel",
        )
        try:
            file_stat = candidate.stat(follow_symlinks=False)
            payload = candidate.read_bytes()
        except OSError as exc:
            raise ReleaseError("cannot read locked release-tool wheel") from exc
        _require(
            stat_module.S_ISREG(file_stat.st_mode),
            "locked release-tool wheel is not a regular file",
        )
        _require(
            _sha256_bytes(payload) == artifact["sha256"],
            "locked release-tool wheel digest changed",
        )
        name = _audit_canonical_package_name(artifact["name"])
        extracted = destination / name
        metadata_by_name[name] = _audit_extract_verified_wheel(
            artifact=artifact,
            payload=payload,
            destination=extracted,
        )
        module_paths.append(str(extracted.resolve()))
        tree_hashes[name] = metadata_by_name[name]["tree_sha256"]
        identities.append(
            {
                "name": artifact["name"],
                "version": artifact["version"],
                "filename": artifact["filename"],
                "sha256": artifact["sha256"],
            }
        )
    _audit_validate_wheel_dependency_graph(lock, metadata_by_name)
    return module_paths, identities, tree_hashes


def _audit_network_isolation_prefix() -> tuple[list[str], dict[str, str]]:
    _require(
        sys.platform == "darwin",
        "no reviewed OS network isolator is available on this release host",
    )
    executable = Path("/usr/bin/sandbox-exec")
    _require(
        executable.exists()
        and not executable.is_symlink()
        and stat_module.S_ISREG(executable.stat().st_mode)
        and executable.stat().st_uid == 0
        and not bool(executable.stat().st_mode & 0o022),
        "trusted Darwin sandbox-exec is unavailable",
    )
    prefix = [str(executable), "-p", AUDIT_SANDBOX_PROFILE]
    probe = subprocess.run(
        [
            *prefix,
            str(Path(sys.executable).resolve()),
            "-I",
            "-S",
            "-c",
            (
                "import errno,socket,sys;"
                "s=socket.socket(socket.AF_INET,socket.SOCK_STREAM);"
                "result=s.connect_ex(('1.1.1.1',53));s.close();"
                "sys.exit(0 if result==errno.EPERM else 91)"
            ),
        ],
        check=False,
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        env={
            "HOME": os.devnull,
            "PATH": "/usr/bin:/bin",
            "PYTHONDONTWRITEBYTECODE": "1",
            "PYTHONNOUSERSITE": "1",
        },
    )
    _require(
        probe.returncode == 0,
        "Darwin sandbox network-denial probe failed closed",
    )
    return prefix, {
        "kind": "darwin-sandbox-exec",
        "policy_sha256": _sha256_bytes(AUDIT_SANDBOX_PROFILE.encode("utf-8")),
        "executable_sha256": _sha256_path(executable),
    }


class _LockedAuditCompleted:
    def __init__(
        self,
        *,
        returncode: int,
        stdout: str,
        stderr: str,
        executed_artifacts: dict[str, str],
        network_isolated: bool,
        execution_identity: dict[str, Any],
    ):
        self.returncode = returncode
        self.stdout = stdout
        self.stderr = stderr
        self.executed_artifacts = executed_artifacts
        self.network_isolated = network_isolated
        self.execution_identity = execution_identity


class LockedWheelSbomRunner:
    """Run esp-idf-sbom only from the reviewed wheel closure, offline."""

    def __init__(
        self,
        *,
        repo_root: Path,
        build_root: Path,
        wheelhouse: Path,
    ):
        self._temporary: tempfile.TemporaryDirectory[str] | None = None
        self._closed = False
        self._repo_root = Path(repo_root)
        self._build_root = Path(build_root)
        self._wheelhouse = Path(wheelhouse)
        _require(self._repo_root.is_dir(), "repository root is missing")
        _require(self._build_root.is_dir(), "license audit build root is missing")
        lock = _audit_load_tool_lock(self._repo_root)
        self._temporary = tempfile.TemporaryDirectory(prefix="pyble-locked-sbom-")
        try:
            private_root = Path(self._temporary.name)
            (
                self._module_paths,
                artifact_identities,
                self._tree_hashes,
            ) = _audit_prepare_locked_wheels(
                lock=lock,
                wheelhouse=self._wheelhouse,
                destination=private_root / "site",
            )
            self._isolation_prefix, isolation_identity = (
                _audit_network_isolation_prefix()
            )
            executable = Path(sys.executable).resolve()
            self._artifact_hashes = dict(sorted(lock["_artifact_hashes"].items()))
            self._execution_identity = {
                "runner": "pyble-locked-wheel-v1",
                "python": {
                    "implementation": sys.implementation.name,
                    "version": platform.python_version(),
                    "executable_sha256": _sha256_path(executable),
                },
                "isolation": isolation_identity,
                "artifacts": artifact_identities,
            }
            _audit_validate_execution_identity(
                self._execution_identity,
                artifact_hashes=self._artifact_hashes,
            )
            self._private_root = private_root
            self._python = str(executable)
        except Exception:
            self.close()
            raise

    def __enter__(self) -> "LockedWheelSbomRunner":
        _require(not self._closed, "locked SBOM runner is closed")
        return self

    def __exit__(self, *_args: Any) -> bool:
        self.close()
        return False

    def close(self) -> None:
        if self._temporary is not None:
            self._temporary.cleanup()
            self._temporary = None
        self._closed = True

    def _verify_private_closure(self) -> None:
        for name, expected in self._tree_hashes.items():
            _require(
                _audit_sha256_tree(self._private_root / "site" / name) == expected,
                "private locked-wheel environment changed during execution",
            )

    def __call__(
        self,
        argv: Any,
        *,
        cwd: Path | str | None = None,
        env: dict[str, str] | None = None,
        check: bool = True,
        network_disabled: bool = False,
        **_unused: Any,
    ) -> _LockedAuditCompleted:
        _require(not self._closed, "locked SBOM runner is closed")
        _require(check is True, "locked SBOM runner requires checked execution")
        _require(
            network_disabled is True,
            "locked SBOM runner refuses a network-enabled invocation",
        )
        _require(
            isinstance(argv, (list, tuple))
            and all(isinstance(item, (str, Path)) for item in argv),
            "locked SBOM runner command is invalid",
        )
        command = [str(item) for item in argv]
        _require(
            len(command) == 10
            and command[:4] == [sys.executable, "-m", "esp_idf_sbom", "create"]
            and command[5] == "--output-file"
            and command[7:] == ["--rem-unused", "--rem-config", "--file-tags"],
            "locked SBOM runner rejected an unexpected command",
        )
        working = _audit_path_in_roots(
            Path(cwd) if cwd is not None else Path(),
            relative_to=self._build_root,
            roots=(self._build_root,),
            label="locked SBOM working directory",
        )
        _require(working.is_dir(), "locked SBOM working directory is missing")
        description = _audit_path_in_roots(
            command[4],
            relative_to=working,
            roots=(self._build_root,),
            label="locked SBOM project description",
        )
        _require(
            description.is_file() and description.name == "project_description.json",
            "locked SBOM project description is invalid",
        )
        output = Path(command[6])
        _require(
            output.is_absolute()
            and output.parent.is_dir()
            and not output.is_symlink()
            and not output.parent.is_symlink(),
            "locked SBOM output path is unsafe",
        )
        received_env = env if isinstance(env, dict) else {}
        clean_env = {
            key: value
            for key, value in received_env.items()
            if key in AUDIT_RUNNER_ALLOWED_ENV and isinstance(value, str)
        }
        clean_env.update(
            {
                "PIP_CONFIG_FILE": os.devnull,
                "PIP_NO_INDEX": "1",
                "PYTHONDONTWRITEBYTECODE": "1",
                "PYTHONHASHSEED": "0",
                "PYTHONNOUSERSITE": "1",
                "TMPDIR": str(self._private_root),
            }
        )
        self._verify_private_closure()
        completed = subprocess.run(
            [
                *self._isolation_prefix,
                self._python,
                "-I",
                "-B",
                "-S",
                "-c",
                AUDIT_RUNNER_BOOTSTRAP,
                json.dumps(self._module_paths, separators=(",", ":")),
                *command[3:],
            ],
            cwd=working,
            env=clean_env,
            check=False,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
        self._verify_private_closure()
        if completed.returncode != 0:
            raise ReleaseError(
                "locked esp-idf-sbom failed (%d): %s"
                % (completed.returncode, completed.stderr.strip()[-1000:])
            )
        return _LockedAuditCompleted(
            returncode=completed.returncode,
            stdout=completed.stdout,
            stderr=completed.stderr,
            executed_artifacts=dict(self._artifact_hashes),
            network_isolated=True,
            execution_identity=copy.deepcopy(self._execution_identity),
        )


def _audit_immutable_ref(value: Any, label: str) -> str:
    _require(isinstance(value, str) and bool(value), "%s is missing" % label)
    commit = value.rsplit("@", 1)[-1]
    _require(
        COMMIT_RE.fullmatch(commit) is not None,
        "%s is not bound to a full immutable commit" % label,
    )
    return value


_AUDIT_POLICY_V2_KEYS = {
    "schema_version",
    "approved_license_refs",
    "review_files",
    "shipment_review",
    "raw_documents",
    "reviewed_packages",
    "resolved_inputs",
    "resolutions",
    "supplemental_packages",
    "toolchains",
}
_AUDIT_POLICY_V2_INPUT_KINDS = {
    "generated-component-archive",
    "generated-supplemental-archive",
    "opaque-archive",
    "toolchain-archive",
    "frozen-source-tree",
}
_AUDIT_POLICY_V2_SUPPLEMENTAL_INPUT_KINDS = {
    "generated-supplemental-archive",
    "frozen-source-tree",
}


def _audit_v2_hash(value: Any, label: str) -> str:
    _require(
        isinstance(value, str) and SHA256_RE.fullmatch(value) is not None,
        "%s must be a lowercase SHA-256" % label,
    )
    return value


def _audit_v2_nonempty(value: Any, label: str) -> str:
    _require(isinstance(value, str) and bool(value), "%s is missing" % label)
    return value


def _audit_v2_identity(
    profile_id: Any,
    role: Any,
    label: str,
) -> tuple[str, str]:
    valid_profiles = {
        profile for profile, _target, _idf_target in LICENSE_AUDIT_PROFILES
    }
    _require(
        isinstance(profile_id, str)
        and profile_id in valid_profiles
        and isinstance(role, str)
        and role in LICENSE_AUDIT_ROLES,
        "%s has an invalid profile/role identity" % label,
    )
    return profile_id, role


def _audit_v2_canonical(value: Any, label: str) -> str:
    try:
        return json.dumps(
            value,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        )
    except (TypeError, ValueError) as exc:
        raise ReleaseError("%s is not deterministic JSON data" % label) from exc


def _audit_v2_shipment_review(
    repo_root: Path,
    raw_record: Any,
    *,
    raw_occurrences: set[tuple[str, str, str]],
) -> tuple[dict[str, str], list[dict[str, str]], dict[tuple[str, str, str], str]]:
    """Validate the independent, canonical raw-package shipment ledger."""

    record = _exact_keys(
        raw_record,
        {"path", "sha256"},
        "shipment review policy",
    )
    relative = _safe_relative_path(
        record["path"],
        "shipment review policy path",
    )
    digest = _audit_v2_hash(
        record["sha256"],
        "shipment review policy digest",
    )
    path = _audit_repo_file(
        repo_root,
        relative,
        "shipment review ledger",
    )
    try:
        source = path.read_bytes()
        text = source.decode("utf-8", errors="strict")
    except (OSError, UnicodeError) as exc:
        raise ReleaseError(
            "shipment review ledger is missing or not strict UTF-8"
        ) from exc
    _require(
        _sha256_bytes(source) == digest,
        "shipment review ledger changed",
    )
    try:
        document = json.loads(text)
    except (TypeError, ValueError) as exc:
        raise ReleaseError("shipment review ledger is not valid JSON") from exc
    _require(
        source
        == (
            _audit_v2_canonical(document, "shipment review ledger") + "\n"
        ).encode("utf-8"),
        "shipment review ledger is not canonical JSON",
    )
    document = _exact_keys(
        document,
        {"schema_version", "occurrences"},
        "shipment review ledger",
    )
    _require(
        type(document["schema_version"]) is int
        and document["schema_version"] == 1,
        "shipment review ledger schema_version must be 1",
    )
    occurrences = document["occurrences"]
    _require(
        isinstance(occurrences, list) and bool(occurrences),
        "shipment review ledger occurrences must be nonempty",
    )
    normalized: list[dict[str, str]] = []
    classifications: dict[tuple[str, str, str], str] = {}
    for raw in occurrences:
        occurrence = _exact_keys(
            raw,
            {"profile_id", "role", "spdx_id", "disposition"},
            "shipment review occurrence",
        )
        profile_id, role = _audit_v2_identity(
            occurrence["profile_id"],
            occurrence["role"],
            "shipment review occurrence",
        )
        spdx_id = _audit_v2_nonempty(
            occurrence["spdx_id"],
            "shipment review occurrence SPDXID",
        )
        disposition = occurrence["disposition"]
        _require(
            disposition in {"allow", "allow-aggregate", "not-shipped"},
            "shipment review occurrence disposition is invalid",
        )
        identity = (profile_id, role, spdx_id)
        _require(
            identity not in classifications,
            "shipment review occurrence is duplicated",
        )
        classifications[identity] = disposition
        normalized.append(
            {
                "profile_id": profile_id,
                "role": role,
                "spdx_id": spdx_id,
                "disposition": disposition,
            }
        )
    expected_order = sorted(
        normalized,
        key=lambda item: (
            item["profile_id"],
            item["role"],
            item["spdx_id"],
        ),
    )
    _require(
        normalized == expected_order,
        "shipment review occurrences are not canonically ordered",
    )
    _require(
        set(classifications) == raw_occurrences,
        "shipment review ledger does not exactly cover raw package occurrences",
    )
    return (
        {"path": relative, "sha256": digest},
        normalized,
        classifications,
    )


def _audit_v2_manifest_evidence(
    repo_root: Path,
    raw_evidence: Any,
    *,
    build_root: Path | None = None,
) -> list[dict[str, Any]]:
    """Validate canonical literal-manifest evidence derived by the collector."""

    firmware_version = _read_lock(Path(repo_root))["pyble"]["agent_version"]
    includes_first_party_field = bool(
        _audit_first_party_frozen_sources_for_version(firmware_version)
    )
    _require(
        isinstance(raw_evidence, list) and bool(raw_evidence),
        "literal manifest evidence must be nonempty",
    )
    expected_targets = {
        target for _profile_id, target, _idf_target in LICENSE_AUDIT_PROFILES
    }
    normalized: list[dict[str, Any]] = []
    seen_targets: set[str] = set()
    for raw_record in raw_evidence:
        expected_fields = {
            "target",
            "architecture",
            "frozen_content_sha256",
            "qstrdefs_sha256",
            "mpy_cross",
            "generator_tools",
            "frozen_mpy",
            "linked_frozen_object",
            "generated_board_manifest",
            "manifests",
            "selections",
        }
        if includes_first_party_field:
            expected_fields.add("first_party_frozen_sources")
        record = _exact_keys(
            raw_record,
            expected_fields,
            "literal manifest evidence record",
        )
        target = record["target"]
        _require(
            isinstance(target, str)
            and target in expected_targets
            and target not in seen_targets,
            "literal manifest evidence target is invalid or duplicated",
        )
        seen_targets.add(target)
        frozen_digest = _audit_v2_hash(
            record["frozen_content_sha256"],
            "%s frozen_content.c digest" % target,
        )
        architecture = record["architecture"]
        _require(
            architecture == FROZEN_TARGET_SETTINGS[target]["architecture"],
            "%s frozen architecture changed" % target,
        )
        qstr_digest = _audit_v2_hash(
            record["qstrdefs_sha256"],
            "%s frozen qstr header digest" % target,
        )
        mpy_cross = _exact_keys(
            record["mpy_cross"],
            {"path", "sha256"},
            "%s mpy-cross evidence" % target,
        )
        mpy_cross_path = _safe_relative_path(
            mpy_cross["path"],
            "%s mpy-cross path" % target,
        )
        _require(
            mpy_cross_path
            == "firmware/upstream/micropython/mpy-cross/build/mpy-cross",
            "%s mpy-cross path changed" % target,
        )
        mpy_cross_digest = _audit_v2_hash(
            mpy_cross["sha256"],
            "%s mpy-cross digest" % target,
        )
        checked_mpy_cross = _audit_repo_file(
            repo_root,
            mpy_cross_path,
            "%s mpy-cross" % target,
        )
        _require(
            _sha256_path(checked_mpy_cross) == mpy_cross_digest,
            "%s mpy-cross changed" % target,
        )

        expected_generator_paths = {
            "firmware/upstream/micropython/mpy-cross/mpy_cross/__init__.py",
            "firmware/upstream/micropython/py/makeqstrdata.py",
            "firmware/upstream/micropython/tools/makemanifest.py",
            "firmware/upstream/micropython/tools/manifestfile.py",
            "firmware/upstream/micropython/tools/mpy-tool.py",
        }
        generators_raw = record["generator_tools"]
        _require(
            isinstance(generators_raw, list) and bool(generators_raw),
            "%s frozen generator inventory must be nonempty" % target,
        )
        generators: list[dict[str, str]] = []
        generator_paths: set[str] = set()
        for raw_generator in generators_raw:
            generator = _exact_keys(
                raw_generator,
                {"path", "sha256"},
                "%s frozen generator" % target,
            )
            relative = _safe_relative_path(
                generator["path"],
                "%s frozen generator path" % target,
            )
            digest = _audit_v2_hash(
                generator["sha256"],
                "%s frozen generator digest" % target,
            )
            _require(
                relative not in generator_paths,
                "%s frozen generator path is duplicated" % target,
            )
            source = _audit_repo_file(
                repo_root,
                relative,
                "%s frozen generator" % target,
            )
            _require(
                _sha256_path(source) == digest,
                "%s frozen generator changed" % target,
            )
            generator_paths.add(relative)
            generators.append({"path": relative, "sha256": digest})
        _require(
            generator_paths == expected_generator_paths
            and generators == sorted(generators, key=lambda item: item["path"]),
            "%s frozen generator inventory changed or is unordered" % target,
        )
        generated_board_manifest = _safe_relative_path(
            record["generated_board_manifest"],
            "%s generated board manifest path" % target,
        )
        retained_board_snapshot: dict[str, tuple[Any, ...]] | None = None
        retained_board_logical_prefix: str | None = None
        if build_root is None:
            board_dir = (
                Path(repo_root)
                / "firmware"
                / "upstream"
                / "micropython"
                / "ports"
                / "esp32"
                / "boards"
                / FROZEN_TARGET_SETTINGS[target]["board"]
            )
            expected_board_manifest = (
                "firmware/upstream/micropython/ports/esp32/boards/%s/manifest.py"
                % FROZEN_TARGET_SETTINGS[target]["board"]
            )
            generated_manifest_path = _audit_repo_file(
                repo_root,
                expected_board_manifest,
                "%s generated board manifest" % target,
            )
            generated_manifest_bytes = _audit_stable_regular_file_bytes(
                generated_manifest_path,
                "%s generated board manifest" % target,
            )
        else:
            (
                board_dir,
                retained_board_logical_prefix,
                retained_board_snapshot,
            ) = _audit_retained_generated_board_snapshot(
                    build_root=Path(build_root),
                    target=target,
            )
            generated_manifest_bytes = (
                _audit_retained_generated_board_snapshot_file(
                    retained_board_snapshot,
                    "manifest.py",
                    "%s generated board manifest" % target,
                )
            )
            expected_board_manifest = (
                retained_board_logical_prefix + "/manifest.py"
            )
        _require(
            generated_board_manifest == expected_board_manifest,
            "%s generated board manifest path changed" % target,
        )
        if build_root is not None:
            reviewed_manifest = _audit_repo_file(
                repo_root,
                "firmware/board_overlays/%s/manifest.py" % target,
                "%s reviewed board manifest" % target,
            )
            _require(
                generated_manifest_bytes
                == _audit_stable_regular_file_bytes(
                    reviewed_manifest,
                    "%s reviewed board manifest" % target,
                ),
                "%s generated board manifest differs from its reviewed overlay"
                % target,
            )

        manifests_raw = record["manifests"]
        _require(
            isinstance(manifests_raw, list) and bool(manifests_raw),
            "%s literal manifest inventory must be nonempty" % target,
        )
        manifests: list[dict[str, str]] = []
        manifest_paths: set[str] = set()
        for raw_manifest in manifests_raw:
            manifest = _exact_keys(
                raw_manifest,
                {"path", "sha256"},
                "%s literal manifest" % target,
            )
            relative = _safe_relative_path(
                manifest["path"],
                "%s literal manifest path" % target,
            )
            digest = _audit_v2_hash(
                manifest["sha256"],
                "%s literal manifest digest" % target,
            )
            _require(
                relative not in manifest_paths,
                "%s literal manifest path is duplicated" % target,
            )
            path = _audit_repo_file(
                repo_root,
                relative,
                "%s literal manifest" % target,
            )
            _require(
                _sha256_path(path) == digest,
                "%s literal manifest changed" % target,
            )
            manifest_paths.add(relative)
            manifests.append({"path": relative, "sha256": digest})
        _require(
            manifests == sorted(manifests, key=lambda item: item["path"]),
            "%s literal manifests are not canonically ordered" % target,
        )

        selections_raw = record["selections"]
        _require(
            isinstance(selections_raw, list) and bool(selections_raw),
            "%s frozen source selections must be nonempty" % target,
        )
        selections: list[dict[str, str]] = []
        destinations: set[str] = set()
        for raw_selection in selections_raw:
            selection = _exact_keys(
                raw_selection,
                {
                    "destination",
                    "source_path",
                    "sha256",
                    "optimization",
                    "metadata_version",
                },
                "%s frozen source selection" % target,
            )
            destination = _safe_relative_path(
                selection["destination"],
                "%s frozen destination" % target,
            )
            _require(
                destination.endswith(".py") and destination not in destinations,
                "%s frozen destination is invalid or duplicated" % target,
            )
            source_relative = _safe_relative_path(
                selection["source_path"],
                "%s frozen source path" % target,
            )
            digest = _audit_v2_hash(
                selection["sha256"],
                "%s frozen source digest" % target,
            )
            source = _audit_repo_file(
                repo_root,
                source_relative,
                "%s frozen source" % target,
            )
            _require(
                _sha256_path(source) == digest,
                "%s frozen source changed" % target,
            )
            optimization = selection["optimization"]
            _require(
                optimization is None
                or (
                    isinstance(optimization, int)
                    and not isinstance(optimization, bool)
                    and 0 <= optimization <= 3
                ),
                "%s frozen source optimization is invalid" % target,
            )
            metadata_version = selection["metadata_version"]
            _require(
                metadata_version is None
                or (
                    isinstance(metadata_version, str)
                    and re.fullmatch(
                        r"[0-9A-Za-z][0-9A-Za-z._+-]{0,127}",
                        metadata_version,
                    )
                    is not None
                ),
                "%s frozen source metadata version is invalid" % target,
            )
            destinations.add(destination)
            selections.append(
                {
                    "destination": destination,
                    "source_path": source_relative,
                    "sha256": digest,
                    "optimization": optimization,
                    "metadata_version": metadata_version,
                }
            )
        _require(
            selections
            == sorted(selections, key=lambda item: item["destination"]),
            "%s frozen source selections are not canonically ordered" % target,
        )
        first_party_frozen_sources = (
            _audit_first_party_frozen_source_evidence(
                repo_root=repo_root,
                target=target,
                board_dir=board_dir,
                selections={
                    selection["destination"]: (
                        Path(repo_root) / selection["source_path"]
                    )
                    for selection in selections
                },
                firmware_version=firmware_version,
                build_root=(
                    None if build_root is None else Path(build_root)
                ),
                retained_board_snapshot=retained_board_snapshot,
                retained_board_logical_prefix=retained_board_logical_prefix,
            )
        )
        if includes_first_party_field:
            _require(
                record["first_party_frozen_sources"]
                == first_party_frozen_sources,
                "%s first-party frozen source evidence changed" % target,
            )

        frozen_mpy_raw = record["frozen_mpy"]
        _require(
            isinstance(frozen_mpy_raw, list) and bool(frozen_mpy_raw),
            "%s frozen MPY inventory must be nonempty" % target,
        )
        frozen_mpy: list[dict[str, str]] = []
        mpy_destinations: set[str] = set()
        for raw_mpy in frozen_mpy_raw:
            mpy = _exact_keys(
                raw_mpy,
                {"destination", "sha256"},
                "%s frozen MPY record" % target,
            )
            destination = _safe_relative_path(
                mpy["destination"],
                "%s frozen MPY destination" % target,
            )
            digest = _audit_v2_hash(
                mpy["sha256"],
                "%s frozen MPY digest" % target,
            )
            _require(
                destination.endswith(".mpy")
                and destination not in mpy_destinations,
                "%s frozen MPY destination is invalid or duplicated" % target,
            )
            mpy_destinations.add(destination)
            frozen_mpy.append(
                {"destination": destination, "sha256": digest}
            )
        _require(
            mpy_destinations
            == {
                selection["destination"][:-3] + ".mpy"
                for selection in selections
            }
            and frozen_mpy
            == sorted(frozen_mpy, key=lambda item: item["destination"]),
            "%s frozen MPY inventory differs from selected sources" % target,
        )
        linked_raw = _exact_keys(
            record["linked_frozen_object"],
            {"component", "archive_path", "member", "sha256"},
            "%s linked frozen object" % target,
        )
        linked_component = linked_raw["component"]
        _require(
            isinstance(linked_component, str)
            and re.fullmatch(r"[0-9A-Za-z_.+-]+", linked_component)
            is not None,
            "%s linked frozen component is invalid" % target,
        )
        linked_archive = _safe_relative_path(
            linked_raw["archive_path"],
            "%s linked frozen archive" % target,
        )
        _require(
            linked_archive.startswith(target + "/")
            and linked_archive.endswith(".a"),
            "%s linked frozen archive identity is invalid" % target,
        )
        linked_member = linked_raw["member"]
        _require(
            isinstance(linked_member, str)
            and bool(linked_member)
            and Path(linked_member).name == linked_member
            and linked_member.endswith((".o", ".obj")),
            "%s linked frozen member identity is invalid" % target,
        )
        linked_digest = _audit_v2_hash(
            linked_raw["sha256"],
            "%s linked frozen object digest" % target,
        )
        normalized_record = {
            "target": target,
            "architecture": architecture,
            "frozen_content_sha256": frozen_digest,
            "qstrdefs_sha256": qstr_digest,
            "mpy_cross": {
                "path": mpy_cross_path,
                "sha256": mpy_cross_digest,
            },
            "generator_tools": generators,
            "frozen_mpy": frozen_mpy,
            "linked_frozen_object": {
                "component": linked_component,
                "archive_path": linked_archive,
                "member": linked_member,
                "sha256": linked_digest,
            },
            "generated_board_manifest": generated_board_manifest,
            "manifests": manifests,
            "selections": selections,
        }
        if includes_first_party_field:
            normalized_record["first_party_frozen_sources"] = (
                first_party_frozen_sources
            )
        if build_root is not None:
            _require(
                retained_board_snapshot is not None
                and retained_board_logical_prefix is not None,
                "%s retained generated board state was not captured" % target,
            )
            (
                final_board_dir,
                final_logical_prefix,
                final_board_snapshot,
            ) = _audit_retained_generated_board_snapshot(
                build_root=Path(build_root),
                target=target,
            )
            _require(
                final_board_dir == board_dir
                and final_logical_prefix == retained_board_logical_prefix
                and final_board_snapshot == retained_board_snapshot,
                "%s retained generated board tree changed during validation"
                % target,
            )
        normalized.append(normalized_record)
    _require(
        seen_targets == expected_targets,
        "literal manifest evidence does not cover the exact release targets",
    )
    _require(
        normalized == sorted(normalized, key=lambda item: item["target"]),
        "literal manifest evidence targets are not canonically ordered",
    )
    return normalized


def _audit_v2_regular_path(
    raw_path: Any,
    *,
    directory: bool,
    label: str,
) -> Path:
    _require(
        isinstance(raw_path, str) and Path(raw_path).is_absolute(),
        "%s must be an absolute path" % label,
    )
    path = Path(raw_path)
    _require(
        path.absolute() == path.resolve(),
        "%s must use its canonical path without symlink ancestors" % label,
    )
    for ancestor in (path, *path.parents):
        try:
            ancestor_mode = ancestor.lstat().st_mode
        except OSError as exc:
            raise ReleaseError("%s has a missing ancestor" % label) from exc
        _require(
            not stat_module.S_ISLNK(ancestor_mode),
            "%s traverses a symlink" % label,
        )
    try:
        mode = path.lstat().st_mode
    except OSError as exc:
        raise ReleaseError("%s is missing" % label) from exc
    _require(not stat_module.S_ISLNK(mode), "%s must not be a symlink" % label)
    if directory:
        _require(stat_module.S_ISDIR(mode), "%s must be a directory" % label)
    else:
        _require(stat_module.S_ISREG(mode), "%s must be a regular file" % label)
    return path


def _audit_v2_review_files(
    repo_root: Path,
    records: Any,
    label: str,
    *,
    expected_identifiers: set[str],
    approved_license_refs: set[str],
) -> list[dict[str, str]]:
    _require(
        isinstance(records, list) and bool(records),
        "%s has no complete license text" % label,
    )
    normalized: list[dict[str, str]] = []
    identifiers: set[str] = set()
    paths: set[tuple[str, str]] = set()
    for index, raw in enumerate(records):
        record = _exact_keys(
            raw,
            {"spdx_id", "path", "sha256"},
            "%s license text %d" % (label, index),
        )
        spdx_id = _audit_v2_nonempty(
            record["spdx_id"],
            "%s license text %d SPDX identifier" % (label, index),
        )
        _require(
            spdx_id in LICENSE_AUDIT_KNOWN_EXCEPTIONS
            or _audit_parse_spdx(spdx_id, approved_license_refs) == {spdx_id},
            "%s license text %d must name one SPDX identifier"
            % (label, index),
        )
        digest = _audit_v2_hash(
            record["sha256"],
            "%s license text %d digest" % (label, index),
        )
        path = _audit_repo_file(
            repo_root,
            record["path"],
            "%s complete license text" % label,
        )
        _require(
            _sha256_path(path) == digest,
            "%s complete license text changed" % label,
        )
        identity = (record["path"], digest)
        _require(
            spdx_id not in identifiers and identity not in paths,
            "%s duplicates a complete license text" % label,
        )
        identifiers.add(spdx_id)
        paths.add(identity)
        normalized.append(
            {
                "spdx_id": spdx_id,
                "path": record["path"],
                "sha256": digest,
            }
        )
    _require(
        identifiers == expected_identifiers,
        "%s complete license texts do not exactly cover its SPDX expression"
        % label,
    )
    return normalized


def _audit_v2_supporting_review_files(
    repo_root: Path,
    records: Any,
) -> list[dict[str, Any]]:
    _require(
        isinstance(records, list) and bool(records),
        "review_files must be a nonempty array",
    )
    identifiers: set[str] = set()
    paths: set[str] = set()
    normalized: list[dict[str, Any]] = []
    for index, raw in enumerate(records):
        record = _exact_keys(
            raw,
            {"id", "purpose", "path", "sha256", "source_identities"},
            "review file %d" % index,
        )
        identifier = _audit_v2_nonempty(
            record["id"],
            "review file %d id" % index,
        )
        purpose = _audit_v2_nonempty(
            record["purpose"],
            "review file %s purpose" % identifier,
        )
        _require(
            identifier not in identifiers,
            "review file id is duplicated",
        )
        digest = _audit_v2_hash(
            record["sha256"],
            "review file %s digest" % identifier,
        )
        path = _audit_repo_file(
            repo_root,
            record["path"],
            "review file %s" % identifier,
        )
        _require(
            record["path"] not in paths and _sha256_path(path) == digest,
            "review file %s is duplicated or changed" % identifier,
        )
        source_identities = record["source_identities"]
        _require(
            isinstance(source_identities, list)
            and bool(source_identities)
            and all(
                isinstance(value, str)
                and re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", value)
                is not None
                for value in source_identities
            )
            and len(source_identities) == len(set(source_identities)),
            "review file %s source identities are invalid" % identifier,
        )
        identifiers.add(identifier)
        paths.add(record["path"])
        normalized.append(
            {
                "id": identifier,
                "purpose": purpose,
                "path": record["path"],
                "sha256": digest,
                "source_identities": list(source_identities),
            }
        )
    return normalized


def _audit_v2_notice(
    repo_root: Path,
    raw: Any,
    label: str,
) -> dict[str, Any]:
    _require(isinstance(raw, dict), "%s NOTICE policy is invalid" % label)
    required = raw.get("required")
    _require(isinstance(required, bool), "%s NOTICE required flag is invalid" % label)
    if not required:
        _exact_keys(raw, {"required"}, "%s NOTICE" % label)
        return {"required": False}
    record = _exact_keys(
        raw,
        {"required", "path", "sha256"},
        "%s NOTICE" % label,
    )
    digest = _audit_v2_hash(record["sha256"], "%s NOTICE digest" % label)
    path = _audit_repo_file(repo_root, record["path"], "%s NOTICE" % label)
    _require(_sha256_path(path) == digest, "%s NOTICE changed" % label)
    return {
        "required": True,
        "path": record["path"],
        "sha256": digest,
    }


def _audit_v2_dependency(
    raw: Any,
    label: str,
) -> dict[str, str]:
    record = _exact_keys(
        raw,
        {"name", "version_ref", "source_url", "copyright"},
        "%s dependency" % label,
    )
    for field in ("name", "copyright"):
        _audit_v2_nonempty(record[field], "%s dependency.%s" % (label, field))
    _audit_immutable_ref(
        record["version_ref"],
        "%s dependency version_ref" % label,
    )
    _require(
        isinstance(record["source_url"], str)
        and record["source_url"].startswith("https://"),
        "%s dependency source URL is not HTTPS" % label,
    )
    commits = re.findall(r"(?<![0-9a-f])[0-9a-f]{40}(?![0-9a-f])", record["version_ref"])
    _require(
        len(commits) == 1 and commits[0] in record["source_url"],
        "%s dependency source URL is not bound to its full immutable ref" % label,
    )
    return copy.deepcopy(record)


def _audit_v2_source(
    repo_root: Path,
    raw: Any,
    label: str,
    *,
    allow_tree: bool,
) -> dict[str, Any]:
    _require(isinstance(raw, dict), "%s source metadata is invalid" % label)
    expected = {"ref", "url"}
    if allow_tree and ("tree_path" in raw or "tree_sha256" in raw):
        expected |= {"tree_path", "tree_sha256"}
    record = _exact_keys(raw, expected, "%s source" % label)
    _audit_immutable_ref(record["ref"], "%s source ref" % label)
    _require(
        isinstance(record["url"], str) and record["url"].startswith("https://"),
        "%s source URL is not immutable HTTPS metadata" % label,
    )
    if "tree_path" in record:
        relative = _safe_relative_path(
            record["tree_path"],
            "%s source tree" % label,
        )
        digest = _audit_v2_hash(
            record["tree_sha256"],
            "%s source tree digest" % label,
        )
        path = repo_root / relative
        _audit_no_symlink_components(repo_root, path, "%s source tree" % label)
        _require(
            _audit_sha256_source_tree(path, reject_python_cache=True) == digest,
            "%s source tree changed" % label,
        )
    return copy.deepcopy(record)


def _audit_v2_generated_binding(
    raw: Any,
    label: str,
) -> dict[str, Any]:
    _require(isinstance(raw, dict), "%s generated binding is invalid" % label)
    expected = {
        "component",
        "project_description_sha256",
        "compile_commands_sha256",
        "linker_map_sha256",
        "sources",
        "members",
    }
    is_main = raw.get("component") == "main"
    if is_main:
        expected.update(
            {
                "linker_command_sha256",
                "build_ninja_sha256",
                "rules_ninja_sha256",
                "metadata_inputs",
                "direct_objects",
            }
        )
    if "nested_archive" in raw:
        expected.add("nested_archive")
    binding = _exact_keys(raw, expected, "%s generated binding" % label)
    _audit_v2_nonempty(binding["component"], "%s component" % label)
    if "nested_archive" in binding:
        nested = _exact_keys(
            binding["nested_archive"],
            {
                "target",
                "archive_build_path",
                "object_build_directory",
            },
            "%s nested archive" % label,
        )
        _audit_v2_nonempty(nested["target"], "%s nested target" % label)
        for field in ("archive_build_path", "object_build_directory"):
            _safe_relative_path(
                nested[field],
                "%s nested %s" % (label, field),
            )
    for field in (
        "project_description_sha256",
        "compile_commands_sha256",
        "linker_map_sha256",
    ):
        _audit_v2_hash(binding[field], "%s %s" % (label, field))
    if is_main:
        for field in (
            "linker_command_sha256",
            "build_ninja_sha256",
            "rules_ninja_sha256",
        ):
            _audit_v2_hash(
                binding[field],
                "%s %s" % (label, field),
            )
    sources = binding["sources"]
    _require(
        isinstance(sources, list) and bool(sources),
        "%s generated binding has no compiled sources" % label,
    )
    source_paths: set[str] = set()
    for index, raw_source in enumerate(sources):
        source = _exact_keys(
            raw_source,
            {"path", "sha256"},
            "%s source %d" % (label, index),
        )
        source_path = _safe_relative_path(
            source["path"],
            "%s source path" % label,
        )
        _audit_v2_hash(source["sha256"], "%s source digest" % label)
        _require(
            source_path not in source_paths,
            "%s generated binding duplicates a source" % label,
        )
        source_paths.add(source_path)
    members = binding["members"]
    _require(
        isinstance(members, list)
        and bool(members)
        and all(isinstance(member, str) and member for member in members),
        "%s generated archive member multiset is invalid" % label,
    )
    if is_main:
        metadata_inputs = binding["metadata_inputs"]
        _require(
            isinstance(metadata_inputs, list),
            "%s generated metadata inputs are invalid" % label,
        )
        metadata_paths: set[str] = set()
        for index, raw_metadata in enumerate(metadata_inputs):
            metadata = _exact_keys(
                raw_metadata,
                {"path", "sha256"},
                "%s metadata input %d" % (label, index),
            )
            metadata_path = _safe_relative_path(
                metadata["path"],
                "%s metadata input path" % label,
            )
            _audit_v2_hash(
                metadata["sha256"],
                "%s metadata input digest" % label,
            )
            _require(
                metadata_path not in metadata_paths,
                "%s generated binding duplicates a metadata input" % label,
            )
            metadata_paths.add(metadata_path)
        _require(
            metadata_inputs
            == sorted(metadata_inputs, key=lambda item: item["path"]),
            "%s metadata inputs are not canonical" % label,
        )

        direct_objects = binding["direct_objects"]
        _require(
            isinstance(direct_objects, list) and bool(direct_objects),
            "%s generated direct-object inventory is empty" % label,
        )
        direct_output_paths: set[str] = set()
        for index, raw_direct in enumerate(direct_objects):
            direct = _exact_keys(
                raw_direct,
                {"output", "source"},
                "%s direct object %d" % (label, index),
            )
            for field in ("output", "source"):
                record = _exact_keys(
                    direct[field],
                    {"path", "sha256"},
                    "%s direct object %d %s" % (label, index, field),
                )
                logical_path = _safe_relative_path(
                    record["path"],
                    "%s direct object %s path" % (label, field),
                )
                _audit_v2_hash(
                    record["sha256"],
                    "%s direct object %s digest" % (label, field),
                )
                if field == "output":
                    _require(
                        logical_path.startswith("build/"),
                        "%s direct object output is not a build path" % label,
                    )
                    _require(
                        logical_path not in direct_output_paths,
                        "%s generated binding duplicates a direct output" % label,
                    )
                    direct_output_paths.add(logical_path)
        _require(
            direct_objects
            == sorted(
                direct_objects,
                key=lambda item: item["output"]["path"],
            ),
            "%s direct objects are not canonical" % label,
        )
    return copy.deepcopy(binding)


def _audit_v2_generated_matcher(
    raw: Any,
    label: str,
) -> dict[str, Any]:
    """Validate the stable, build-independent selector committed in policy."""

    _require(isinstance(raw, dict), "%s generated matcher is invalid" % label)
    expected = {"component"}
    if "nested_archive" in raw:
        expected.add("nested_archive")
    matcher = _exact_keys(raw, expected, "%s generated matcher" % label)
    _audit_v2_nonempty(matcher["component"], "%s component" % label)
    if "nested_archive" in matcher:
        nested = _exact_keys(
            matcher["nested_archive"],
            {
                "target",
                "archive_build_path",
                "object_build_directory",
            },
            "%s nested archive matcher" % label,
        )
        _audit_v2_nonempty(nested["target"], "%s nested target" % label)
        for field in ("archive_build_path", "object_build_directory"):
            _safe_relative_path(
                nested[field],
                "%s nested %s" % (label, field),
            )
    return copy.deepcopy(matcher)


def _audit_v2_observed_documents(
    observed_documents: Any,
) -> tuple[
    dict[tuple[str, str], dict[str, Any]],
    dict[tuple[str, str, str], dict[str, Any]],
]:
    _require(
        isinstance(observed_documents, dict),
        "observed SPDX documents must be a mapping",
    )
    documents: dict[tuple[str, str], dict[str, Any]] = {}
    raw_packages: dict[tuple[str, str, str], dict[str, Any]] = {}
    for raw_identity, raw_document in observed_documents.items():
        if (
            isinstance(raw_identity, tuple)
            and len(raw_identity) == 2
            and all(isinstance(item, str) for item in raw_identity)
        ):
            profile_id, role = raw_identity
        elif isinstance(raw_identity, str) and raw_identity.count("/") == 1:
            profile_id, role = raw_identity.split("/", 1)
        else:
            raise ReleaseError("observed SPDX document identity is invalid")
        identity = _audit_v2_identity(
            profile_id,
            role,
            "observed SPDX document",
        )
        _require(
            identity not in documents,
            "observed SPDX document identity is duplicated",
        )
        _require(
            isinstance(raw_document, dict),
            "observed SPDX document is not an object",
        )
        packages = raw_document.get("packages")
        relationships = raw_document.get("relationships")
        _require(
            isinstance(packages, list) and bool(packages),
            "observed SPDX document contains no packages",
        )
        _require(
            isinstance(relationships, list) and bool(relationships),
            "observed SPDX document contains no relationships",
        )
        package_ids: set[str] = set()
        for package in packages:
            _require(isinstance(package, dict), "observed SPDX package is invalid")
            required = {
                "name",
                "SPDXID",
                "downloadLocation",
                "filesAnalyzed",
                "licenseConcluded",
                "licenseDeclared",
                "copyrightText",
            }
            _require(
                required <= set(package),
                "observed SPDX package property set is incomplete",
            )
            if "versionInfo" in package:
                _require(
                    isinstance(package["versionInfo"], str)
                    and bool(package["versionInfo"]),
                    "observed SPDX package versionInfo is explicitly empty",
                )
            spdx_id = package["SPDXID"]
            _require(
                isinstance(spdx_id, str)
                and _AUDIT_SPDX_ELEMENT_RE.fullmatch(spdx_id) is not None
                and spdx_id != "SPDXRef-DOCUMENT"
                and spdx_id not in package_ids,
                "observed SPDX package ID is invalid or duplicated",
            )
            _audit_v2_canonical(package, "observed SPDX package")
            package_ids.add(spdx_id)
            raw_packages[(identity[0], identity[1], spdx_id)] = copy.deepcopy(package)
        known_elements = {"SPDXRef-DOCUMENT"} | package_ids
        for relationship in relationships:
            relation = _exact_keys(
                relationship,
                {
                    "spdxElementId",
                    "relationshipType",
                    "relatedSpdxElement",
                },
                "observed SPDX relationship",
            )
            _require(
                all(
                    isinstance(relation[field], str) and relation[field]
                    for field in relation
                )
                and relation["spdxElementId"] in known_elements
                and relation["relatedSpdxElement"] in known_elements,
                "observed SPDX relationship names an unknown element",
            )
        documents[identity] = {
            "packages": copy.deepcopy(packages),
            "relationships": copy.deepcopy(relationships),
        }
    expected_identities = {
        (profile_id, role)
        for profile_id, _target, _idf_target in LICENSE_AUDIT_PROFILES
        for role in LICENSE_AUDIT_ROLES
    }
    _require(
        set(documents) == expected_identities,
        "observed SPDX documents do not cover the exact six profile/roles",
    )
    return documents, raw_packages


def _audit_v2_observed_inputs(
    observed_inputs: Any,
) -> tuple[dict[str, dict[str, Any]], dict[str, str]]:
    _require(
        isinstance(observed_inputs, list) and bool(observed_inputs),
        "observed redistributed inputs must be a nonempty array",
    )
    records: dict[str, dict[str, Any]] = {}
    hashes: dict[str, str] = {}
    frozen_destination_owners: set[tuple[str, str, str]] = set()
    common = {
        "id",
        "profile_id",
        "role",
        "kind",
        "observed_path",
        "sha256",
    }
    kind_fields = {
        "generated-component-archive": {"generated_binding"},
        "generated-supplemental-archive": {"generated_binding"},
        "opaque-archive": {"reviewed_source_path"},
        "toolchain-archive": {
            "toolchain_id",
            "relative_path",
            "compiler_paths",
        },
        "frozen-source-tree": {"frozen_destinations"},
    }
    for raw in observed_inputs:
        _require(isinstance(raw, dict), "observed redistributed input is invalid")
        kind = raw.get("kind")
        _require(
            kind in _AUDIT_POLICY_V2_INPUT_KINDS,
            "observed redistributed input kind is unsupported",
        )
        record = _exact_keys(
            raw,
            common | kind_fields[kind],
            "observed redistributed input",
        )
        identifier = _audit_v2_nonempty(
            record["id"],
            "observed redistributed input id",
        )
        _require(
            identifier not in records,
            "observed redistributed input id is duplicated",
        )
        _audit_v2_identity(
            record["profile_id"],
            record["role"],
            "observed redistributed input %s" % identifier,
        )
        directory = kind == "frozen-source-tree"
        path = _audit_v2_regular_path(
            record["observed_path"],
            directory=directory,
            label="observed redistributed input %s" % identifier,
        )
        actual_digest = _audit_sha256_tree(path) if directory else _sha256_path(path)
        declared_digest = _audit_v2_hash(
            record["sha256"],
            "observed redistributed input %s digest" % identifier,
        )
        _require(
            actual_digest == declared_digest,
            "observed redistributed input %s changed" % identifier,
        )
        if kind.startswith("generated-"):
            _audit_v2_generated_binding(
                record["generated_binding"],
                "observed redistributed input %s" % identifier,
            )
        elif kind == "opaque-archive":
            _safe_relative_path(
                record["reviewed_source_path"],
                "observed opaque source",
            )
        elif kind == "toolchain-archive":
            _audit_v2_nonempty(
                record["toolchain_id"],
                "observed toolchain id",
            )
            _safe_relative_path(
                record["relative_path"],
                "observed toolchain archive",
            )
            compiler_paths = record["compiler_paths"]
            _require(
                isinstance(compiler_paths, list)
                and bool(compiler_paths)
                and all(
                    isinstance(compiler_path, str)
                    and Path(compiler_path).is_absolute()
                    for compiler_path in compiler_paths
                )
                and compiler_paths == sorted(compiler_paths)
                and len(compiler_paths) == len(set(compiler_paths)),
                "observed toolchain compiler paths are invalid",
            )
        else:
            destinations = record["frozen_destinations"]
            _require(
                isinstance(destinations, list)
                and bool(destinations)
                and all(
                    isinstance(destination, str)
                    and _safe_relative_path(
                        destination,
                        "frozen destination",
                    )
                    == destination
                    for destination in destinations
                )
                and len(destinations) == len(set(destinations)),
                "observed frozen destination inventory is invalid",
            )
            destination_owners = {
                (record["profile_id"], record["role"], destination)
                for destination in destinations
            }
            _require(
                frozen_destination_owners.isdisjoint(destination_owners),
                "observed frozen destination has more than one owner",
            )
            frozen_destination_owners.update(destination_owners)
        records[identifier] = copy.deepcopy(record)
        hashes[identifier] = actual_digest
    return records, dict(sorted(hashes.items()))


def _audit_v2_distribution_members(
    source: bytes | Path,
    *,
    root_name: str,
    required_paths: set[str],
    label: str,
) -> dict[str, dict[str, Any]]:
    try:
        if isinstance(source, Path):
            archive = tarfile.open(name=source, mode="r:xz")
        else:
            archive = tarfile.open(fileobj=io.BytesIO(source), mode="r:xz")
    except (tarfile.TarError, EOFError, OSError) as exc:
        raise ReleaseError("%s is not a valid tar.xz archive" % label) from exc
    members: dict[str, tarfile.TarInfo] = {}
    regular: dict[str, tarfile.TarInfo] = {}
    links: dict[str, str] = {}
    total_size = 0
    with archive:
        infos = archive.getmembers()
        _require(
            0 < len(infos) <= 250_000,
            "%s has an unsafe member count" % label,
        )
        for info in infos:
            name = info.name
            pure = PurePosixPath(name)
            _require(
                "\\" not in name
                and not pure.is_absolute()
                and all(part not in ("", ".", "..") for part in pure.parts)
                and pure.as_posix() == name,
                "%s contains an unsafe path" % label,
            )
            if info.isdir() and len(pure.parts) == 1:
                _require(
                    pure.parts[0] == root_name,
                    "%s contains a directory outside its declared root" % label,
                )
                continue
            _require(
                len(pure.parts) >= 2 and pure.parts[0] == root_name,
                "%s contains a path outside its declared root" % label,
            )
            relative = PurePosixPath(*pure.parts[1:]).as_posix()
            if info.isdir():
                continue
            _require(
                relative not in members,
                "%s contains a duplicate path" % label,
            )
            members[relative] = info
            if info.isfile():
                _require(
                    0 <= info.size <= 1024 * 1024 * 1024,
                    "%s contains an oversized member" % label,
                )
                total_size += info.size
                _require(
                    total_size <= 4 * 1024 * 1024 * 1024,
                    "%s expands beyond the audit safety limit" % label,
                )
                regular[relative] = info
                continue
            _require(
                info.issym() or info.islnk(),
                "%s contains a special file" % label,
            )
            link = PurePosixPath(info.linkname)
            if info.issym():
                target = PurePosixPath(relative).parent / link
            else:
                target = link
                if target.parts and target.parts[0] == root_name:
                    target = PurePosixPath(*target.parts[1:])
            normalized_parts: list[str] = []
            for part in target.parts:
                if part in ("", "."):
                    continue
                if part == "..":
                    _require(
                        bool(normalized_parts),
                        "%s link escapes its declared root" % label,
                    )
                    normalized_parts.pop()
                else:
                    normalized_parts.append(part)
            _require(
                not target.is_absolute() and bool(normalized_parts),
                "%s contains an unsafe link target" % label,
            )
            links[relative] = PurePosixPath(*normalized_parts).as_posix()

        for relative, target in links.items():
            seen = {relative}
            while target in links:
                _require(
                    target not in seen,
                    "%s contains a link cycle" % label,
                )
                seen.add(target)
                target = links[target]
            _require(
                target in regular,
                "%s link target is missing or not regular" % label,
            )

        _require(bool(regular), "%s contains no regular files" % label)
        results: dict[str, dict[str, Any]] = {}
        for relative in sorted(required_paths):
            _require(
                relative in members,
                "%s omits a required member" % label,
            )
            target = relative
            while target in links:
                target = links[target]
            info = regular.get(target)
            _require(
                info is not None,
                "%s required member is not regular" % label,
            )
            extracted = archive.extractfile(info)
            _require(extracted is not None, "%s member is unreadable" % label)
            digest = hashlib.sha256()
            size = 0
            while True:
                chunk = extracted.read(1024 * 1024)
                if not chunk:
                    break
                size += len(chunk)
                _require(
                    size <= info.size,
                    "%s member exceeds its declared size" % label,
                )
                digest.update(chunk)
            _require(size == info.size, "%s member is truncated" % label)
            results[relative] = {
                "size": size,
                "sha256": digest.hexdigest(),
            }
    return results


def _audit_v2_compiler_frontends(
    raw: Any,
    label: str,
) -> list[dict[str, str]]:
    _require(
        isinstance(raw, list) and bool(raw),
        "%s compiler_frontends must be a nonempty array" % label,
    )
    records: list[dict[str, str]] = []
    for index, value in enumerate(raw):
        frontend = _exact_keys(
            value,
            {"relative_path", "sha256"},
            "%s compiler frontend %d" % (label, index),
        )
        relative = _safe_relative_path(
            frontend["relative_path"],
            "%s compiler frontend %d" % (label, index),
        )
        digest = _audit_v2_hash(
            frontend["sha256"],
            "%s compiler frontend %d digest" % (label, index),
        )
        records.append(
            {
                "relative_path": relative,
                "sha256": digest,
            }
        )
    relative_paths = [record["relative_path"] for record in records]
    _require(
        relative_paths == sorted(relative_paths)
        and len(relative_paths) == len(set(relative_paths)),
        "%s compiler_frontends must be unique and sorted by relative_path"
        % label,
    )
    frontend_names = {Path(relative).name for relative in relative_paths}
    gcc_prefixes = {
        name[: -len("-gcc")]
        for name in frontend_names
        if name.endswith("-gcc")
    }
    gxx_prefixes = {
        name[: -len("-g++")]
        for name in frontend_names
        if name.endswith("-g++")
    }
    _require(
        len(records) == 2
        and len(gcc_prefixes) == 1
        and gcc_prefixes == gxx_prefixes,
        "%s compiler_frontends must contain exactly one matched gcc/g++ pair"
        % label,
    )
    return records


def _audit_v2_derive_toolchain_cache_context(
    policy: dict[str, Any],
    *,
    repo_root: Path,
    compiler_paths: set[Path],
) -> dict[str, dict[str, str]]:
    """Derive private tool/cache paths from reviewed policy and compiler paths."""

    _require(isinstance(policy, dict), "toolchain cache policy is invalid")
    policy_records = policy.get("toolchains")
    _require(isinstance(policy_records, list), "toolchains must be an array")
    _require(
        isinstance(compiler_paths, set) and bool(compiler_paths),
        "observed toolchain compiler set is invalid",
    )
    observed_compilers: set[Path] = set()
    for raw_path in compiler_paths:
        compiler = _audit_v2_regular_path(
            str(raw_path),
            directory=False,
            label="observed toolchain compiler",
        )
        _require(
            compiler not in observed_compilers,
            "observed toolchain compiler is duplicated",
        )
        observed_compilers.add(compiler)

    contexts: dict[str, dict[str, str]] = {}
    consumed_compilers: set[Path] = set()
    for raw in policy_records:
        record = _exact_keys(
            raw,
            {
                "id",
                "name",
                "version",
                "platform",
                "install_root_relative",
                "compiler_frontends",
                "distribution",
                "metadata",
                "admitted_archive_paths",
            },
            "toolchain policy",
        )
        identifier = _audit_v2_nonempty(record["id"], "toolchain id")
        _require(identifier not in contexts, "toolchain id is duplicated")
        name = _audit_v2_nonempty(record["name"], "toolchain %s name" % identifier)
        version = _audit_v2_nonempty(
            record["version"],
            "toolchain %s version" % identifier,
        )
        platform_name = _audit_v2_nonempty(
            record["platform"],
            "toolchain %s platform" % identifier,
        )

        compiler_frontends = _audit_v2_compiler_frontends(
            record["compiler_frontends"],
            "toolchain %s" % identifier,
        )

        distribution = _exact_keys(
            record["distribution"],
            {
                "url",
                "filename",
                "size",
                "sha256",
                "archive_format",
                "archive_root",
            },
            "toolchain %s distribution" % identifier,
        )
        distribution_url = distribution["url"]
        _require(
            isinstance(distribution_url, str),
            "toolchain %s distribution URL is invalid" % identifier,
        )
        parsed_url = urlsplit(distribution_url)
        _require(
            parsed_url.scheme == "https"
            and bool(parsed_url.netloc)
            and not parsed_url.query
            and not parsed_url.fragment,
            "toolchain %s distribution URL is not canonical HTTPS" % identifier,
        )
        filename = _safe_relative_path(
            distribution["filename"],
            "toolchain %s distribution filename" % identifier,
        )
        _require(
            "/" not in filename
            and parsed_url.path.rsplit("/", 1)[-1] == filename,
            "toolchain %s distribution filename disagrees with its URL"
            % identifier,
        )
        archive_root = _safe_relative_path(
            distribution["archive_root"],
            "toolchain %s distribution archive root" % identifier,
        )
        _require(
            "/" not in archive_root
            and distribution["archive_format"] == "tar.xz",
            "toolchain %s distribution identity changed" % identifier,
        )
        distribution_digest = _audit_v2_hash(
            distribution["sha256"],
            "toolchain %s distribution digest" % identifier,
        )
        _require(
            isinstance(distribution["size"], int)
            and not isinstance(distribution["size"], bool)
            and distribution["size"] > 0,
            "toolchain %s distribution size is invalid" % identifier,
        )

        install_relative = _safe_relative_path(
            record["install_root_relative"],
            "toolchain %s installed root" % identifier,
        )
        _require(
            PurePosixPath(install_relative).parts
            == ("tools", name, version, archive_root),
            "toolchain %s installed root disagrees with its reviewed identity"
            % identifier,
        )
        frontend_paths: list[Path] = []
        tools_homes: set[Path] = set()
        for frontend in compiler_frontends:
            frontend_relative = frontend["relative_path"]
            frontend_suffix = Path(install_relative) / frontend_relative
            suffix_parts = frontend_suffix.parts
            matches = {
                compiler
                for compiler in observed_compilers
                if len(compiler.parts) > len(suffix_parts)
                and compiler.parts[-len(suffix_parts) :] == suffix_parts
            }
            _require(
                len(matches) == 1,
                "toolchain %s compiler frontend does not select one trusted "
                "installation" % identifier,
            )
            frontend_path = next(iter(matches))
            _require(
                frontend_path not in consumed_compilers
                and _sha256_path(frontend_path) == frontend["sha256"],
                "toolchain %s compiler frontend identity changed" % identifier,
            )
            consumed_compilers.add(frontend_path)
            frontend_paths.append(frontend_path)
            tools_home_candidate = frontend_path
            for _part in suffix_parts:
                tools_home_candidate = tools_home_candidate.parent
            tools_homes.add(tools_home_candidate)
        _require(
            len(tools_homes) == 1,
            "toolchain %s compiler frontends do not share one trusted tools "
            "home" % identifier,
        )
        tools_home = next(iter(tools_homes))
        tools_home = _audit_v2_regular_path(
            str(tools_home),
            directory=True,
            label="toolchain %s tools home" % identifier,
        )
        tools_dir = _audit_v2_regular_path(
            str(tools_home / "tools"),
            directory=True,
            label="toolchain %s installed tools directory" % identifier,
        )
        installed_root = _audit_v2_regular_path(
            str(tools_home / install_relative),
            directory=True,
            label="toolchain %s installed root" % identifier,
        )
        _require(
            tools_dir == tools_home / "tools"
            and frontend_paths
            == [
                installed_root / frontend["relative_path"]
                for frontend in compiler_frontends
            ],
            "toolchain %s compiler frontends escaped their reviewed "
            "installation" % identifier,
        )

        metadata_record = _exact_keys(
            record["metadata"],
            {"path", "sha256"},
            "toolchain %s metadata" % identifier,
        )
        metadata_digest = _audit_v2_hash(
            metadata_record["sha256"],
            "toolchain %s metadata digest" % identifier,
        )
        metadata_path = _audit_repo_file(
            repo_root,
            metadata_record["path"],
            "toolchain %s ESP-IDF metadata" % identifier,
        )
        _require(
            _sha256_path(metadata_path) == metadata_digest,
            "toolchain %s ESP-IDF metadata changed" % identifier,
        )
        metadata = _read_json(
            metadata_path,
            "toolchain %s ESP-IDF metadata" % identifier,
        )
        tools = metadata.get("tools") if isinstance(metadata, dict) else None
        _require(
            isinstance(tools, list),
            "toolchain %s ESP-IDF metadata has no tool inventory" % identifier,
        )
        tool_matches = [
            item
            for item in tools
            if isinstance(item, dict) and item.get("name") == name
        ]
        _require(
            len(tool_matches) == 1,
            "toolchain %s ESP-IDF metadata identity is ambiguous" % identifier,
        )
        tool_metadata = tool_matches[0]
        versions = tool_metadata.get("versions")
        _require(
            isinstance(versions, list),
            "toolchain %s ESP-IDF metadata has no versions" % identifier,
        )
        version_matches = [
            item
            for item in versions
            if isinstance(item, dict) and item.get("name") == version
        ]
        _require(
            len(version_matches) == 1,
            "toolchain %s ESP-IDF metadata version is ambiguous" % identifier,
        )
        platform_distribution = version_matches[0].get(platform_name)
        platform_distribution = _exact_keys(
            platform_distribution,
            {"url", "size", "sha256"},
            "toolchain %s ESP-IDF platform distribution" % identifier,
        )
        _require(
            platform_distribution
            == {
                "url": distribution_url,
                "size": distribution["size"],
                "sha256": distribution_digest,
            },
            "toolchain %s policy disagrees with ESP-IDF distribution metadata"
            % identifier,
        )
        frontend_export_directories = {
            PurePosixPath(frontend["relative_path"]).parts[0]
            for frontend in compiler_frontends
        }
        _require(
            len(frontend_export_directories) == 1,
            "toolchain %s compiler frontend export directories changed"
            % identifier,
        )
        expected_export = [archive_root, next(iter(frontend_export_directories))]
        _require(
            tool_metadata.get("export_paths") == [expected_export],
            "toolchain %s ESP-IDF export path changed" % identifier,
        )

        dist_dir = _audit_v2_regular_path(
            str(tools_home / "dist"),
            directory=True,
            label="toolchain %s distribution cache directory" % identifier,
        )
        cache_path = _audit_v2_regular_path(
            str(dist_dir / filename),
            directory=False,
            label="toolchain %s cached distribution" % identifier,
        )
        _require(
            cache_path.stat().st_size == distribution["size"]
            and _sha256_path(cache_path) == distribution_digest,
            "toolchain %s cached distribution changed" % identifier,
        )
        distribution_frontends = _audit_v2_distribution_members(
            cache_path,
            root_name=archive_root,
            required_paths={
                frontend["relative_path"] for frontend in compiler_frontends
            },
            label="toolchain %s cached distribution" % identifier,
        )
        for frontend, frontend_path in zip(
            compiler_frontends,
            frontend_paths,
        ):
            distribution_frontend = distribution_frontends.get(
                frontend["relative_path"]
            )
            _require(
                distribution_frontend is not None
                and frontend_path.stat().st_size
                == distribution_frontend["size"]
                and _sha256_path(frontend_path)
                == distribution_frontend["sha256"],
                "toolchain %s compiler frontend differs from its distribution"
                % identifier,
            )
        contexts[identifier] = {
            "root": str(installed_root),
            "trusted_anchor": str(tools_home),
            "root_relative": install_relative,
            "distribution_cache_path": str(cache_path),
            "distribution_cache_relative": "dist/%s" % filename,
        }

    _require(
        consumed_compilers == observed_compilers,
        "observed compiler set does not exactly match reviewed toolchains",
    )
    return contexts


def _audit_v2_toolchains(
    *,
    policy_records: Any,
    repo_root: Path,
    observed_inputs: dict[str, dict[str, Any]],
    toolchain_roots: Any,
) -> dict[str, dict[str, Any]]:
    _require(isinstance(policy_records, list), "toolchains must be an array")
    toolchain_observations = [
        record
        for record in observed_inputs.values()
        if record["kind"] == "toolchain-archive"
    ]
    declared_id_values: list[str] = []
    for record in policy_records:
        _require(
            isinstance(record, dict)
            and isinstance(record.get("id"), str)
            and bool(record["id"]),
            "toolchain policy id is invalid",
        )
        declared_id_values.append(record["id"])
    _require(
        len(declared_id_values) == len(set(declared_id_values)),
        "toolchain policy id is duplicated",
    )
    declared_ids = set(declared_id_values)
    _require(
        isinstance(toolchain_roots, dict)
        and all(isinstance(identifier, str) for identifier in toolchain_roots)
        and set(toolchain_roots) == declared_ids,
        "verified toolchain roots do not match policy",
    )
    validated: dict[str, dict[str, Any]] = {}
    for raw in policy_records:
        record = _exact_keys(
            raw,
            {
                "id",
                "name",
                "version",
                "platform",
                "install_root_relative",
                "compiler_frontends",
                "distribution",
                "metadata",
                "admitted_archive_paths",
            },
            "toolchain policy",
        )
        identifier = _audit_v2_nonempty(record["id"], "toolchain id")
        _require(identifier not in validated, "toolchain id is duplicated")
        for field in ("name", "version", "platform", "install_root_relative"):
            _audit_v2_nonempty(record[field], "toolchain %s %s" % (identifier, field))
        raw_context = toolchain_roots[identifier]
        _require(
            isinstance(raw_context, dict),
            "toolchain %s root lacks collector-verified context" % identifier,
        )
        context = _exact_keys(
            raw_context,
            {
                "root",
                "trusted_anchor",
                "root_relative",
                "distribution_cache_path",
                "distribution_cache_relative",
            },
            "toolchain %s verified root context" % identifier,
        )
        root = Path(context["root"])
        trusted_anchor = Path(context["trusted_anchor"])
        root_relative = _safe_relative_path(
            context["root_relative"],
            "toolchain %s trusted root relative path" % identifier,
        )
        _require(
            root.is_absolute()
            and trusted_anchor.is_absolute()
            and root == trusted_anchor / root_relative
            and root.absolute() == root.resolve()
            and trusted_anchor.absolute() == trusted_anchor.resolve(),
            "toolchain %s root is not collector-bound to its trusted anchor"
            % identifier,
        )
        for ancestor in (trusted_anchor, *trusted_anchor.parents):
            try:
                ancestor_mode = ancestor.lstat().st_mode
            except OSError as exc:
                raise ReleaseError(
                    "toolchain %s trusted anchor is missing" % identifier
                ) from exc
            _require(
                not stat_module.S_ISLNK(ancestor_mode),
                "toolchain %s trusted anchor traverses a symlink" % identifier,
            )
        _audit_no_symlink_components(
            trusted_anchor,
            root,
            "toolchain %s root" % identifier,
        )
        try:
            root_mode = root.lstat().st_mode
        except OSError as exc:
            raise ReleaseError("toolchain %s root is missing" % identifier) from exc
        _require(
            stat_module.S_ISDIR(root_mode)
            and not stat_module.S_ISLNK(root_mode)
            and root_relative == record["install_root_relative"],
            "toolchain %s root identity is not the reviewed version" % identifier,
        )

        compiler_frontends = _audit_v2_compiler_frontends(
            record["compiler_frontends"],
            "toolchain %s" % identifier,
        )
        frontend_paths: list[Path] = []
        for frontend in compiler_frontends:
            frontend_path = root / frontend["relative_path"]
            _audit_no_symlink_components(
                root,
                frontend_path,
                "toolchain %s compiler frontend" % identifier,
            )
            try:
                frontend_mode = frontend_path.lstat().st_mode
            except OSError as exc:
                raise ReleaseError(
                    "toolchain %s compiler frontend is missing" % identifier
                ) from exc
            _require(
                stat_module.S_ISREG(frontend_mode)
                and not stat_module.S_ISLNK(frontend_mode)
                and _sha256_path(frontend_path) == frontend["sha256"],
                "toolchain %s compiler frontend identity changed" % identifier,
            )
            frontend_paths.append(frontend_path)

        admitted = record["admitted_archive_paths"]
        _require(
            isinstance(admitted, list)
            and bool(admitted)
            and all(isinstance(path, str) for path in admitted),
            "toolchain %s admitted archive paths are invalid" % identifier,
        )
        admitted_paths = [
            _safe_relative_path(
                path,
                "toolchain %s admitted archive" % identifier,
            )
            for path in admitted
        ]
        _require(
            len(admitted_paths) == len(set(admitted_paths)),
            "toolchain %s admitted archive path is duplicated" % identifier,
        )

        metadata = _exact_keys(
            record["metadata"],
            {"path", "sha256"},
            "toolchain %s metadata" % identifier,
        )
        metadata_digest = _audit_v2_hash(
            metadata["sha256"],
            "toolchain %s metadata digest" % identifier,
        )
        metadata_path = _audit_repo_file(
            repo_root,
            metadata["path"],
            "toolchain %s ESP-IDF metadata" % identifier,
        )
        _require(
            _sha256_path(metadata_path) == metadata_digest,
            "toolchain %s ESP-IDF metadata changed" % identifier,
        )

        distribution = _exact_keys(
            record["distribution"],
            {
                "url",
                "filename",
                "size",
                "sha256",
                "archive_format",
                "archive_root",
            },
            "toolchain %s distribution" % identifier,
        )
        _require(
            isinstance(distribution["url"], str)
            and distribution["url"].startswith("https://"),
            "toolchain %s distribution URL is not HTTPS" % identifier,
        )
        distribution_filename = _safe_relative_path(
            distribution["filename"],
            "toolchain %s distribution filename" % identifier,
        )
        distribution_root = _safe_relative_path(
            distribution["archive_root"],
            "toolchain %s distribution archive root" % identifier,
        )
        _require(
            "/" not in distribution_filename
            and "/" not in distribution_root
            and urlsplit(distribution["url"]).path.rsplit("/", 1)[-1]
            == distribution_filename
            and distribution["archive_format"] == "tar.xz",
            "toolchain %s distribution identity changed" % identifier,
        )
        distribution_path = _audit_v2_regular_path(
            context["distribution_cache_path"],
            directory=False,
            label="toolchain %s cached distribution" % identifier,
        )
        distribution_relative = _safe_relative_path(
            context["distribution_cache_relative"],
            "toolchain %s cached distribution" % identifier,
        )
        _require(
            distribution_relative == "dist/%s" % distribution_filename
            and distribution_path == trusted_anchor / distribution_relative,
            "toolchain %s cached distribution is not collector-bound"
            % identifier,
        )
        distribution_digest = _audit_v2_hash(
            distribution["sha256"],
            "toolchain %s distribution digest" % identifier,
        )
        _require(
            isinstance(distribution["size"], int)
            and not isinstance(distribution["size"], bool)
            and distribution["size"] > 0
            and distribution_path.stat().st_size == distribution["size"]
            and _sha256_path(distribution_path) == distribution_digest,
            "toolchain %s cached distribution changed" % identifier,
        )
        distribution_members = _audit_v2_distribution_members(
            distribution_path,
            root_name=distribution_root,
            required_paths={
                *(frontend["relative_path"] for frontend in compiler_frontends),
                *admitted_paths,
            },
            label="toolchain %s cached distribution" % identifier,
        )
        for frontend, frontend_path in zip(
            compiler_frontends,
            frontend_paths,
        ):
            frontend_distribution = distribution_members.get(
                frontend["relative_path"]
            )
            _require(
                frontend_distribution is not None
                and frontend_path.stat().st_size
                == frontend_distribution["size"]
                and _sha256_path(frontend_path)
                == frontend_distribution["sha256"],
                "toolchain %s compiler frontend differs from its distribution"
                % identifier,
            )

        for relative in admitted_paths:
            installed = root / relative
            _audit_no_symlink_components(
                root,
                installed,
                "toolchain %s admitted archive" % identifier,
            )
            try:
                mode = installed.lstat().st_mode
            except OSError as exc:
                raise ReleaseError(
                    "toolchain %s admitted archive is missing" % identifier
                ) from exc
            distribution_member = distribution_members.get(relative)
            _require(
                stat_module.S_ISREG(mode)
                and not stat_module.S_ISLNK(mode)
                and distribution_member is not None
                and installed.stat().st_size == distribution_member["size"]
                and _sha256_path(installed) == distribution_member["sha256"],
                "toolchain %s archive differs from its distribution" % identifier,
            )

        matching_observations = [
            observation
            for observation in toolchain_observations
            if observation["toolchain_id"] == identifier
        ]
        _require(
            bool(matching_observations),
            "toolchain %s has no observed input" % identifier,
        )
        observed_relatives = {
            observation["relative_path"] for observation in matching_observations
        }
        _require(
            observed_relatives == set(admitted_paths),
            "toolchain %s observed archive set changed" % identifier,
        )
        expected_frontend_paths = set(frontend_paths)
        observed_frontend_paths: set[Path] = set()
        for observation in matching_observations:
            relative = observation["relative_path"]
            observed_path = Path(observation["observed_path"])
            observation_frontends = [
                _audit_v2_regular_path(
                    compiler_path,
                    directory=False,
                    label="toolchain %s observed compiler frontend"
                    % identifier,
                )
                for compiler_path in observation["compiler_paths"]
            ]
            _require(
                observed_path.resolve() == (root / relative).resolve()
                and bool(observation_frontends)
                and set(observation_frontends) <= expected_frontend_paths,
                "toolchain %s observation comes from an unreviewed root" % identifier,
            )
            observed_frontend_paths.update(observation_frontends)
        _require(
            observed_frontend_paths == expected_frontend_paths,
            "toolchain %s observed compiler frontend set changed" % identifier,
        )
        validated[identifier] = {
            "id": identifier,
            "name": record["name"],
            "version": record["version"],
            "platform": record["platform"],
            "install_root_relative": record["install_root_relative"],
            "compiler_frontends": copy.deepcopy(compiler_frontends),
            "metadata_path": metadata["path"],
            "metadata_sha256": metadata_digest,
            "distribution_url": distribution["url"],
            "distribution_filename": distribution_filename,
            "distribution_archive_root": distribution_root,
            "distribution_size": distribution["size"],
            "distribution_sha256": distribution_digest,
            "admitted_archive_paths": admitted_paths,
        }
    observed_toolchain_ids = {
        observation["toolchain_id"] for observation in toolchain_observations
    }
    _require(
        observed_toolchain_ids == set(validated),
        "observed toolchain input lacks exact reviewed policy",
    )
    return validated


def _audit_v2_zero_input_proof(
    raw: Any,
    *,
    package_refs: list[dict[str, str]],
    reviewed_package_id: str,
    observed_inputs: dict[str, dict[str, Any]],
    policy_inputs: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    proof = _exact_keys(
        raw,
        {"profile_roles"},
        "not-shipped zero-input proof",
    )
    records = proof["profile_roles"]
    _require(
        isinstance(records, list) and bool(records),
        "not-shipped zero-input proof has no profile/role records",
    )
    expected_identities = {
        (ref["profile_id"], ref["role"]) for ref in package_refs
    }
    normalized: list[dict[str, Any]] = []
    observed_identities: set[tuple[str, str]] = set()
    for raw_record in records:
        record = _exact_keys(
            raw_record,
            {
                "profile_id",
                "role",
                "matched_input_ids",
            },
            "not-shipped zero-input proof record",
        )
        identity = _audit_v2_identity(
            record["profile_id"],
            record["role"],
            "not-shipped zero-input proof",
        )
        _require(
            identity not in observed_identities,
            "not-shipped zero-input proof duplicates a profile/role",
        )
        observed_identities.add(identity)
        matched = record["matched_input_ids"]
        _require(
            isinstance(matched, list)
            and all(isinstance(item, str) and item for item in matched)
            and len(matched) == len(set(matched)),
            "not-shipped zero-input matched input IDs are invalid",
        )
        expected_matched = sorted(
            identifier
            for identifier, policy_input in policy_inputs.items()
            if policy_input["reviewed_package_id"] == reviewed_package_id
            and (
                policy_input["profile_id"],
                policy_input["role"],
            )
            == identity
        )
        _require(
            matched == expected_matched == [],
            "not-shipped zero-input proof names a redistributed input",
        )
        bindings = {
            (
                item["generated_binding"]["project_description_sha256"],
                item["generated_binding"]["compile_commands_sha256"],
                item["generated_binding"]["linker_map_sha256"],
            )
            for item in observed_inputs.values()
            if (item["profile_id"], item["role"]) == identity
            and item["kind"].startswith("generated-")
        }
        _require(
            len(bindings) == 1,
            "not-shipped zero-input proof is not bound to the observed build",
        )
        (
            project_description_sha256,
            compile_commands_sha256,
            linker_map_sha256,
        ) = next(iter(bindings))
        normalized.append(
            {
                "profile_id": identity[0],
                "role": identity[1],
                "project_description_sha256": project_description_sha256,
                "compile_commands_sha256": compile_commands_sha256,
                "linker_map_sha256": linker_map_sha256,
                "matched_input_ids": [],
            }
        )
    _require(
        observed_identities == expected_identities,
        "not-shipped zero-input proof does not cover its raw package identities",
    )
    return {
        "profile_roles": sorted(
            normalized,
            key=lambda item: (item["profile_id"], item["role"]),
        )
    }


def _audit_v2_aggregate_proof(
    raw: Any,
    *,
    package_refs: list[dict[str, str]],
    reviewed_package_id: str,
    documents: dict[tuple[str, str], dict[str, Any]],
    resolution_by_reviewed: dict[str, dict[str, Any]],
    policy_inputs: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    """Validate raw-relationship paths from aggregate packages to input owners."""

    proof = _exact_keys(raw, {"profile_roles"}, "aggregate relationship proof")
    records = proof["profile_roles"]
    _require(
        isinstance(records, list) and bool(records),
        "aggregate relationship proof has no profile/role records",
    )
    expected_refs = {
        (ref["profile_id"], ref["role"], ref["spdx_id"]) for ref in package_refs
    }
    observed_refs: set[tuple[str, str, str]] = set()
    normalized: list[dict[str, Any]] = []
    for raw_record in records:
        record = _exact_keys(
            raw_record,
            {
                "profile_id",
                "role",
                "relationship_path",
                "input_owning_reviewed_package_id",
            },
            "aggregate relationship proof record",
        )
        identity = _audit_v2_identity(
            record["profile_id"],
            record["role"],
            "aggregate relationship proof",
        )
        path = record["relationship_path"]
        _require(
            isinstance(path, list) and bool(path),
            "aggregate relationship proof path is empty",
        )
        relationships = Counter(
            _audit_v2_canonical(
                relationship,
                "observed SPDX relationship",
            )
            for relationship in documents[identity]["relationships"]
        )
        normalized_path: list[dict[str, str]] = []
        first = _exact_keys(
            path[0],
            {
                "spdxElementId",
                "relationshipType",
                "relatedSpdxElement",
            },
            "aggregate relationship path edge",
        )
        candidate_starts = {
            first["spdxElementId"],
            first["relatedSpdxElement"],
        } & {
            spdx_id
            for profile_id, role, spdx_id in expected_refs
            if (profile_id, role) == identity
        }
        _require(
            len(candidate_starts) == 1,
            "aggregate relationship proof does not start at its raw package",
        )
        start = next(iter(candidate_starts))
        current = start
        visited = {current}
        for raw_edge in path:
            edge = _exact_keys(
                raw_edge,
                {
                    "spdxElementId",
                    "relationshipType",
                    "relatedSpdxElement",
                },
                "aggregate relationship path edge",
            )
            _require(
                relationships[
                    _audit_v2_canonical(
                        edge,
                        "aggregate relationship path edge",
                    )
                ]
                > 0,
                "aggregate relationship proof invents a raw relationship",
            )
            source = edge["spdxElementId"]
            related = edge["relatedSpdxElement"]
            _require(
                edge["relationshipType"] == "DEPENDS_ON"
                and "SPDXRef-DOCUMENT" not in (source, related)
                and current in (source, related)
                and source != related,
                "aggregate relationship proof path is disconnected",
            )
            current = related if current == source else source
            _require(
                current not in visited,
                "aggregate relationship proof path is cyclic",
            )
            visited.add(current)
            normalized_path.append(copy.deepcopy(edge))

        target_reviewed_id = _audit_v2_nonempty(
            record["input_owning_reviewed_package_id"],
            "aggregate relationship proof target",
        )
        _require(
            target_reviewed_id != reviewed_package_id,
            "aggregate relationship proof targets itself",
        )
        target = resolution_by_reviewed.get(target_reviewed_id)
        _require(
            target is not None
            and target["disposition"] == "allow"
            and bool(target["input_refs"])
            and any(
                (
                    policy_inputs[input_ref]["profile_id"],
                    policy_inputs[input_ref]["role"],
                )
                == identity
                for input_ref in target["input_refs"]
            )
            and any(
                (
                    ref["profile_id"],
                    ref["role"],
                    ref["spdx_id"],
                )
                == (identity[0], identity[1], current)
                for ref in target["package_refs"]
            ),
            "aggregate relationship proof does not terminate at an input owner",
        )
        proof_ref = (identity[0], identity[1], start)
        _require(
            proof_ref not in observed_refs,
            "aggregate relationship proof duplicates a raw package",
        )
        observed_refs.add(proof_ref)
        normalized.append(
            {
                "profile_id": identity[0],
                "role": identity[1],
                "relationship_path": normalized_path,
                "input_owning_reviewed_package_id": target_reviewed_id,
            }
        )
    _require(
        observed_refs == expected_refs,
        "aggregate relationship proof does not cover its exact raw packages",
    )
    return {
        "profile_roles": sorted(
            normalized,
            key=lambda item: (
                item["profile_id"],
                item["role"],
                _audit_v2_canonical(
                    item["relationship_path"],
                    "aggregate relationship proof path",
                ),
            ),
        )
    }


def _audit_validate_policy_v2(
    policy: Any,
    *,
    repo_root: Path,
    observed_documents: Any,
    observed_inputs: Any,
    manifest_evidence: Any,
    toolchain_roots: Any = None,
    build_root: Path | None = None,
) -> dict[str, Any]:
    """Validate schema-v2 raw/reviewed/resolved license evidence.

    This seam consumes already parsed raw SPDX and already reconciled build
    observations. It is deliberately deterministic and returns the hashes and
    normalized review records needed by the audit receipt and public notice.
    """

    root = Path(repo_root)
    _require(root.is_dir(), "license policy repository root is missing")
    policy = _exact_keys(policy, _AUDIT_POLICY_V2_KEYS, "license policy v2")
    _require(
        type(policy["schema_version"]) is int
        and policy["schema_version"] == 2,
        "release license policy schema_version must be 2",
    )
    approved_raw = policy["approved_license_refs"]
    _require(
        isinstance(approved_raw, list)
        and all(isinstance(item, str) and item for item in approved_raw)
        and len(approved_raw) == len(set(approved_raw)),
        "approved_license_refs must be a unique array of strings",
    )
    approved = set(approved_raw)
    validated_review_files = _audit_v2_supporting_review_files(
        root,
        policy["review_files"],
    )

    documents, raw_packages = _audit_v2_observed_documents(observed_documents)
    policy_documents = policy["raw_documents"]
    _require(
        isinstance(policy_documents, list),
        "license policy raw_documents must be an array",
    )
    policy_document_identities: set[tuple[str, str]] = set()
    for raw_document in policy_documents:
        record = _exact_keys(
            raw_document,
            {"profile_id", "role", "packages", "relationships"},
            "license policy raw document",
        )
        identity = _audit_v2_identity(
            record["profile_id"],
            record["role"],
            "license policy raw document",
        )
        _require(
            identity not in policy_document_identities,
            "license policy raw document identity is duplicated",
        )
        policy_document_identities.add(identity)
        _require(
            isinstance(record["packages"], list)
            and isinstance(record["relationships"], list),
            "license policy raw evidence is invalid",
        )
        expected_packages: dict[str, str] = {}
        for package in record["packages"]:
            _require(
                isinstance(package, dict) and isinstance(package.get("SPDXID"), str),
                "license policy raw package is invalid",
            )
            spdx_id = package["SPDXID"]
            _require(
                spdx_id not in expected_packages,
                "license policy raw package ID is duplicated",
            )
            expected_packages[spdx_id] = _audit_v2_canonical(
                package,
                "license policy raw package",
            )
        actual_packages = {
            package["SPDXID"]: _audit_v2_canonical(
                package,
                "observed SPDX package",
            )
            for package in documents[identity]["packages"]
        }
        _require(
            expected_packages == actual_packages,
            "raw SPDX package property sets disagree with reviewed policy",
        )
        expected_relationships = Counter(
            _audit_v2_canonical(
                relationship,
                "license policy raw relationship",
            )
            for relationship in record["relationships"]
        )
        actual_relationships = Counter(
            _audit_v2_canonical(
                relationship,
                "observed SPDX relationship",
            )
            for relationship in documents[identity]["relationships"]
        )
        _require(
            expected_relationships == actual_relationships,
            "raw SPDX relationship multiset disagrees with reviewed policy",
        )
    _require(
        policy_document_identities == set(documents),
        "license policy does not cover the exact raw SPDX documents",
    )
    (
        validated_shipment_review,
        shipment_classifications,
        shipment_by_occurrence,
    ) = _audit_v2_shipment_review(
        root,
        policy["shipment_review"],
        raw_occurrences=set(raw_packages),
    )
    validated_manifest_evidence = _audit_v2_manifest_evidence(
        root,
        manifest_evidence,
        build_root=build_root,
    )

    reviewed_raw = policy["reviewed_packages"]
    _require(
        isinstance(reviewed_raw, list) and bool(reviewed_raw),
        "license policy reviewed_packages must be nonempty",
    )
    reviewed: dict[str, dict[str, Any]] = {}
    for raw_record in reviewed_raw:
        expected_reviewed_fields = {
            "id",
            "dependency",
            "source",
            "reviewed_raw_package_expression",
            "license_texts",
            "notice",
        }
        if isinstance(raw_record, dict) and "reviewed_input_expressions" in raw_record:
            expected_reviewed_fields.add("reviewed_input_expressions")
        record = _exact_keys(
            raw_record,
            expected_reviewed_fields,
            "reviewed package",
        )
        identifier = _audit_v2_nonempty(record["id"], "reviewed package id")
        _require(identifier not in reviewed, "reviewed package id is duplicated")
        dependency = _audit_v2_dependency(record["dependency"], identifier)
        source = _audit_v2_source(
            root,
            record["source"],
            identifier,
            allow_tree=False,
        )
        _require(
            source["ref"] == dependency["version_ref"]
            and source["url"] == dependency["source_url"],
            "%s reviewed dependency/source metadata disagrees" % identifier,
        )
        expression = record["reviewed_raw_package_expression"]
        raw_expression_identifiers = _audit_parse_spdx(expression, approved)
        if "reviewed_input_expressions" in record:
            input_expressions = record["reviewed_input_expressions"]
            _require(
                isinstance(input_expressions, list)
                and bool(input_expressions)
                and all(
                    isinstance(input_expression, str) and bool(input_expression)
                    for input_expression in input_expressions
                )
                and len(input_expressions) == len(set(input_expressions)),
                "%s reviewed input expressions are invalid" % identifier,
            )
        else:
            input_expressions = [expression]
        input_expression_identifiers = {
            input_expression: _audit_parse_spdx(input_expression, approved)
            for input_expression in input_expressions
        }
        all_expression_identifiers = set(raw_expression_identifiers)
        for identifiers in input_expression_identifiers.values():
            all_expression_identifiers.update(identifiers)
        reviewed[identifier] = {
            "id": identifier,
            "dependency": dependency,
            "source": source,
            "reviewed_raw_package_expression": expression,
            "reviewed_input_expressions": list(input_expressions),
            "license_texts": _audit_v2_review_files(
                root,
                record["license_texts"],
                identifier,
                expected_identifiers=all_expression_identifiers,
                approved_license_refs=approved,
            ),
            "raw_license_identifiers": raw_expression_identifiers,
            "input_expression_identifiers": input_expression_identifiers,
            "license_identifiers": all_expression_identifiers,
            "notice": _audit_v2_notice(
                root,
                record["notice"],
                identifier,
            ),
        }

    observed_by_id, observed_hashes = _audit_v2_observed_inputs(observed_inputs)
    policy_inputs_raw = policy["resolved_inputs"]
    _require(
        isinstance(policy_inputs_raw, list) and bool(policy_inputs_raw),
        "license policy resolved_inputs must be nonempty",
    )
    policy_inputs: dict[str, dict[str, Any]] = {}
    generated_bindings: dict[str, dict[str, Any]] = {}
    common_input_fields = {
        "id",
        "profile_id",
        "role",
        "kind",
        "reviewed_package_id",
    }
    for raw_input in policy_inputs_raw:
        _require(isinstance(raw_input, dict), "resolved input policy is invalid")
        kind = raw_input.get("kind")
        _require(
            kind in _AUDIT_POLICY_V2_INPUT_KINDS,
            "resolved input policy kind is unsupported",
        )
        if kind.startswith("generated-"):
            expected_fields = common_input_fields | {"generated_matcher"}
        elif kind == "opaque-archive":
            expected_fields = common_input_fields | {
                "reviewed_source_path",
                "sha256",
            }
        elif kind == "toolchain-archive":
            expected_fields = common_input_fields | {
                "toolchain_id",
                "relative_path",
                "sha256",
            }
        else:
            expected_fields = common_input_fields | {
                "path",
                "sha256",
                "frozen_destinations",
            }
        record = _exact_keys(
            raw_input,
            expected_fields,
            "resolved input policy",
        )
        identifier = _audit_v2_nonempty(record["id"], "resolved input id")
        _require(identifier not in policy_inputs, "resolved input id is duplicated")
        _audit_v2_nonempty(
            record["reviewed_package_id"],
            "resolved input %s reviewed package" % identifier,
        )
        _audit_v2_identity(
            record["profile_id"],
            record["role"],
            "resolved input %s" % identifier,
        )
        observed = observed_by_id.get(identifier)
        _require(
            observed is not None
            and observed["profile_id"] == record["profile_id"]
            and observed["role"] == record["role"]
            and observed["kind"] == kind,
            "resolved input %s does not match an exact observation" % identifier,
        )
        if kind.startswith("generated-"):
            matcher = _audit_v2_generated_matcher(
                record["generated_matcher"],
                "resolved input %s" % identifier,
            )
            binding = _audit_v2_generated_binding(
                observed["generated_binding"],
                "observed resolved input %s" % identifier,
            )
            _require(
                (
                    "nested_archive" not in matcher
                    or kind == "generated-supplemental-archive"
                )
                and binding["component"] == matcher["component"]
                and binding.get("nested_archive") == matcher.get("nested_archive"),
                "generated input %s stable matcher disagrees with observation"
                % identifier,
            )
            generated_bindings[identifier] = binding
        elif kind == "opaque-archive":
            relative = _safe_relative_path(
                record["reviewed_source_path"],
                "opaque input %s source" % identifier,
            )
            digest = _audit_v2_hash(
                record["sha256"],
                "opaque input %s digest" % identifier,
            )
            source_path = _audit_repo_file(
                root,
                relative,
                "opaque input %s reviewed source" % identifier,
            )
            _require(
                observed["reviewed_source_path"] == relative
                and _sha256_path(source_path) == digest
                and observed["sha256"] == digest,
                "opaque input %s changed or lacks reviewed provenance" % identifier,
            )
        elif kind == "toolchain-archive":
            relative = _safe_relative_path(
                record["relative_path"],
                "toolchain input %s" % identifier,
            )
            digest = _audit_v2_hash(
                record["sha256"],
                "toolchain input %s digest" % identifier,
            )
            _require(
                record["toolchain_id"] == observed["toolchain_id"]
                and relative == observed["relative_path"]
                and digest == observed["sha256"],
                "toolchain input %s changed" % identifier,
            )
        else:
            relative = _safe_relative_path(
                record["path"],
                "frozen input %s source tree" % identifier,
            )
            digest = _audit_v2_hash(
                record["sha256"],
                "frozen input %s digest" % identifier,
            )
            path = root / relative
            _audit_no_symlink_components(
                root,
                path,
                "frozen input %s source tree" % identifier,
            )
            _require(
                _audit_sha256_tree(path) == digest
                and observed["sha256"] == digest
                and Path(observed["observed_path"]).resolve() == path.resolve()
                and record["frozen_destinations"] == observed["frozen_destinations"],
                "frozen input %s changed" % identifier,
            )
        policy_inputs[identifier] = copy.deepcopy(record)
    _require(
        set(policy_inputs) == set(observed_by_id),
        "resolved input policy does not exactly cover observations",
    )

    validated_toolchains = _audit_v2_toolchains(
        policy_records=policy["toolchains"],
        repo_root=root,
        observed_inputs=observed_by_id,
        toolchain_roots={} if toolchain_roots is None else toolchain_roots,
    )

    raw_consumers: Counter[tuple[str, str, str]] = Counter()
    input_consumers: Counter[str] = Counter()
    normalized_packages: dict[tuple[str, str, str], dict[str, Any]] = {}
    resolutions_raw = policy["resolutions"]
    _require(
        isinstance(resolutions_raw, list) and bool(resolutions_raw),
        "license policy resolutions must be nonempty",
    )
    resolution_ids: set[str] = set()
    reviewed_consumers: Counter[str] = Counter()
    validated_resolutions: list[dict[str, Any]] = []
    resolution_by_reviewed: dict[str, dict[str, Any]] = {}
    resolution_notice_identifiers: dict[str, set[str]] = {}
    for raw_resolution in resolutions_raw:
        _require(isinstance(raw_resolution, dict), "license resolution is invalid")
        base_fields = {
            "id",
            "reviewed_package_id",
            "package_refs",
            "input_refs",
            "resolved_input_expression",
            "disposition",
            "attribution",
        }
        disposition = raw_resolution.get("disposition")
        expected_fields = set(base_fields)
        if disposition == "not-shipped":
            expected_fields.add("zero_input_proof")
        elif disposition == "allow-aggregate":
            expected_fields.add("aggregate_proof")
        resolution = _exact_keys(
            raw_resolution,
            expected_fields,
            "license resolution",
        )
        identifier = _audit_v2_nonempty(resolution["id"], "license resolution id")
        _require(
            identifier not in resolution_ids,
            "license resolution id is duplicated",
        )
        resolution_ids.add(identifier)
        reviewed_id = resolution["reviewed_package_id"]
        _require(
            isinstance(reviewed_id, str) and reviewed_id in reviewed,
            "license resolution names an unknown reviewed package",
        )
        reviewed_consumers[reviewed_id] += 1
        reviewed_record = reviewed[reviewed_id]
        expression = resolution["resolved_input_expression"]
        resolved_identifiers = _audit_parse_spdx(expression, approved)
        _require(
            expression in reviewed_record["input_expression_identifiers"],
            "license resolution expression is not an exact reviewed input expression",
        )
        attribution = _audit_v2_nonempty(
            resolution["attribution"],
            "license resolution attribution",
        )
        package_refs = resolution["package_refs"]
        input_refs = resolution["input_refs"]
        _require(
            isinstance(package_refs, list) and bool(package_refs),
            "license resolution has no raw package references",
        )
        _require(
            isinstance(input_refs, list)
            and all(
                isinstance(input_ref, str) and input_ref for input_ref in input_refs
            ),
            "license resolution input references are invalid",
        )
        if disposition == "allow":
            _require(
                bool(input_refs),
                "allowed license resolution has no redistributed inputs",
            )
            zero_input_proof = None
            aggregate_proof = None
        elif disposition == "allow-aggregate":
            _require(
                not input_refs and isinstance(resolution["aggregate_proof"], dict),
                "aggregate resolution lacks an exact relationship proof",
            )
            _require(
                expression
                == reviewed_record["reviewed_raw_package_expression"],
                "aggregate resolution must retain its reviewed raw expression",
            )
            zero_input_proof = None
            aggregate_proof = resolution["aggregate_proof"]
        elif disposition == "not-shipped":
            _require(
                not input_refs and isinstance(resolution["zero_input_proof"], dict),
                "not-shipped resolution lacks an exact zero-input proof",
            )
            _require(
                expression
                == reviewed_record["reviewed_raw_package_expression"],
                "not-shipped resolution must retain its reviewed raw expression",
            )
            zero_input_proof = resolution["zero_input_proof"]
            aggregate_proof = None
        else:
            raise ReleaseError("license resolution disposition is not approved")

        normalized_refs: list[dict[str, str]] = []
        for raw_ref in package_refs:
            ref = _exact_keys(
                raw_ref,
                {"profile_id", "role", "spdx_id"},
                "license resolution package reference",
            )
            profile_id, role = _audit_v2_identity(
                ref["profile_id"],
                ref["role"],
                "license resolution package reference",
            )
            spdx_id = _audit_v2_nonempty(
                ref["spdx_id"],
                "license resolution package SPDXID",
            )
            key = (profile_id, role, spdx_id)
            package = raw_packages.get(key)
            _require(
                package is not None,
                "license resolution names an unobserved raw package",
            )
            _require(
                shipment_by_occurrence[key] == disposition,
                "license resolution disposition disagrees with shipment review",
            )
            raw_consumers[key] += 1
            concluded = package.get("licenseConcluded")
            declared = package.get("licenseDeclared")
            reviewed_expression = reviewed_record["reviewed_raw_package_expression"]
            if concluded not in ("NOASSERTION", "NONE"):
                _audit_parse_spdx(concluded, approved)
                _require(
                    concluded == reviewed_expression,
                    "concrete raw concluded expression disagrees with review",
                )
            if declared not in ("NOASSERTION", "NONE"):
                _audit_parse_spdx(declared, approved)
                _require(
                    declared == reviewed_expression,
                    "concrete raw declared expression disagrees with review",
                )
            normalized = copy.deepcopy(package)
            normalized.update(
                {
                    "name": reviewed_record["dependency"]["name"],
                    "versionInfo": reviewed_record["dependency"]["version_ref"],
                    "downloadLocation": reviewed_record["dependency"]["source_url"],
                    "copyrightText": reviewed_record["dependency"]["copyright"],
                    "licenseConcluded": reviewed_expression,
                    "licenseDeclared": reviewed_expression,
                }
            )
            existing_attribution = normalized.get("attributionTexts", [])
            _require(
                isinstance(existing_attribution, list)
                and all(
                    isinstance(item, str) and item
                    for item in existing_attribution
                ),
                "raw package attribution texts are invalid",
            )
            normalized["attributionTexts"] = list(
                dict.fromkeys([*existing_attribution, attribution])
            )
            normalized_packages[key] = normalized
            normalized_refs.append(
                {
                    "profile_id": profile_id,
                    "role": role,
                    "spdx_id": spdx_id,
                }
            )
        _require(
            len(normalized_refs)
            == len(
                {
                    (ref["profile_id"], ref["role"], ref["spdx_id"])
                    for ref in normalized_refs
                }
            ),
            "license resolution duplicates a raw package reference",
        )
        if disposition == "not-shipped":
            zero_input_proof = _audit_v2_zero_input_proof(
                zero_input_proof,
                package_refs=normalized_refs,
                reviewed_package_id=reviewed_id,
                observed_inputs=observed_by_id,
                policy_inputs=policy_inputs,
            )
        for input_ref in input_refs:
            _require(
                input_ref in policy_inputs,
                "license resolution names an unknown input",
            )
            _require(
                policy_inputs[input_ref]["kind"]
                not in _AUDIT_POLICY_V2_SUPPLEMENTAL_INPUT_KINDS,
                "raw package resolution consumes a supplemental-only input",
            )
            _require(
                policy_inputs[input_ref]["reviewed_package_id"] == reviewed_id,
                "license resolution consumes an input reviewed for another package",
            )
            _require(
                (
                    policy_inputs[input_ref]["profile_id"],
                    policy_inputs[input_ref]["role"],
                )
                in {
                    (ref["profile_id"], ref["role"])
                    for ref in normalized_refs
                },
                "license resolution input is outside its raw package identities",
            )
            input_consumers[input_ref] += 1
        _require(
            len(input_refs) == len(set(input_refs)),
            "license resolution duplicates an input reference",
        )
        if disposition == "allow":
            _require(
                {
                    (
                        policy_inputs[input_ref]["profile_id"],
                        policy_inputs[input_ref]["role"],
                    )
                    for input_ref in input_refs
                }
                == {
                    (ref["profile_id"], ref["role"])
                    for ref in normalized_refs
                },
                "allowed license resolution lacks exact profile/role input coverage",
            )
        validated = {
            "id": identifier,
            "reviewed_package_id": reviewed_id,
            "package_refs": sorted(
                normalized_refs,
                key=lambda item: (
                    item["profile_id"],
                    item["role"],
                    item["spdx_id"],
                ),
            ),
            "input_refs": sorted(input_refs),
            "resolved_input_expression": expression,
            "disposition": disposition,
            "attribution": attribution,
        }
        if disposition == "not-shipped":
            validated["zero_input_proof"] = zero_input_proof
        elif disposition == "allow-aggregate":
            validated["aggregate_proof"] = copy.deepcopy(aggregate_proof)
        validated_resolutions.append(validated)
        resolution_by_reviewed[reviewed_id] = validated
        resolution_notice_identifiers[identifier] = resolved_identifiers

    for resolution in validated_resolutions:
        if resolution["disposition"] != "allow-aggregate":
            continue
        resolution["aggregate_proof"] = _audit_v2_aggregate_proof(
            resolution["aggregate_proof"],
            package_refs=resolution["package_refs"],
            reviewed_package_id=resolution["reviewed_package_id"],
            documents=documents,
            resolution_by_reviewed=resolution_by_reviewed,
            policy_inputs=policy_inputs,
        )

    _require(
        set(reviewed_consumers) == set(reviewed)
        and all(count == 1 for count in reviewed_consumers.values()),
        "each reviewed raw package must have exactly one resolution",
    )

    supplemental_raw = policy["supplemental_packages"]
    _require(
        isinstance(supplemental_raw, list) and bool(supplemental_raw),
        "supplemental_packages must be nonempty",
    )
    supplemental_ids: set[str] = set()
    validated_supplementals: list[dict[str, Any]] = []
    for raw_supplemental in supplemental_raw:
        supplemental = _exact_keys(
            raw_supplemental,
            {
                "id",
                "dependency",
                "source",
                "source_spdx_expression",
                "selected_spdx_expression",
                "input_refs",
                "relationship",
                "license_texts",
                "notice",
                "disposition",
            },
            "supplemental package",
        )
        identifier = _audit_v2_nonempty(
            supplemental["id"],
            "supplemental package id",
        )
        _require(
            identifier not in supplemental_ids and identifier not in reviewed,
            "supplemental package id is duplicated",
        )
        supplemental_ids.add(identifier)
        _require(
            supplemental["disposition"] == "allow",
            "supplemental package is not approved",
        )
        dependency = _audit_v2_dependency(
            supplemental["dependency"],
            identifier,
        )
        source = _audit_v2_source(
            root,
            supplemental["source"],
            identifier,
            allow_tree=True,
        )
        _require(
            source["ref"] == dependency["version_ref"]
            and source["url"] == dependency["source_url"],
            "%s supplemental dependency/source metadata disagrees" % identifier,
        )
        source_expression = supplemental["source_spdx_expression"]
        selected_expression = supplemental["selected_spdx_expression"]
        source_expression_identifiers, selected_expression_identifiers = (
            _audit_spdx_selected_choice(
                source_expression,
                selected_expression,
                approved,
            )
        )
        relationship = _exact_keys(
            supplemental["relationship"],
            {
                "relationship_type",
                "related_reviewed_package_id",
            },
            "%s supplemental relationship" % identifier,
        )
        _audit_v2_nonempty(
            relationship["relationship_type"],
            "%s supplemental relationship type" % identifier,
        )
        _require(
            relationship["relationship_type"] == "DEPENDS_ON",
            "%s supplemental relationship must be DEPENDS_ON" % identifier,
        )
        related = relationship["related_reviewed_package_id"]
        _require(
            isinstance(related, str)
            and related in reviewed
            and related in resolution_by_reviewed,
            "%s supplemental relationship names an unknown reviewed package"
            % identifier,
        )
        input_refs = supplemental["input_refs"]
        _require(
            isinstance(input_refs, list)
            and bool(input_refs)
            and all(
                isinstance(input_ref, str) and input_ref for input_ref in input_refs
            )
            and len(input_refs) == len(set(input_refs)),
            "%s supplemental input references are invalid" % identifier,
        )
        supplemental_identities: set[tuple[str, str]] = set()
        for input_ref in input_refs:
            policy_input = policy_inputs.get(input_ref)
            _require(
                policy_input is not None
                and policy_input["kind"] in _AUDIT_POLICY_V2_SUPPLEMENTAL_INPUT_KINDS,
                "%s supplemental package names a non-supplemental input" % identifier,
            )
            _require(
                policy_input["reviewed_package_id"] == identifier,
                "%s supplemental package consumes an input reviewed elsewhere"
                % identifier,
            )
            source_tree = source.get("tree_path")
            _require(
                isinstance(source_tree, str) and bool(source_tree),
                "%s supplemental input lacks an immutable reviewed source tree"
                % identifier,
            )
            if policy_input["kind"] == "generated-supplemental-archive":
                tree_prefix = _safe_relative_path(
                    source_tree,
                    "%s supplemental source tree" % identifier,
                ).rstrip("/") + "/"
                _require(
                    all(
                        item["path"].startswith(tree_prefix)
                        for item in generated_bindings[input_ref]["sources"]
                    ),
                    "%s generated source escapes its immutable reviewed tree"
                    % identifier,
                )
            else:
                _require(
                    policy_input["path"] == source_tree,
                    "%s frozen input differs from its immutable reviewed tree"
                    % identifier,
                )
            input_consumers[input_ref] += 1
            supplemental_identities.add(
                (policy_input["profile_id"], policy_input["role"])
            )
        owner_resolution = resolution_by_reviewed[related]
        owner_identities = {
            (ref["profile_id"], ref["role"]) for ref in owner_resolution["package_refs"]
        }
        owner_generated_identities = {
            (
                policy_inputs[input_ref]["profile_id"],
                policy_inputs[input_ref]["role"],
            )
            for input_ref in owner_resolution["input_refs"]
            if policy_inputs[input_ref]["kind"] == "generated-component-archive"
        }
        _require(
            supplemental_identities <= owner_identities
            and supplemental_identities <= owner_generated_identities,
            "%s supplemental relationship does not identify its owning package"
            % identifier,
        )
        validated_supplementals.append(
            {
                "id": identifier,
                "dependency": dependency,
                "source": source,
                "source_spdx_expression": source_expression,
                "selected_spdx_expression": selected_expression,
                "input_refs": sorted(input_refs),
                "relationship": copy.deepcopy(relationship),
                "license_texts": _audit_v2_review_files(
                    root,
                    supplemental["license_texts"],
                    identifier,
                    expected_identifiers=source_expression_identifiers,
                    approved_license_refs=approved,
                ),
                "selected_license_identifiers": selected_expression_identifiers,
                "notice": _audit_v2_notice(
                    root,
                    supplemental["notice"],
                    identifier,
                ),
                "disposition": "allow",
            }
        )

    _require(
        set(raw_consumers) == set(raw_packages)
        and all(count == 1 for count in raw_consumers.values()),
        "every raw package must be consumed by exactly one resolution",
    )
    _require(
        set(input_consumers) == set(policy_inputs)
        and all(count == 1 for count in input_consumers.values()),
        "every redistributed input must be consumed exactly once",
    )

    reviewed_documents: dict[str, dict[str, Any]] = {}
    for identity, document in sorted(documents.items()):
        profile_id, role = identity
        reviewed_documents["%s/%s" % identity] = {
            "profile_id": profile_id,
            "role": role,
            "packages": sorted(
                (
                    normalized_packages[(profile_id, role, package["SPDXID"])]
                    for package in document["packages"]
                ),
                key=lambda package: package["SPDXID"],
            ),
            "relationships": sorted(
                copy.deepcopy(document["relationships"]),
                key=lambda relationship: _audit_v2_canonical(
                    relationship,
                    "reviewed SPDX relationship",
                ),
            ),
        }

    notice_records: list[dict[str, Any]] = []
    for resolution in sorted(validated_resolutions, key=lambda item: item["id"]):
        if resolution["disposition"] not in ("allow", "allow-aggregate"):
            continue
        record = reviewed[resolution["reviewed_package_id"]]
        selected_identifiers = resolution_notice_identifiers[resolution["id"]]
        notice_records.append(
            {
                "id": record["id"],
                "dependency": copy.deepcopy(record["dependency"]),
                "source": copy.deepcopy(record["source"]),
                "spdx_expression": resolution["resolved_input_expression"],
                "license_texts": [
                    copy.deepcopy(item)
                    for item in record["license_texts"]
                    if item["spdx_id"] in selected_identifiers
                ],
                "notice": copy.deepcopy(record["notice"]),
                "input_refs": list(resolution["input_refs"]),
            }
        )
    for supplemental in sorted(
        validated_supplementals,
        key=lambda item: item["id"],
    ):
        notice_records.append(
            {
                "id": supplemental["id"],
                "dependency": copy.deepcopy(supplemental["dependency"]),
                "source": copy.deepcopy(supplemental["source"]),
                "spdx_expression": supplemental["selected_spdx_expression"],
                "license_texts": [
                    copy.deepcopy(item)
                    for item in supplemental["license_texts"]
                    if item["spdx_id"]
                    in supplemental["selected_license_identifiers"]
                ],
                "notice": copy.deepcopy(supplemental["notice"]),
                "input_refs": list(supplemental["input_refs"]),
            }
        )
    notice_records.sort(key=lambda item: item["id"])

    semantic_sha256 = {
        key: _sha256_bytes(
            _audit_v2_canonical(policy[key], "license policy %s" % key).encode(
                "utf-8"
            )
        )
        for key in (
            "raw_documents",
            "review_files",
            "shipment_review",
            "reviewed_packages",
            "resolved_inputs",
            "resolutions",
            "supplemental_packages",
            "toolchains",
        )
    }
    semantic_sha256["resolutions"] = _sha256_bytes(
        _audit_v2_canonical(
            sorted(validated_resolutions, key=lambda item: item["id"]),
            "validated license resolutions",
        ).encode("utf-8")
    )
    semantic_sha256["generated_bindings"] = _sha256_bytes(
        _audit_v2_canonical(
            dict(sorted(generated_bindings.items())),
            "observed generated input bindings",
        ).encode("utf-8")
    )
    semantic_sha256["shipment_classifications"] = _sha256_bytes(
        _audit_v2_canonical(
            shipment_classifications,
            "validated shipment classifications",
        ).encode("utf-8")
    )
    semantic_sha256["frozen_manifest_evidence"] = _sha256_bytes(
        _audit_v2_canonical(
            validated_manifest_evidence,
            "validated literal manifest evidence",
        ).encode("utf-8")
    )
    public_supplementals = []
    for supplemental in sorted(validated_supplementals, key=lambda item: item["id"]):
        record = copy.deepcopy(supplemental)
        record.pop("selected_license_identifiers")
        public_supplementals.append(record)
    return {
        "schema_version": 2,
        "reviewed_documents": reviewed_documents,
        "observed_input_sha256": observed_hashes,
        "generated_bindings": dict(sorted(generated_bindings.items())),
        "review_files": validated_review_files,
        "shipment_review": validated_shipment_review,
        "shipment_classifications": shipment_classifications,
        "manifest_evidence": validated_manifest_evidence,
        "notice_records": notice_records,
        "resolutions": sorted(validated_resolutions, key=lambda item: item["id"]),
        "supplemental_packages": public_supplementals,
        "toolchains": dict(sorted(validated_toolchains.items())),
        "semantic_sha256": semantic_sha256,
    }


def _audit_load_policy(
    repo_root: Path,
    lock: dict[str, Any],
) -> dict[str, Any]:
    inputs = lock["inputs"]
    policy_path = _audit_repo_file(
        repo_root,
        inputs["license_policy_path"],
        "release license policy",
    )
    policy = _read_json(policy_path, "release license policy")
    _require(isinstance(policy, dict), "release license policy must be an object")
    _require(
        type(policy.get("schema_version")) is int
        and policy.get("schema_version") == 2,
        "release license policy schema_version must be 2",
    )
    _exact_keys(policy, _AUDIT_POLICY_V2_KEYS, "release license policy")
    return policy


def _audit_rp2_nonempty(value: Any, label: str) -> str:
    _require(
        isinstance(value, str) and bool(value) and value == value.strip(),
        "%s must be one nonempty canonical string" % label,
    )
    _require("\x00" not in value, "%s contains NUL" % label)
    return value


def _audit_rp2_logical_file(
    value: Any,
    *,
    repo_root: Path,
    build_root: Path,
    label: str,
) -> tuple[str, Path]:
    logical = _safe_relative_path(value, label)
    prefix, separator, relative = logical.partition("/")
    if bool(separator) and prefix in {"repo", "build"} and bool(relative):
        root = Path(repo_root) if prefix == "repo" else Path(build_root)
    else:
        # Checked-in policy assets use repository-relative paths.  The
        # explicit repo/build spelling remains accepted for persisted input
        # records and for self-contained audit fixtures.
        root = Path(repo_root)
        relative = logical
    return logical, _audit_repo_file(root, relative, label)


def _audit_validate_rp2_license_policy(
    value: Any,
    *,
    repo_root: Path,
    build_root: Path,
) -> dict[str, Any]:
    """Validate the independent, source-root keyed RP2 license policy."""

    root = Path(repo_root)
    builds = Path(build_root)
    policy = _exact_keys(
        value,
        _RP2_LICENSE_POLICY_KEYS,
        "RP2 license policy",
    )
    schema_version = policy["schema_version"]
    _require(
        type(schema_version) is int and schema_version in {1, 2},
        "RP2 license policy schema_version must be the exact integer 1 or 2",
    )
    _require(
        policy["profile_id"] == "rpi-pico2-w"
        and policy["target"] == "rpi-pico2-w",
        "RP2 license policy identity is substituted",
    )
    raw_owners = policy["source_owners"]
    _require(
        isinstance(raw_owners, list) and bool(raw_owners),
        "RP2 license policy source_owners must be nonempty",
    )
    owners: list[dict[str, Any]] = []
    owner_ids: set[str] = set()
    root_identities: set[tuple[str, str]] = set()
    license_ref_sha256: dict[str, str] = {}
    for index, raw in enumerate(raw_owners):
        raw_identifier = raw.get("id") if isinstance(raw, dict) else None
        arm_runtime_owner = raw_identifier in _RP2_ARM_RUNTIME_OWNER_CONTRACT
        expected_owner_keys = (
            _RP2_LICENSE_OWNER_V2_KEYS
            if schema_version == 2 and arm_runtime_owner
            else _RP2_LICENSE_OWNER_KEYS
        )
        owner = _exact_keys(
            raw,
            expected_owner_keys,
            "RP2 license owner %d" % index,
        )
        identifier = _audit_rp2_nonempty(owner["id"], "RP2 owner id")
        _require(
            re.fullmatch(r"[a-z0-9][a-z0-9.-]*", identifier) is not None
            and identifier not in owner_ids,
            "RP2 license owner id is invalid or duplicated",
        )
        owner_ids.add(identifier)
        component_kind = owner.get("component_kind")
        if schema_version == 2:
            _require(
                arm_runtime_owner
                == (component_kind in {"build-tool", "runtime"}),
                "RP2 schema-2 component_kind scope is invalid",
            )
            if arm_runtime_owner:
                _require(
                    component_kind
                    == _RP2_ARM_RUNTIME_OWNER_CONTRACT[identifier],
                    "RP2 ARM GNU component_kind changed for %s" % identifier,
                )
        roots = owner["source_roots"]
        _require(
            isinstance(roots, list) and bool(roots),
            "RP2 owner %s source_roots must be nonempty" % identifier,
        )
        normalized_roots: list[dict[str, str]] = []
        for root_index, raw_root in enumerate(roots):
            source_root = _exact_keys(
                raw_root,
                {"namespace", "path"},
                "RP2 owner %s source root %d" % (identifier, root_index),
            )
            namespace = source_root["namespace"]
            _require(
                namespace in {"repo", "micropython", "arm-gnu-toolchain"},
                "RP2 owner %s source-root namespace is invalid" % identifier,
            )
            path = _safe_relative_path(
                source_root["path"],
                "RP2 owner %s source-root path" % identifier,
            )
            identity = (namespace, path.rstrip("/"))
            _require(
                identity not in root_identities,
                "RP2 license source root is ambiguous or duplicated",
            )
            root_identities.add(identity)
            normalized_roots.append(
                {"namespace": namespace, "path": identity[1]}
            )
        _require(
            normalized_roots
            == sorted(
                normalized_roots,
                key=lambda item: (item["namespace"], item["path"]),
            ),
            "RP2 owner %s source_roots are not canonical" % identifier,
        )
        source_ref = _audit_rp2_nonempty(
            owner["source_ref"], "RP2 owner %s source_ref" % identifier
        )
        source_url = _audit_rp2_nonempty(
            owner["source_url"], "RP2 owner %s source_url" % identifier
        )
        parsed_url = urlsplit(source_url)
        _require(
            parsed_url.scheme in {"https", "file"}
            and bool(parsed_url.netloc or parsed_url.scheme == "file"),
            "RP2 owner %s source_url is invalid" % identifier,
        )
        disposition = owner["disposition"]
        _require(
            disposition in {"project-owned", "allow", "review-required"},
            "RP2 owner %s disposition is invalid" % identifier,
        )
        source_expression = _audit_rp2_nonempty(
            owner["source_spdx_expression"],
            "RP2 owner %s source SPDX expression" % identifier,
        )
        selected_expression = _audit_rp2_nonempty(
            owner["selected_spdx_expression"],
            "RP2 owner %s selected SPDX expression" % identifier,
        )
        source_syntax = _AuditSpdxExpressionParser(source_expression).parse()
        selected_syntax = _AuditSpdxExpressionParser(selected_expression).parse()
        custom_refs = {
            item
            for item in source_syntax | selected_syntax
            if item.startswith("LicenseRef-")
        }
        # The separately locked policy plus the exact complete-text records is
        # the review authority for project-specific LicenseRefs.  Its
        # disposition decides admission later; syntax validation must retain
        # both reviewed ``allow`` and unresolved ``review-required`` records.
        approved_refs = custom_refs
        source_identifiers = _audit_parse_spdx(
            source_expression,
            approved_refs,
        )
        selected_identifiers = _audit_parse_spdx(
            selected_expression,
            approved_refs,
        )
        source_arms = _audit_spdx_choice_arms(source_expression)
        selected_tokens = _audit_spdx_unwrap(
            _audit_spdx_tokens(selected_expression)
        )
        source_tokens = _audit_spdx_unwrap(
            _audit_spdx_tokens(source_expression)
        )
        _require(
            (
                selected_tokens == source_tokens
                and (
                    len(source_arms) == 1
                    or disposition == "review-required"
                )
            )
            or (
                len(source_arms) > 1
                and selected_tokens in source_arms
            ),
            "RP2 owner %s selected expression weakens or changes source terms"
            % identifier,
        )
        copyright_value = _audit_rp2_nonempty(
            owner["copyright"], "RP2 owner %s copyright" % identifier
        )
        license_texts = owner["license_texts"]
        _require(
            isinstance(license_texts, list) and bool(license_texts),
            "RP2 owner %s has no complete license texts" % identifier,
        )
        normalized_licenses: list[dict[str, str]] = []
        license_ids: set[str] = set()
        for text_index, raw_text in enumerate(license_texts):
            record = _exact_keys(
                raw_text,
                {"identifier", "path", "sha256"},
                "RP2 owner %s license text %d" % (identifier, text_index),
            )
            text_id = _audit_rp2_nonempty(
                record["identifier"],
                "RP2 owner %s license identifier" % identifier,
            )
            _require(
                text_id not in license_ids,
                "RP2 owner %s duplicates a license identifier" % identifier,
            )
            logical, file_path = _audit_rp2_logical_file(
                record["path"],
                repo_root=root,
                build_root=builds,
                label="RP2 owner %s license text" % identifier,
            )
            digest = _audit_v060_digest(
                record["sha256"],
                "RP2 owner %s license digest" % identifier,
            )
            _require(
                _sha256_path(file_path) == digest,
                "RP2 owner %s license text changed" % identifier,
            )
            license_ids.add(text_id)
            normalized_licenses.append(
                {"identifier": text_id, "path": logical, "sha256": digest}
            )
        _require(
            normalized_licenses
            == sorted(normalized_licenses, key=lambda item: item["identifier"])
            and license_ids == source_identifiers,
            "RP2 owner %s license texts do not exactly cover its source expression"
            % identifier,
        )
        for license_record in normalized_licenses:
            license_identifier = license_record["identifier"]
            if not license_identifier.startswith("LicenseRef-"):
                continue
            previous_digest = license_ref_sha256.setdefault(
                license_identifier,
                license_record["sha256"],
            )
            _require(
                previous_digest == license_record["sha256"],
                "RP2 LicenseRef %s has different complete-text digests across "
                "owners" % license_identifier,
            )
        notices = owner["notice_files"]
        _require(
            isinstance(notices, list),
            "RP2 owner %s notice_files must be an array" % identifier,
        )
        normalized_notices: list[dict[str, str]] = []
        notice_paths: set[str] = set()
        for notice_index, raw_notice in enumerate(notices):
            record = _exact_keys(
                raw_notice,
                {"path", "sha256"},
                "RP2 owner %s notice %d" % (identifier, notice_index),
            )
            logical, file_path = _audit_rp2_logical_file(
                record["path"],
                repo_root=root,
                build_root=builds,
                label="RP2 owner %s notice" % identifier,
            )
            digest = _audit_v060_digest(
                record["sha256"],
                "RP2 owner %s notice digest" % identifier,
            )
            _require(
                logical not in notice_paths and _sha256_path(file_path) == digest,
                "RP2 owner %s notice is duplicated or changed" % identifier,
            )
            notice_paths.add(logical)
            normalized_notices.append({"path": logical, "sha256": digest})
        _require(
            normalized_notices
            == sorted(normalized_notices, key=lambda item: item["path"]),
            "RP2 owner %s notices are not canonical" % identifier,
        )
        normalized_owner = {
            "id": identifier,
            "source_roots": normalized_roots,
            "source_ref": source_ref,
            "source_url": source_url,
            "source_spdx_expression": source_expression,
            "selected_spdx_expression": selected_expression,
            "copyright": copyright_value,
            "license_texts": normalized_licenses,
            "notice_files": normalized_notices,
            "disposition": disposition,
        }
        if component_kind is not None:
            normalized_owner["component_kind"] = component_kind
        owners.append(normalized_owner)
    _require(
        [owner["id"] for owner in owners]
        == sorted(owner["id"] for owner in owners),
        "RP2 license policy owners are not canonical",
    )
    return {
        "schema_version": schema_version,
        "profile_id": "rpi-pico2-w",
        "target": "rpi-pico2-w",
        "source_owners": owners,
    }


def _audit_load_rp2_license_policy(
    repo_root: Path,
    build_root: Path,
    lock: dict[str, Any],
) -> dict[str, Any]:
    inputs = lock.get("inputs")
    _require(isinstance(inputs, dict), "release tool lock inputs are missing")
    relative = inputs.get("rp2_license_policy_path")
    expected_hash = inputs.get("rp2_license_policy_sha256")
    _require(
        isinstance(relative, str)
        and isinstance(expected_hash, str)
        and SHA256_RE.fullmatch(expected_hash) is not None,
        "release tool lock lacks the RP2 license-policy binding",
    )
    path = _audit_repo_file(
        Path(repo_root),
        relative,
        "RP2 release license policy",
    )
    raw = _read_regular_file_bytes(path, "RP2 release license policy")
    try:
        value = json.loads(raw.decode("utf-8", errors="strict"))
    except (UnicodeError, TypeError, ValueError) as exc:
        raise ReleaseError("RP2 release license policy is invalid JSON") from exc
    _require(
        raw == _canonical_json_bytes(value),
        "RP2 release license policy is not canonical JSON",
    )
    _require(
        _sha256_bytes(raw) == expected_hash,
        "RP2 release license policy differs from release-tools.lock",
    )
    return _audit_validate_rp2_license_policy(
        value,
        repo_root=Path(repo_root),
        build_root=Path(build_root),
    )


def _audit_validate_rp2_arm_runtime_closure(
    attribution: Any,
    observed: Any,
    *,
    repo_root: Path,
) -> dict[str, Any]:
    """Validate the hash-frozen Arm GNU contribution and compilation receipt."""

    root = Path(repo_root)
    expected_path = _audit_repo_file(
        root,
        _RP2_ARM_RUNTIME_ATTRIBUTION,
        "RP2 Arm GNU runtime attribution",
    )
    expected_raw = _read_regular_file_bytes(
        expected_path, "RP2 Arm GNU runtime attribution"
    )
    _require(
        _sha256_bytes(expected_raw) == _RP2_ARM_RUNTIME_ATTRIBUTION_SHA256,
        "RP2 Arm GNU runtime attribution bytes changed",
    )
    try:
        expected = json.loads(expected_raw.decode("utf-8", errors="strict"))
    except (UnicodeError, TypeError, ValueError) as exc:
        raise ReleaseError("RP2 Arm GNU runtime attribution is invalid JSON") from exc
    _require(
        isinstance(attribution, dict) and attribution == expected,
        "RP2 Arm GNU runtime attribution differs from its frozen document",
    )
    _require(isinstance(observed, dict), "RP2 Arm GNU observation must be an object")

    exact_observation_keys = (
        "identity",
        "build_tools",
        "specs_inputs",
        "runtime_archives",
        "archive_members",
        "headers",
        "generated_headers",
    )
    for key in exact_observation_keys:
        _require(
            key in observed and observed[key] == expected[key],
            "RP2 Arm GNU %s observation changed" % key.replace("_", " "),
        )
    expected_direct = expected["direct_inputs"]
    observed_direct = observed.get("direct_inputs")
    _require(
        isinstance(observed_direct, list)
        and len(observed_direct) == len(expected_direct),
        "RP2 Arm GNU direct-input inventory changed",
    )
    for expected_item, observed_item in zip(expected_direct, observed_direct):
        _require(
            isinstance(observed_item, list)
            and len(observed_item) == len(expected_item)
            and type(observed_item[3]) is bool
            and observed_item[:3] == expected_item[:3]
            and observed_item[4:] == expected_item[4:],
            "RP2 Arm GNU direct-input source mapping changed",
        )

    receipt = _exact_keys(
        observed.get("eligible_compilation_receipt"),
        {
            "bound_kinds",
            "compiler_launchers",
            "driver_environment_overrides",
            "external_ir_consumers",
            "compile_recipes",
            "link_driver",
            "link_arguments",
            "resolved_specs_inputs",
            "source_archive_sha256",
        },
        "RP2 Eligible Compilation receipt",
    )
    eligible = _exact_keys(
        expected.get("eligible_compilation"),
        {
            "forbidden_arguments",
            "forbid_compiler_launchers",
            "forbid_external_ir_consumers",
            "required_receipt_kinds",
            "target_code_drivers",
            "link_driver",
        },
        "RP2 Eligible Compilation contract",
    )
    bound_kinds = receipt["bound_kinds"]
    _require(
        isinstance(bound_kinds, list)
        and len(bound_kinds) == len(set(bound_kinds))
        and set(bound_kinds) == set(eligible["required_receipt_kinds"]),
        "RP2 Eligible Compilation receipt kinds changed",
    )
    _require(
        receipt["compiler_launchers"] == []
        and receipt["driver_environment_overrides"] == []
        and receipt["external_ir_consumers"] == [],
        "RP2 Eligible Compilation uses an unreviewed environment, launcher, or IR consumer",
    )
    recipes = receipt["compile_recipes"]
    _require(
        isinstance(recipes, list) and bool(recipes),
        "RP2 Eligible Compilation has no compile recipes",
    )
    allowed_drivers = set(eligible["target_code_drivers"])
    for index, raw_recipe in enumerate(recipes):
        recipe = _exact_keys(
            raw_recipe,
            {"language", "driver", "arguments"},
            "RP2 Eligible Compilation recipe %d" % index,
        )
        _require(
            recipe["language"] in {"C", "CXX", "ASM"}
            and recipe["driver"] in allowed_drivers
            and isinstance(recipe["arguments"], list)
            and all(isinstance(item, str) and "\x00" not in item for item in recipe["arguments"]),
            "RP2 Eligible Compilation recipe changed driver or syntax",
        )
        _audit_rp2_reject_driver_overrides(
            recipe["arguments"],
            label="RP2 Eligible Compilation recipe %d" % index,
        )
        lowered = [item.lower() for item in recipe["arguments"]]
        for forbidden in eligible["forbidden_arguments"]:
            _require(
                not any(
                    item == forbidden.lower()
                    or item.startswith(forbidden.lower() + "=")
                    for item in lowered
                ),
                "RP2 Eligible Compilation uses forbidden %s" % forbidden,
            )
    link_arguments = receipt["link_arguments"]
    if isinstance(link_arguments, list):
        _audit_rp2_reject_driver_overrides(
            link_arguments,
            label="RP2 Eligible Compilation link recipe",
            allowed_specs={"--specs=nosys.specs"},
        )
    _require(
        receipt["link_driver"] == eligible["link_driver"]
        and receipt["resolved_specs_inputs"] == expected["specs_inputs"]
        and isinstance(link_arguments, list)
        and all(isinstance(item, str) and "\x00" not in item for item in link_arguments)
        and not any(
            item.lower() == "-flto" or item.lower().startswith("-flto=")
            or item.lower() == "-fplugin"
            or item.lower().startswith("-fplugin=")
            for item in link_arguments
        ),
        "RP2 Eligible Compilation link recipe is not admitted",
    )
    source_archive = expected["identity"]["source_archive"]
    _require(
        receipt["source_archive_sha256"] == source_archive["sha256"],
        "RP2 Eligible Compilation source archive identity changed",
    )
    arm_lock = _read_lock(root).get("arm_gnu_toolchain")
    _require(
        isinstance(arm_lock, dict)
        and arm_lock.get("source_archive_filename") == source_archive["filename"]
        and arm_lock.get("source_archive_bytes") == source_archive["bytes"]
        and arm_lock.get("source_archive_format") == "tar.xz"
        and arm_lock.get("source_archive_sha256") == source_archive["sha256"]
        and arm_lock.get("source_manifest_path")
        == expected["identity"]["source_manifest"]["path"]
        and arm_lock.get("source_manifest_sha256")
        == expected["identity"]["source_manifest"]["sha256"],
        "RP2 Arm GNU source archive or manifest lock changed",
    )
    retained_source_archive = (
        root
        / "firmware"
        / ".arm-gnu"
        / ".pyble-dist"
        / source_archive["filename"]
    )
    _audit_regular_compile_file(
        retained_source_archive, "RP2 retained Arm GNU source archive"
    )
    _require(
        retained_source_archive.stat().st_size == source_archive["bytes"]
        and _sha256_path(retained_source_archive) == source_archive["sha256"],
        "RP2 retained Arm GNU source archive bytes changed",
    )
    source_manifest_path = _audit_repo_file(
        root,
        expected["identity"]["source_manifest"]["path"],
        "RP2 Arm GNU source manifest",
    )
    _require(
        _sha256_path(source_manifest_path)
        == expected["identity"]["source_manifest"]["sha256"],
        "RP2 Arm GNU source manifest bytes changed",
    )

    contributing_owner_ids: set[str] = {
        item[0] for item in expected["headers"] + expected["generated_headers"]
    }
    contributing_owner_ids.update(
        item[0] for item in expected["direct_inputs"] if item[3]
    )
    contributing_owner_ids.update(item[0] for item in expected["archive_members"])
    # A replay may deliberately exercise a future exact direct contributor.
    # The source mapping is already frozen in the attribution row, so its
    # contribution changes notice scope without weakening source ownership.
    contributing_owner_ids.update(
        item[0] for item in observed["direct_inputs"] if item[3]
    )
    kinds = {
        item["id"]: item["kind"] for item in expected["components"]
    }
    public_notice_owner_ids = sorted(
        owner_id
        for owner_id in contributing_owner_ids
        if kinds.get(owner_id) == "runtime"
    )
    return {
        "eligible_compilation": True,
        "contributing_owner_ids": sorted(contributing_owner_ids),
        "public_notice_owner_ids": public_notice_owner_ids,
    }


def _audit_validate_rp2_arm_runtime_notices(
    attribution: Any,
    evidence: Any,
    *,
    repo_root: Path,
) -> dict[str, Any]:
    """Validate the exact contribution-scoped Arm GNU notice assets."""

    root = Path(repo_root)
    attribution_path = _audit_repo_file(
        root,
        _RP2_ARM_RUNTIME_ATTRIBUTION,
        "RP2 Arm GNU runtime attribution",
    )
    attribution_raw = _read_regular_file_bytes(
        attribution_path,
        "RP2 Arm GNU runtime attribution",
    )
    _require(
        _sha256_bytes(attribution_raw) == _RP2_ARM_RUNTIME_ATTRIBUTION_SHA256,
        "RP2 Arm GNU runtime attribution bytes changed",
    )
    try:
        expected_attribution = json.loads(
            attribution_raw.decode("utf-8", errors="strict")
        )
    except (UnicodeError, TypeError, ValueError) as exc:
        raise ReleaseError(
            "RP2 Arm GNU runtime attribution is invalid JSON"
        ) from exc
    _require(
        isinstance(attribution, dict) and attribution == expected_attribution,
        "RP2 Arm GNU runtime notice attribution changed",
    )

    evidence_path = _audit_repo_file(
        root,
        _RP2_ARM_RUNTIME_NOTICES,
        "RP2 Arm GNU runtime notice evidence",
    )
    evidence_raw = _read_regular_file_bytes(
        evidence_path,
        "RP2 Arm GNU runtime notice evidence",
    )
    _require(
        _sha256_bytes(evidence_raw) == _RP2_ARM_RUNTIME_NOTICES_SHA256,
        "RP2 Arm GNU runtime notice evidence bytes changed",
    )
    try:
        expected_evidence = json.loads(
            evidence_raw.decode("ascii", errors="strict")
        )
        canonical_evidence = (
            json.dumps(
                expected_evidence,
                ensure_ascii=True,
                separators=(",", ":"),
                sort_keys=True,
            )
            + "\n"
        ).encode("ascii")
    except (UnicodeError, TypeError, ValueError) as exc:
        raise ReleaseError(
            "RP2 Arm GNU runtime notice evidence is invalid canonical JSON"
        ) from exc
    _require(
        evidence_raw == canonical_evidence,
        "RP2 Arm GNU runtime notice evidence is not canonical JSON",
    )
    _require(
        isinstance(evidence, dict) and evidence == expected_evidence,
        "RP2 Arm GNU runtime notice evidence differs from its frozen document",
    )
    normalized = _exact_keys(
        evidence,
        {
            "schema_version",
            "canonicalization",
            "identity",
            "record_schemas",
            "sources",
            "notice_blocks",
            "public_notice",
            "summary",
        },
        "RP2 Arm GNU runtime notice evidence",
    )
    _require(
        type(normalized["schema_version"]) is int
        and normalized["schema_version"] == 1
        and normalized["canonicalization"]
        == "UTF-8 JSON; sorted keys; compact separators; LF terminator",
        "RP2 Arm GNU runtime notice schema or canonicalization changed",
    )
    identity = _exact_keys(
        normalized["identity"],
        {"runtime_attribution", "source_archive"},
        "RP2 Arm GNU runtime notice identity",
    )
    _require(
        identity
        == {
            "runtime_attribution": {
                "path": _RP2_ARM_RUNTIME_ATTRIBUTION,
                "sha256": _RP2_ARM_RUNTIME_ATTRIBUTION_SHA256,
            },
            "source_archive": expected_attribution["identity"]["source_archive"],
        },
        "RP2 Arm GNU runtime notice identity changed",
    )
    _require(
        normalized["record_schemas"]
        == {
            "source": [
                "owner_id",
                "source_path",
                "source_sha256",
                "selection_reasons",
                "notice_block_indices",
            ],
            "notice_block": [
                "sha256",
                "base64",
                "first_owner_id",
                "first_source_path",
                "source_block_ordinal",
            ],
        },
        "RP2 Arm GNU runtime notice record schemas changed",
    )

    notice_owner_ids = set(_RP2_ARM_RUNTIME_NOTICE_OWNER_IDS)
    selected_sources: dict[tuple[str, str], tuple[str, set[str]]] = {}

    def add_source(
        owner_id: str,
        source_path: str,
        source_sha256: str,
        reason: str,
    ) -> None:
        if owner_id not in notice_owner_ids:
            return
        identity_key = (owner_id, source_path)
        prior_digest, reasons = selected_sources.setdefault(
            identity_key,
            (source_sha256, set()),
        )
        _require(
            prior_digest == source_sha256,
            "RP2 Arm GNU runtime notice source has conflicting digests",
        )
        reasons.add(reason)

    for row in expected_attribution["headers"]:
        add_source(row[0], row[3], row[2], "compiler-dependency-header")
    for row in expected_attribution["generated_headers"]:
        for source_path, source_sha256 in row[3]:
            if source_path.endswith(("configure", "Makefile.am", "Makefile.in")):
                continue
            add_source(
                row[0],
                source_path,
                source_sha256,
                "generated-header-template",
            )
    for row in expected_attribution["archive_members"]:
        add_source(row[0], row[4], row[5], "allocated-archive-member")
    for row in expected_attribution["direct_inputs"]:
        if row[3]:
            add_source(
                row[0],
                row[4],
                row[5],
                "contributing-direct-input",
            )
    expected_source_rows = [
        [owner_id, source_path, source_sha256, sorted(reasons)]
        for (owner_id, source_path), (source_sha256, reasons)
        in sorted(selected_sources.items())
    ]
    sources = normalized["sources"]
    _require(
        isinstance(sources, list)
        and len(sources) == len(expected_source_rows) == 96,
        "RP2 Arm GNU runtime notice source count changed",
    )
    source_rows: list[list[Any]] = []
    for index, raw_source in enumerate(sources):
        _require(
            isinstance(raw_source, list) and len(raw_source) == 5,
            "RP2 Arm GNU runtime notice source row %d changed" % index,
        )
        _require(
            raw_source[:4] == expected_source_rows[index],
            "RP2 Arm GNU runtime notice source selection changed",
        )
        indices = raw_source[4]
        _require(
            isinstance(indices, list)
            and all(type(item) is int and item >= 0 for item in indices)
            and indices == sorted(set(indices)),
            "RP2 Arm GNU runtime notice block indices changed",
        )
        source_rows.append(raw_source)

    blocks = normalized["notice_blocks"]
    _require(
        isinstance(blocks, list) and len(blocks) == 41,
        "RP2 Arm GNU runtime unique notice-block count changed",
    )
    first_uses: dict[int, tuple[str, str, int]] = {}
    occurrence_count = 0
    for owner_id, source_path, _digest, _reasons, indices in source_rows:
        for source_ordinal, block_index in enumerate(indices):
            _require(
                block_index < len(blocks),
                "RP2 Arm GNU runtime notice block index is out of range",
            )
            first_uses.setdefault(
                block_index,
                (owner_id, source_path, source_ordinal),
            )
            occurrence_count += 1
    _require(
        set(first_uses) == set(range(len(blocks))) and occurrence_count == 46,
        "RP2 Arm GNU runtime notice block occurrence closure changed",
    )
    decoded_blocks: list[bytes] = []
    block_digests: set[str] = set()
    for index, raw_block in enumerate(blocks):
        _require(
            isinstance(raw_block, list) and len(raw_block) == 5,
            "RP2 Arm GNU runtime notice block row %d changed" % index,
        )
        digest, encoded, owner_id, source_path, source_ordinal = raw_block
        _require(
            isinstance(digest, str)
            and SHA256_RE.fullmatch(digest) is not None
            and isinstance(encoded, str)
            and isinstance(owner_id, str)
            and isinstance(source_path, str)
            and type(source_ordinal) is int
            and source_ordinal >= 0
            and digest not in block_digests,
            "RP2 Arm GNU runtime notice block identity changed",
        )
        try:
            value = base64.b64decode(encoded, validate=True)
        except (ValueError, binascii.Error) as exc:
            raise ReleaseError(
                "RP2 Arm GNU runtime notice block is invalid base64"
            ) from exc
        _require(
            base64.b64encode(value).decode("ascii") == encoded
            and _sha256_bytes(value) == digest
            and b"copyright" in value.lower()
            and (owner_id, source_path, source_ordinal) == first_uses[index],
            "RP2 Arm GNU runtime notice block bytes or first use changed",
        )
        block_digests.add(digest)
        decoded_blocks.append(value)

    expected_summary = {
        "owner_count": 2,
        "source_count": 96,
        "source_count_by_owner": {
            "arm-gnu-gcc-runtime": 23,
            "arm-gnu-newlib-runtime": 73,
        },
        "source_count_by_reason": {
            "allocated-archive-member": 26,
            "compiler-dependency-header": 62,
            "contributing-direct-input": 2,
            "generated-header-template": 6,
        },
        "source_notice_block_occurrence_count": 46,
        "source_without_notice_block_count": 50,
        "unique_notice_block_count": 41,
    }
    _require(
        normalized["summary"] == expected_summary
        and sum(not row[4] for row in source_rows) == 50,
        "RP2 Arm GNU runtime notice summary changed",
    )
    public_notice_record = _exact_keys(
        normalized["public_notice"],
        {"path", "bytes", "sha256"},
        "RP2 Arm GNU runtime public notice",
    )
    _require(
        public_notice_record
        == {
            "path": _RP2_ARM_RUNTIME_PUBLIC_NOTICE,
            "bytes": _RP2_ARM_RUNTIME_PUBLIC_NOTICE_BYTES,
            "sha256": _RP2_ARM_RUNTIME_PUBLIC_NOTICE_SHA256,
        },
        "RP2 Arm GNU runtime public notice identity changed",
    )
    rendered = bytearray(
        ((
            "PyBLE RP2 Arm GNU selected runtime source notices\n\n"
            "Runtime attribution SHA-256: %s\n"
            "Source archive SHA-256: %s\n"
            "Scope: exact sources selected by compiler-dependency headers, "
            "generated-header\n"
            "content templates, allocated archive members, or contributing "
            "direct inputs.\n"
            "Excluded: build tools, generator recipe files, LOAD-only archives, "
            "and\n"
            "noncontributing direct inputs. Exact source comment bytes follow; "
            "identical\n"
            "blocks are emitted once at their first canonical (owner, source "
            "path) use.\n\n"
        ) % (
            _RP2_ARM_RUNTIME_ATTRIBUTION_SHA256,
            expected_attribution["identity"]["source_archive"]["sha256"],
        )).encode("ascii")
    )
    for raw_block, value in zip(blocks, decoded_blocks):
        digest, _encoded, owner_id, source_path, source_ordinal = raw_block
        rendered.extend(b"=" * 78 + b"\n")
        rendered.extend(
            ((
                "Owner: %s\n"
                "Source: %s\n"
                "Source block: %d\n"
                "Block SHA-256: %s\n"
            ) % (owner_id, source_path, source_ordinal, digest)).encode(
                "ascii"
            )
        )
        rendered.extend(b"-" * 78 + b"\n")
        rendered.extend(value)
        if not value.endswith(b"\n"):
            rendered.extend(b"\n")
        rendered.extend(b"\n")
    public_notice_path = _audit_repo_file(
        root,
        _RP2_ARM_RUNTIME_PUBLIC_NOTICE,
        "RP2 Arm GNU selected runtime public notice",
    )
    public_notice = _read_regular_file_bytes(
        public_notice_path,
        "RP2 Arm GNU selected runtime public notice",
    )
    _require(
        len(public_notice) == _RP2_ARM_RUNTIME_PUBLIC_NOTICE_BYTES
        and _sha256_bytes(public_notice) == _RP2_ARM_RUNTIME_PUBLIC_NOTICE_SHA256
        and public_notice == bytes(rendered),
        "RP2 Arm GNU selected runtime public notice bytes changed",
    )
    return {
        "evidence_path": evidence_path,
        "evidence_sha256": _RP2_ARM_RUNTIME_NOTICES_SHA256,
        "public_notice_path": public_notice_path,
        "public_notice_bytes": _RP2_ARM_RUNTIME_PUBLIC_NOTICE_BYTES,
        "public_notice_sha256": _RP2_ARM_RUNTIME_PUBLIC_NOTICE_SHA256,
        "public_notice_owner_ids": list(_RP2_ARM_RUNTIME_NOTICE_OWNER_IDS),
    }


def _audit_rp2_reject_driver_overrides(
    arguments: list[str],
    *,
    label: str,
    allowed_specs: set[str] | None = None,
) -> None:
    """Reject GCC arguments that can replace helpers, specs, or search roots."""

    _require(
        isinstance(arguments, list)
        and all(isinstance(item, str) and "\x00" not in item for item in arguments),
        "%s GCC argument vector is invalid" % label,
    )
    admitted_specs = set() if allowed_specs is None else set(allowed_specs)
    _require(
        all(
            isinstance(item, str)
            and item.startswith("--specs=")
            and item.count("=") == 1
            for item in admitted_specs
        ),
        "%s admitted GCC specs vector is invalid" % label,
    )
    observed_specs: list[str] = []
    for argument in arguments:
        lowered = argument.lower()
        specs_argument = (
            lowered in {"-specs", "--specs"}
            or lowered.startswith("-specs=")
            or lowered.startswith("--specs=")
        )
        if specs_argument:
            _require(
                argument in admitted_specs,
                "%s uses a GCC helper/search/spec override: %s"
                % (label, argument),
            )
            observed_specs.append(argument)
            continue
        _require(
            not (
                argument == "-B"
                or argument.startswith("-B")
                or lowered in {"-wrapper", "-fuse-ld"}
                or lowered.startswith("-wrapper=")
                or lowered.startswith("-fuse-ld=")
                or lowered == "-fplugin"
                or lowered.startswith("-fplugin=")
                or lowered == "--sysroot"
                or lowered.startswith("--sysroot=")
                or lowered == "-isysroot"
                or lowered.startswith("-isysroot=")
                or (
                    lowered.startswith("-isysroot")
                    and lowered != "-isysroot"
                )
                or argument.startswith("@")
            ),
            "%s uses a GCC helper/search/spec override: %s" % (label, argument),
        )
    _require(
        len(observed_specs) == len(admitted_specs)
        and set(observed_specs) == admitted_specs,
        "%s does not use the exact admitted GCC specs vector" % label,
    )


def _audit_observe_rp2_arm_runtime_closure(
    *,
    repo_root: Path,
    target_root: Path,
    cache: Path,
    mappings: dict[Path, Path],
    link_path: Path,
    map_loads: list[Path],
    direct_contributors: set[Path],
    archive_members: list[dict[str, Any]],
    compiler_dependency_closure: list[dict[str, Any]],
) -> tuple[dict[str, Any], dict[str, Any], set[Path]]:
    """Derive the Arm runtime vector and Eligible Compilation receipt."""

    root = Path(repo_root)
    target = Path(target_root)
    attribution_path = _audit_repo_file(
        root,
        _RP2_ARM_RUNTIME_ATTRIBUTION,
        "RP2 Arm GNU runtime attribution",
    )
    attribution = _read_json(
        attribution_path, "RP2 Arm GNU runtime attribution"
    )
    arm = _read_lock(root).get("arm_gnu_toolchain")
    _require(isinstance(arm, dict), "RP2 ARM GNU lock section is missing")

    builder_path = _audit_repo_file(
        root,
        "firmware/scripts/build_rp2.sh",
        "RP2 retained-source build driver",
    )
    builder_text = _read_regular_file_bytes(
        builder_path, "RP2 retained-source build driver"
    ).decode("utf-8", errors="strict")
    scrub_marker = (
        "# Never allow ambient compiler/make flags to influence the pinned build.\n"
        "unset \\\n"
    )
    scrub_end = '\n\nmake -C "$RETAINED_UPSTREAM/mpy-cross"'
    _require(
        builder_text.count(scrub_marker) == 1
        and builder_text.count(scrub_end) == 1,
        "RP2 build driver environment scrub is missing or ambiguous",
    )
    scrub_source = builder_text.split(scrub_marker, 1)[1].split(scrub_end, 1)[0]
    scrub_lines = scrub_source.splitlines()
    scrubbed_variables: list[str] = []
    for index, line in enumerate(scrub_lines):
        continued = line.endswith(" \\")
        value = line[:-2] if continued else line
        _require(
            line.startswith("  ")
            and re.fullmatch(r"[A-Z][A-Z0-9_]*", value.strip()) is not None
            and continued == (index < len(scrub_lines) - 1),
            "RP2 build driver environment scrub is malformed",
        )
        scrubbed_variables.append(value.strip())
    _require(
        len(scrubbed_variables) == len(set(scrubbed_variables))
        and set(_RP2_GCC_ENVIRONMENT_OVERRIDES) <= set(scrubbed_variables),
        "RP2 build driver does not scrub every GCC resolution override",
    )

    cache_text = _read_regular_file_bytes(cache, "RP2 CMake cache").decode(
        "utf-8", errors="strict"
    )
    for launcher_key in (
        "CMAKE_C_COMPILER_LAUNCHER",
        "CMAKE_CXX_COMPILER_LAUNCHER",
        "CMAKE_ASM_COMPILER_LAUNCHER",
        "RULE_LAUNCH_COMPILE",
        "RULE_LAUNCH_LINK",
    ):
        _require(
            not re.search(
                r"^%s(?::[^=]+)?=(?!$).+" % re.escape(launcher_key),
                cache_text,
                re.MULTILINE,
            ),
            "RP2 Eligible Compilation uses a compiler/link launcher",
        )

    make_root = target / "CMakeFiles" / "firmware.dir"
    flags_path = make_root / "flags.make"
    build_path = make_root / "build.make"
    flags_text = _read_regular_file_bytes(
        flags_path, "RP2 firmware target flags.make"
    ).decode("utf-8", errors="strict")
    build_text = _read_regular_file_bytes(
        build_path, "RP2 firmware target build.make"
    ).decode("utf-8", errors="strict")
    toolchain = (root / "firmware" / ".arm-gnu").resolve()
    compiler_by_language = {
        "C": (toolchain / arm["c_asm_frontend_path"]).resolve(),
        "CXX": (toolchain / arm["cxx_frontend_path"]).resolve(),
        "ASM": (toolchain / arm["c_asm_frontend_path"]).resolve(),
    }
    compile_recipes: list[dict[str, Any]] = []
    for language, compiler in compiler_by_language.items():
        _audit_regular_compile_file(compiler, "RP2 pinned %s compiler" % language)
        comment = "# compile %s with %s" % (language, compiler)
        _require(
            flags_text.count(comment) == 1,
            "RP2 flags.make lacks one pinned %s compiler identity" % language,
        )
        variable = "%s_FLAGS" % language
        match = re.search(
            r"^%s = (.*)$" % re.escape(variable), flags_text, re.MULTILINE
        )
        _require(match is not None, "RP2 flags.make lacks %s" % variable)
        try:
            arguments = shlex.split(match.group(1), posix=True)
        except ValueError as exc:
            raise ReleaseError("RP2 %s flags are malformed" % language) from exc
        _audit_rp2_reject_driver_overrides(
            arguments,
            label="RP2 %s flags" % language,
        )
        _require(
            bool(arguments)
            and os.fspath(compiler) in build_text
            and not any(
                token.lower() == "-flto"
                or token.lower().startswith("-flto=")
                or token.lower() == "-fplugin"
                or token.lower().startswith("-fplugin=")
                for token in arguments
            ),
            "RP2 %s compilation recipe is not eligible" % language,
        )
        compile_recipes.append(
            {
                "language": language,
                "driver": compiler.relative_to(toolchain).as_posix(),
                "arguments": arguments,
            }
        )
    # Every mapped target-code object must have exactly one concrete compile
    # recipe using the language-appropriate pinned driver. This checks the
    # generated rules themselves, rather than inferring use from flags alone.
    compile_rule_outputs: set[Path] = set()
    compile_make_paths = sorted(target.rglob("build.make"))
    compile_flags_paths: set[Path] = set()
    for compile_make in compile_make_paths:
        make_text = _read_regular_file_bytes(
            compile_make, "RP2 generated target build.make"
        ).decode("utf-8", errors="strict")
        for raw_line in make_text.splitlines():
            if not raw_line.startswith("\t") or " -c " not in raw_line or " -o " not in raw_line:
                continue
            try:
                words = shlex.split(raw_line.strip(), posix=True)
            except ValueError as exc:
                raise ReleaseError("RP2 target compile rule is malformed") from exc
            command_cwd = target
            if len(words) >= 4 and words[0] == "cd" and words[2] == "&&":
                command_cwd = _audit_rp2_admitted_path(
                    words[1],
                    relative_to=target,
                    roots=(target,),
                    label="RP2 target compile-rule working directory",
                )
                words = words[3:]
            if words.count("-c") != 1 or words.count("-o") != 1:
                continue
            output_raw = Path(words[words.index("-o") + 1])
            output_candidate = (
                output_raw if output_raw.is_absolute() else command_cwd / output_raw
            ).resolve(strict=False)
            if output_candidate not in mappings:
                # Host-only Pico SDK utilities are generated beneath the same
                # CMake tree. They are not target-code inputs and need not
                # survive a retained firmware build.
                continue
            _audit_rp2_reject_driver_overrides(
                words,
                label="RP2 target-code compile rule",
            )
            output = _audit_rp2_admitted_path(
                os.fspath(output_raw),
                relative_to=command_cwd,
                roots=(target,),
                label="RP2 target compile-rule output",
            )
            source = _audit_rp2_admitted_path(
                words[words.index("-c") + 1],
                relative_to=command_cwd,
                roots=(target, target.parent, root),
                label="RP2 target compile-rule source",
            )
            language = (
                "CXX" if source.suffix in {".cc", ".cpp", ".cxx"} else
                "ASM" if source.suffix.lower() in {".s", ".asm"} else "C"
            )
            _require(
                mappings[output].resolve() == source.resolve()
                and Path(words[0]).resolve() == compiler_by_language[language]
                and output not in compile_rule_outputs
                and not any(
                    token.lower() == "-flto"
                    or token.lower().startswith("-flto=")
                    or token.lower() == "-fplugin"
                    or token.lower().startswith("-fplugin=")
                    for token in words
                ),
                "RP2 target-code compile rule changed driver, source, or flags",
            )
            compile_rule_outputs.add(output)
            local_flags = compile_make.parent / "flags.make"
            _audit_regular_compile_file(local_flags, "RP2 target flags.make")
            flags_text_value = _read_regular_file_bytes(
                local_flags, "RP2 target flags.make"
            ).decode("utf-8", errors="strict")
            for flags_match in re.finditer(
                r"^(?:ASM|C|CXX)_FLAGS = (.*)$",
                flags_text_value,
                re.MULTILINE,
            ):
                try:
                    local_arguments = shlex.split(flags_match.group(1), posix=True)
                except ValueError as exc:
                    raise ReleaseError("RP2 target flags are malformed") from exc
                _audit_rp2_reject_driver_overrides(
                    local_arguments,
                    label="RP2 target flags",
                )
            flags_value = flags_text_value.lower()
            _require(
                "-flto" not in flags_value and "-fplugin" not in flags_value,
                "RP2 target flags use an ineligible IR/plugin path",
            )
            compile_flags_paths.add(local_flags)
    _require(
        compile_rule_outputs == set(mappings),
        "RP2 target-code compile recipe inventory is incomplete or extra",
    )
    depfiles = sorted(
        Path(os.fspath(output) + ".d").resolve()
        for output in mappings
        if Path(os.fspath(output) + ".d").is_file()
    )
    _require(bool(depfiles), "RP2 Eligible Compilation has no compiler depfiles")

    link_text = _read_regular_file_bytes(
        link_path, "RP2 linker command"
    ).decode("utf-8", errors="strict").rstrip("\n")
    try:
        link_words = shlex.split(link_text, posix=True)
    except ValueError as exc:
        raise ReleaseError("RP2 linker command is malformed") from exc
    _require(
        bool(link_words)
        and Path(link_words[0]).resolve() == compiler_by_language["CXX"],
        "RP2 Eligible Compilation link driver changed",
    )
    _audit_rp2_reject_driver_overrides(
        link_words[1:],
        label="RP2 linker command",
        allowed_specs={"--specs=nosys.specs"},
    )

    expected_build_tools: list[list[str]] = []
    for owner_id, relative, digest, purpose in attribution["build_tools"]:
        tool = _audit_repo_file(toolchain, relative, "RP2 Arm GNU build tool")
        _require(
            _sha256_path(tool) == digest,
            "RP2 Arm GNU build tool bytes changed: %s" % relative,
        )
        expected_build_tools.append([owner_id, relative, digest, purpose])

    helper_query = {
        "assembler": (compiler_by_language["C"], "as"),
        "linker": (compiler_by_language["CXX"], "ld"),
        "collect2": (compiler_by_language["CXX"], "collect2"),
    }
    resolved_helpers: dict[str, Path] = {}
    for purpose, (driver, program) in helper_query.items():
        try:
            completed = subprocess.run(
                [os.fspath(driver), "-print-prog-name=%s" % program],
                cwd=target,
                env={"LANG": "C", "LC_ALL": "C", "PATH": "/usr/bin:/bin"},
                stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                check=False,
                timeout=30,
            )
        except (OSError, subprocess.SubprocessError) as exc:
            raise ReleaseError("RP2 compiler helper resolution failed") from exc
        _require(
            completed.returncode == 0
            and completed.stdout.count("\n") <= 1
            and bool(completed.stdout.strip()),
            "RP2 compiler helper resolution failed",
        )
        resolved_helpers[purpose] = Path(completed.stdout.strip()).resolve()
    expected_helpers = {
        purpose: (toolchain / relative).resolve()
        for _owner, relative, _digest, purpose in expected_build_tools
        if purpose in helper_query
    }
    _require(
        resolved_helpers == expected_helpers,
        "RP2 GCC driver resolves substituted assembler/linker/collect2 helpers",
    )

    expected_specs_inputs = attribution["specs_inputs"]
    _require(
        isinstance(expected_specs_inputs, list)
        and len(expected_specs_inputs) == 1
        and isinstance(expected_specs_inputs[0], list)
        and len(expected_specs_inputs[0]) == 10,
        "RP2 GCC specs attribution is not one exact row",
    )
    (
        specs_owner,
        specs_token,
        specs_relative,
        specs_bytes,
        specs_sha256,
        specs_source_relative,
        specs_source_bytes,
        specs_source_sha256,
        specs_basis,
        specs_contributes,
    ) = expected_specs_inputs[0]
    _require(
        specs_token == "--specs=nosys.specs"
        and link_words[1:].count(specs_token) == 1
        and specs_owner == "arm-gnu-libgloss-runtime"
        and specs_basis == "libgloss-default-compilation"
        and specs_contributes is False,
        "RP2 GCC specs token, owner, basis, or contribution changed",
    )
    try:
        specs_query = subprocess.run(
            [
                os.fspath(compiler_by_language["CXX"]),
                specs_token,
                "-print-file-name=%s" % Path(specs_relative).name,
            ],
            cwd=target,
            env={"LANG": "C", "LC_ALL": "C", "PATH": "/usr/bin:/bin"},
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=False,
            timeout=30,
        )
    except (OSError, subprocess.SubprocessError) as exc:
        raise ReleaseError("RP2 GCC specs resolution failed") from exc
    _require(
        specs_query.returncode == 0
        and specs_query.stdout.count("\n") <= 1
        and bool(specs_query.stdout.strip())
        and specs_query.stdout.strip() != Path(specs_relative).name,
        "RP2 GCC specs resolution is missing or ambiguous",
    )
    resolved_specs = Path(specs_query.stdout.strip()).resolve()
    expected_specs = (toolchain / specs_relative).resolve()
    _require(
        resolved_specs == expected_specs,
        "RP2 GCC driver resolves a substituted specs input",
    )
    specs_value = _read_regular_file_bytes(
        resolved_specs, "RP2 resolved GCC specs input"
    )
    _require(
        len(specs_value) == specs_bytes
        and _sha256_bytes(specs_value) == specs_sha256,
        "RP2 resolved GCC specs bytes changed",
    )

    retained_source_archive = (
        root
        / "firmware"
        / ".arm-gnu"
        / ".pyble-dist"
        / arm["source_archive_filename"]
    )
    _audit_regular_compile_file(
        retained_source_archive, "RP2 retained Arm GNU source archive"
    )
    try:
        with tarfile.open(retained_source_archive, mode="r:xz") as handle:
            source_matches = [
                member
                for member in handle.getmembers()
                if member.name == specs_source_relative
            ]
            _require(
                len(source_matches) == 1
                and source_matches[0].isfile()
                and not source_matches[0].issym()
                and not source_matches[0].islnk()
                and source_matches[0].size == specs_source_bytes,
                "RP2 source snapshot GCC specs member changed",
            )
            extracted = handle.extractfile(source_matches[0])
            _require(
                extracted is not None,
                "RP2 source snapshot GCC specs member is unreadable",
            )
            specs_source_value = extracted.read()
    except (OSError, tarfile.TarError) as exc:
        raise ReleaseError("RP2 retained Arm GNU source archive is unreadable") from exc
    _require(
        len(specs_source_value) == specs_source_bytes
        and _sha256_bytes(specs_source_value) == specs_source_sha256
        and specs_source_value == specs_value,
        "RP2 installed GCC specs differs from its exact source snapshot file",
    )
    observed_specs_inputs = [
        [
            specs_owner,
            specs_token,
            resolved_specs.relative_to(toolchain).as_posix(),
            len(specs_value),
            _sha256_bytes(specs_value),
            specs_source_relative,
            len(specs_source_value),
            _sha256_bytes(specs_source_value),
            specs_basis,
            False,
        ]
    ]

    load_by_relative = {
        path.resolve().relative_to(toolchain).as_posix(): path.resolve()
        for path in map_loads
        if path.resolve().is_relative_to(toolchain)
    }
    archive_member_counts = Counter(
        record["archive"].resolve()
        for record in archive_members
        for _digest in record["member_sha256"]
    )
    runtime_archives: list[list[Any]] = []
    for owner_id, relative, digest, _count in attribution["runtime_archives"]:
        path = load_by_relative.get(relative)
        _require(path is not None, "RP2 runtime archive is absent from map LOAD")
        count = archive_member_counts[path]
        runtime_archives.append([owner_id, relative, _sha256_path(path), count])

    direct_inputs: list[list[Any]] = []
    for frozen in attribution["direct_inputs"]:
        owner_id, relative, _digest, _contributes, source, source_digest, basis = frozen
        path = load_by_relative.get(relative)
        _require(path is not None, "RP2 direct runtime input is absent from map LOAD")
        direct_inputs.append(
            [
                owner_id,
                relative,
                _sha256_path(path),
                path in direct_contributors,
                source,
                source_digest,
                basis,
            ]
        )

    frozen_members = {
        (item[1], item[2], item[3]): item for item in attribution["archive_members"]
    }
    observed_member_by_identity: dict[tuple[str, str, str], list[Any]] = {}
    archive_name_by_path = {
        load_by_relative[item[1]].resolve(): item[1].rsplit("/", 1)[-1]
        for item in attribution["runtime_archives"]
    }
    for record in archive_members:
        archive_name = archive_name_by_path.get(record["archive"].resolve())
        _require(archive_name is not None, "RP2 allocated member has an unknown archive")
        _require(
            record["multiplicity"] == len(record["member_sha256"]),
            "RP2 allocated archive/member multiplicity changed",
        )
        for digest in record["member_sha256"]:
            frozen = frozen_members.get((archive_name, record["member"], digest))
            _require(
                frozen is not None,
                "RP2 allocated archive/member lacks an exact source mapping",
            )
            identity = (archive_name, record["member"], digest)
            _require(
                identity not in observed_member_by_identity,
                "RP2 allocated archive/member identity is duplicated",
            )
            observed_member_by_identity[identity] = copy.deepcopy(frozen)
    _require(
        set(observed_member_by_identity) == set(frozen_members),
        "RP2 allocated archive/member closure is incomplete or extra",
    )
    observed_members = [
        observed_member_by_identity[(item[1], item[2], item[3])]
        for item in attribution["archive_members"]
    ]

    closure_dependencies = {
        dependency["logical_path"]: dependency
        for record in compiler_dependency_closure
        for dependency in record["dependencies"]
        if dependency["logical_path"].startswith("repo/firmware/.arm-gnu/")
    }
    headers: list[list[Any]] = []
    generated_headers: list[list[Any]] = []
    for frozen in attribution["headers"]:
        logical = "repo/firmware/.arm-gnu/" + frozen[1]
        dependency = closure_dependencies.get(logical)
        _require(
            dependency is not None
            and dependency["owner_id"] == frozen[0],
            "RP2 Arm GNU header is absent or has a different owner",
        )
        headers.append(
            [frozen[0], frozen[1], dependency["sha256"], frozen[3]]
        )
    for frozen in attribution["generated_headers"]:
        logical = "repo/firmware/.arm-gnu/" + frozen[1]
        dependency = closure_dependencies.get(logical)
        _require(
            dependency is not None
            and dependency["owner_id"] == frozen[0],
            "RP2 generated Arm GNU header is absent or has a different owner",
        )
        generated_headers.append(
            [frozen[0], frozen[1], dependency["sha256"], frozen[3], frozen[4]]
        )
    expected_header_paths = {
        "repo/firmware/.arm-gnu/" + item[1]
        for item in attribution["headers"] + attribution["generated_headers"]
    }
    _require(
        set(closure_dependencies) == expected_header_paths,
        "RP2 Arm GNU compiler-header closure is incomplete or extra",
    )

    observed = {
        "identity": {
            "binary_archive": {
                "bytes": arm["archive_bytes"],
                "filename": arm["archive_filename"],
                "sha256": arm["sha256"],
            },
            "source_archive": {
                "bytes": arm["source_archive_bytes"],
                "filename": arm["source_archive_filename"],
                "sha256": arm["source_archive_sha256"],
            },
            "source_manifest": {
                "path": arm["source_manifest_path"],
                "sha256": arm["source_manifest_sha256"],
            },
            "source_commits": copy.deepcopy(attribution["identity"]["source_commits"]),
        },
        "runtime_archives": runtime_archives,
        "specs_inputs": observed_specs_inputs,
        "direct_inputs": direct_inputs,
        "archive_members": observed_members,
        "headers": headers,
        "generated_headers": generated_headers,
    }
    observed["build_tools"] = expected_build_tools
    observed["eligible_compilation_receipt"] = {
        "bound_kinds": list(
            attribution["eligible_compilation"]["required_receipt_kinds"]
        ),
        "compiler_launchers": [],
        "driver_environment_overrides": [],
        "external_ir_consumers": [],
        "compile_recipes": compile_recipes,
        "link_driver": compiler_by_language["CXX"].relative_to(toolchain).as_posix(),
        "link_arguments": link_words[1:],
        "resolved_specs_inputs": copy.deepcopy(observed_specs_inputs),
        "source_archive_sha256": arm["source_archive_sha256"],
    }
    result = _audit_validate_rp2_arm_runtime_closure(
        attribution,
        observed,
        repo_root=root,
    )
    runtime_notices_path = _audit_repo_file(
        root,
        _RP2_ARM_RUNTIME_NOTICES,
        "RP2 Arm GNU runtime notice evidence",
    )
    runtime_notices = _read_json(
        runtime_notices_path,
        "RP2 Arm GNU runtime notice evidence",
    )
    runtime_notice_result = _audit_validate_rp2_arm_runtime_notices(
        attribution,
        runtime_notices,
        repo_root=root,
    )
    _require(
        runtime_notice_result["public_notice_owner_ids"]
        == result["public_notice_owner_ids"],
        "RP2 Arm GNU runtime notice owners differ from contribution closure",
    )
    result["runtime_notices"] = {
        "evidence_path": _RP2_ARM_RUNTIME_NOTICES,
        "evidence_sha256": runtime_notice_result["evidence_sha256"],
        "public_notice_path": _RP2_ARM_RUNTIME_PUBLIC_NOTICE,
        "public_notice_bytes": runtime_notice_result["public_notice_bytes"],
        "public_notice_sha256": runtime_notice_result["public_notice_sha256"],
        "public_notice_owner_ids": copy.deepcopy(
            runtime_notice_result["public_notice_owner_ids"]
        ),
    }
    evidence_paths = {
        attribution_path,
        runtime_notice_result["evidence_path"],
        runtime_notice_result["public_notice_path"],
        builder_path,
        retained_source_archive,
        resolved_specs,
        cache,
        flags_path,
        build_path,
        link_path,
        target / "firmware.elf.map",
        target / "firmware.elf",
        target / "firmware.bin",
        target / "firmware.uf2",
        *depfiles,
        *compile_make_paths,
        *compile_flags_paths,
    }
    for evidence in evidence_paths:
        _audit_regular_compile_file(evidence, "RP2 Eligible Compilation evidence")
    return observed, result, evidence_paths


def _audit_rp2_owner_for_path(
    owners: list[dict[str, Any]],
    *,
    namespace: str,
    logical_path: str,
) -> dict[str, Any]:
    matches: list[tuple[int, dict[str, Any]]] = []
    for owner in owners:
        for source_root in owner["source_roots"]:
            if source_root["namespace"] != namespace:
                continue
            root_path = source_root["path"].rstrip("/")
            if logical_path == root_path or logical_path.startswith(root_path + "/"):
                matches.append((len(PurePosixPath(root_path).parts), owner))
    _require(
        bool(matches),
        "RP2 linked input has no license owner: %s/%s"
        % (namespace, logical_path),
    )
    specificity = max(length for length, _owner in matches)
    winners = {
        owner["id"]: owner
        for length, owner in matches
        if length == specificity
    }
    _require(
        len(winners) == 1,
        "RP2 linked input has ambiguous license owners: %s/%s"
        % (namespace, logical_path),
    )
    return next(iter(winners.values()))


def _audit_rp2_admitted_path(
    raw_path: str | Path,
    *,
    relative_to: Path,
    roots: tuple[Path, ...],
    label: str,
) -> Path:
    """Resolve one RP2 build operand only after lexical symlink checks."""

    value = Path(raw_path)
    lexical = value if value.is_absolute() else Path(relative_to) / value
    # Preserve literal parents until every traversed component is checked;
    # ``link/../file`` must still inspect ``link`` before normalization.
    absolute = lexical.absolute()
    for root in roots:
        for lexical_root in (Path(root).absolute(), Path(root).resolve()):
            try:
                absolute.relative_to(lexical_root)
            except ValueError:
                continue
            _audit_no_symlink_components(lexical_root, absolute, label)
            try:
                resolved = absolute.resolve(strict=True)
                resolved.relative_to(Path(root).resolve())
            except (OSError, ValueError) as exc:
                raise ReleaseError("%s escapes or is missing" % label) from exc
            return resolved
    raise ReleaseError("%s escapes its admitted RP2 roots" % label)


def _audit_rp2_depend_info(
    path: Path,
    *,
    target_root: Path,
    repo_root: Path,
    source_root: Path,
) -> dict[Path, Path]:
    text = _read_regular_file_bytes(path, "RP2 CMake DependInfo").decode(
        "utf-8", errors="strict"
    )
    dependency_match = re.search(
        r"set\(CMAKE_DEPENDS_DEPENDENCY_FILES\s*(.*?)\s*\)",
        text,
        re.DOTALL,
    )
    try:
        dependency_tokens = (
            shlex.split(dependency_match.group(1), posix=True)
            if dependency_match is not None
            else []
        )
    except ValueError as exc:
        raise ReleaseError("RP2 CMake DependInfo mapping is malformed") from exc
    _require(
        len(dependency_tokens) % 4 == 0,
        "RP2 CMake DependInfo mapping is incomplete",
    )
    asm_match = re.search(
        r"set\(CMAKE_DEPENDS_CHECK_ASM\s*(.*?)\s*\)",
        text,
        re.DOTALL,
    )
    try:
        asm_tokens = (
            shlex.split(asm_match.group(1), posix=True)
            if asm_match is not None
            else []
        )
    except ValueError as exc:
        raise ReleaseError("RP2 CMake ASM mapping is malformed") from exc
    _require(
        len(asm_tokens) % 2 == 0
        and bool(dependency_tokens or asm_tokens),
        "RP2 CMake source/object mapping is missing or incomplete",
    )
    result: dict[Path, Path] = {}
    sources: set[Path] = set()

    def add_mapping(
        source_raw: str,
        output_raw: str,
        *,
        language: str,
        dependency_raw: str | None,
    ) -> None:
        _require(
            language in {"gcc", "asm", "cxx"},
            "RP2 CMake DependInfo language is unknown",
        )
        source = _audit_rp2_admitted_path(
            source_raw,
            relative_to=target_root,
            roots=(target_root, source_root, repo_root),
            label="RP2 CMake DependInfo source",
        )
        output = _audit_rp2_admitted_path(
            output_raw,
            relative_to=target_root,
            roots=(target_root,),
            label="RP2 CMake DependInfo output",
        )
        dependency = None
        if dependency_raw is not None:
            dependency = _audit_rp2_admitted_path(
                dependency_raw,
                relative_to=target_root,
                roots=(target_root,),
                label="RP2 CMake dependency file",
            )
        _require(
            source.is_relative_to(repo_root.resolve())
            or source.is_relative_to(source_root.resolve())
            or source.is_relative_to(target_root.resolve()),
            "RP2 CMake DependInfo source escapes admitted roots",
        )
        _require(
            not source.is_relative_to(
                (repo_root / "firmware" / "upstream" / "micropython").resolve()
            ),
            "RP2 CMake DependInfo uses canonical rather than retained source",
        )
        _require(
            output.is_relative_to(target_root.resolve())
            and (
                dependency is None
                or (
                    dependency.is_relative_to(target_root.resolve())
                    and output != dependency
                    and dependency == Path(os.fspath(output) + ".d").resolve()
                )
            ),
            "RP2 CMake DependInfo output/depfile mapping escapes or is ambiguous",
        )
        _audit_regular_compile_file(source, "RP2 compiled source")
        _audit_regular_compile_file(output, "RP2 linked object")
        _require(
            output not in result and source not in sources,
            "RP2 CMake DependInfo source/object mapping is not bijective",
        )
        result[output] = source
        sources.add(source)

    for index in range(0, len(dependency_tokens), 4):
        source_raw, output_raw, language, dependency_raw = dependency_tokens[
            index : index + 4
        ]
        add_mapping(
            source_raw,
            output_raw,
            language=language,
            dependency_raw=dependency_raw,
        )
    for index in range(0, len(asm_tokens), 2):
        add_mapping(
            asm_tokens[index],
            asm_tokens[index + 1],
            language="asm",
            dependency_raw=None,
        )
    return result


def _audit_rp2_bootstage_mapping(
    *,
    target_root: Path,
) -> tuple[dict[Path, Path], Path]:
    """Bind the separately generated RP2350 bootstage source/object pair."""

    dependency = (
        target_root
        / "pico-sdk"
        / "src"
        / "rp2350"
        / "boot_stage2"
        / "CMakeFiles"
        / "bs2_default_library.dir"
        / "DependInfo.cmake"
    )
    if not dependency.is_file():
        return {}, dependency
    text = _read_regular_file_bytes(
        dependency, "RP2 bootstage DependInfo"
    ).decode("utf-8", errors="strict")
    match = re.search(
        r"set\(CMAKE_DEPENDS_CHECK_ASM\s*(.*?)\s*\)",
        text,
        re.DOTALL,
    )
    _require(match is not None, "RP2 bootstage source/object mapping is missing")
    try:
        tokens = shlex.split(match.group(1), posix=True)
    except ValueError as exc:
        raise ReleaseError("RP2 bootstage source/object mapping is malformed") from exc
    _require(
        len(tokens) == 2,
        "RP2 bootstage source/object mapping is not exact",
    )
    source = _audit_rp2_admitted_path(
        tokens[0],
        relative_to=target_root,
        roots=(target_root,),
        label="RP2 bootstage generated source",
    )
    output = _audit_rp2_admitted_path(
        tokens[1],
        relative_to=target_root,
        roots=(target_root,),
        label="RP2 bootstage output",
    )
    expected_source = (
        target_root
        / "pico-sdk"
        / "src"
        / "rp2350"
        / "boot_stage2"
        / "bs2_default_padded_checksummed.S"
    ).resolve()
    expected_output = (
        target_root
        / "pico-sdk"
        / "src"
        / "rp2350"
        / "boot_stage2"
        / "CMakeFiles"
        / "bs2_default_library.dir"
        / "bs2_default_padded_checksummed.S.o"
    ).resolve()
    _require(
        source == expected_source and output == expected_output,
        "RP2 bootstage derivation path is substituted",
    )
    _audit_regular_compile_file(source, "RP2 generated bootstage source")
    _audit_regular_compile_file(output, "RP2 linked bootstage object")
    return {output: source}, dependency


def _audit_rp2_link_arguments(
    path: Path,
    *,
    target_root: Path,
    repo_root: Path,
) -> list[Path]:
    text = _read_regular_file_bytes(path, "RP2 linker command").decode(
        "utf-8", errors="strict"
    )
    command = text[:-1] if text.endswith("\n") else text
    _require(
        "\n" not in command
        and "\r" not in command
        and all(token not in command for token in (";", "`", "$(", "${", "|", "&&")),
        "RP2 linker command contains shell control",
    )
    try:
        tokens = shlex.split(command, posix=True)
    except ValueError as exc:
        raise ReleaseError("RP2 linker command is malformed") from exc
    _require(bool(tokens), "RP2 linker command is empty")
    inputs: list[Path] = []
    seen: set[Path] = set()
    for token in tokens[1:]:
        _require(
            not token.startswith("@") and not token.startswith("-Wl,@"),
            "RP2 linker response files are forbidden",
        )
        if token.startswith("-") or token == "firmware.elf":
            continue
        if not token.endswith((".o", ".obj", ".a")):
            continue
        candidate = _audit_rp2_admitted_path(
            token,
            relative_to=target_root,
            roots=(target_root, repo_root),
            label="RP2 linker input",
        )
        _audit_regular_compile_file(candidate, "RP2 linker input")
        _require(candidate not in seen, "RP2 linker input is duplicated")
        seen.add(candidate)
        inputs.append(candidate)
    _require(bool(inputs), "RP2 linker command contains no admitted inputs")
    return inputs


def _audit_rp2_replay_implicit_inputs(
    path: Path,
    *,
    target_root: Path,
    repo_root: Path,
    explicit_inputs: list[Path],
    map_implicit_inputs: list[Path],
) -> None:
    """Prove compiler-injected LOAD paths by a traced, scratch-only relink."""

    if not map_implicit_inputs:
        return
    command = _read_regular_file_bytes(path, "RP2 linker command").decode(
        "utf-8", errors="strict"
    ).rstrip("\n")
    try:
        tokens = shlex.split(command, posix=True)
    except ValueError as exc:
        raise ReleaseError("RP2 linker command is malformed") from exc
    compiler = _audit_rp2_admitted_path(
        tokens[0],
        relative_to=target_root,
        roots=(repo_root / "firmware" / ".arm-gnu",),
        label="RP2 pinned linker driver",
    )
    toolchain_root = (repo_root / "firmware" / ".arm-gnu").resolve()
    _require(
        compiler.is_relative_to(toolchain_root / "bin"),
        "RP2 implicit inputs require the pinned ARM GNU compiler",
    )
    _audit_regular_compile_file(compiler, "RP2 pinned linker driver")
    arguments: list[str] = []
    skip_output = False
    for token in tokens[1:]:
        if skip_output:
            skip_output = False
            continue
        if token == "-o":
            skip_output = True
            continue
        if token.startswith("-Wl,-Map=") or token.startswith("-Wl,-Map,"):
            continue
        arguments.append(token)
    _require(not skip_output, "RP2 linker output operand is incomplete")
    with tempfile.TemporaryDirectory(prefix="pyble-rp2-link-replay-") as raw:
        scratch = Path(raw)
        replay_map = scratch / "firmware.elf.map"
        replay_elf = scratch / "firmware.elf"
        environment = {
            "HOME": os.fspath(scratch),
            "LANG": "C",
            "LC_ALL": "C",
            "PATH": "/usr/bin:/bin",
            "TMPDIR": os.fspath(scratch),
        }
        try:
            completed = subprocess.run(
                [
                    os.fspath(compiler),
                    *arguments,
                    "-Wl,-t",
                    "-Wl,-Map=%s" % replay_map,
                    "-o",
                    os.fspath(replay_elf),
                ],
                cwd=target_root,
                env=environment,
                stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                check=False,
                timeout=120,
            )
        except (OSError, subprocess.SubprocessError) as exc:
            raise ReleaseError("RP2 traced linker replay failed") from exc
        _require(
            completed.returncode == 0
            and replay_elf.is_file()
            and replay_map.is_file(),
            "RP2 traced linker replay failed",
        )
        traced: list[Path] = []
        for line in completed.stdout.splitlines():
            value = line.strip()
            if not value.endswith((".o", ".obj", ".a")):
                continue
            candidate = _audit_rp2_admitted_path(
                value,
                relative_to=target_root,
                roots=(target_root, toolchain_root),
                label="RP2 traced linker input",
            )
            _audit_regular_compile_file(candidate, "RP2 traced linker input")
            traced.append(candidate)
    explicit = set(explicit_inputs)
    traced_implicit = [item for item in traced if item not in explicit]
    expected_counts = Counter(map_implicit_inputs)
    traced_counts = Counter(traced_implicit)
    _require(
        set(expected_counts) == set(traced_counts)
        and all(
            expected_counts[path_value] <= traced_counts[path_value]
            for path_value in expected_counts
        ),
        "RP2 map implicit LOADs differ from pinned driver/spec replay",
    )


def _audit_rp2_map_records(
    path: Path,
    *,
    target_root: Path,
    repo_root: Path,
) -> tuple[list[Path], set[Path], list[dict[str, Any]]]:
    text = _read_regular_file_bytes(path, "RP2 linker map").decode(
        "utf-8", errors="strict"
    )
    loads: list[Path] = []
    direct_contributors: set[Path] = set()
    archive_sections: set[tuple[Path, str]] = set()
    included_members: list[tuple[Path, str]] = []

    def resolve(raw: str) -> Path:
        candidate = _audit_rp2_admitted_path(
            raw,
            relative_to=target_root,
            roots=(target_root, repo_root),
            label="RP2 linker map input",
        )
        _audit_regular_compile_file(candidate, "RP2 linker map input")
        return candidate

    lines = text.splitlines()
    in_archive_inventory = bool(lines) and lines[0] == (
        "Archive member included to satisfy reference by file (symbol)"
    )
    for line in lines:
        if in_archive_inventory:
            member_match = re.fullmatch(r"(\S+\.a)\(([^()/]+)\)", line)
            if member_match is not None:
                included_members.append(
                    (resolve(member_match.group(1)), member_match.group(2))
                )
                continue
            if line.startswith("Discarded input sections"):
                in_archive_inventory = False
        load_match = re.fullmatch(r"LOAD (\S+)", line)
        if load_match is not None:
            candidate = resolve(load_match.group(1))
            loads.append(candidate)
            continue
        contribution = re.fullmatch(
            r"\s+(?:\.\S+\s+)?(0x[0-9A-Fa-f]+)\s+"
            r"(0x[0-9A-Fa-f]+)\s+(\S+?)(?:\(([^()/]+)\))?",
            line,
        )
        if (
            contribution is not None
            and int(contribution.group(1), 16) > 0
            and int(contribution.group(2), 16) > 0
        ):
            source = resolve(contribution.group(3))
            member = contribution.group(4)
            if member is None:
                direct_contributors.add(source)
            else:
                archive_sections.add((source, member))
    _require(bool(loads), "RP2 linker map has no LOAD inventory")
    _require(
        direct_contributors <= set(loads),
        "RP2 linker map contribution is absent from its LOAD inventory",
    )
    inventory_counts: Counter[tuple[Path, str]] = Counter(included_members)
    _require(
        archive_sections <= set(inventory_counts),
        "RP2 allocated archive/member is absent from inclusion inventory",
    )
    archive_members: list[dict[str, Any]] = []
    for (archive, member), count in sorted(
        (
            (identity, inventory_counts[identity])
            for identity in archive_sections
        ),
        key=lambda item: (os.fspath(item[0][0]), item[0][1]),
    ):
        payloads = _audit_ar_member_payloads(archive).get(member, [])
        _require(
            len(payloads) == count,
            "RP2 archive/member multiplicity differs from archive bytes",
        )
        archive_members.append(
            {
                "archive": archive,
                "member": member,
                "multiplicity": count,
                "member_sha256": [
                    _sha256_bytes(payload) for payload in payloads
                ],
            }
        )
    return loads, direct_contributors, archive_members


def _audit_rp2_source_identity(
    *,
    source_root: Path,
    repo_root: Path,
    provenance: dict[str, Any],
) -> dict[str, Any]:
    micropython = _exact_keys(
        provenance.get("micropython"),
        {"commit"},
        "RP2 MicroPython provenance",
    )
    lock_micropython = _read_lock(Path(repo_root)).get("micropython")
    _require(
        isinstance(lock_micropython, dict),
        "RP2 versions.lock MicroPython identity is missing",
    )
    commit = _git_output(source_root, "retained MicroPython", "rev-parse", "HEAD")
    origin = _git_output(
        source_root, "retained MicroPython", "remote", "get-url", "origin"
    )
    _require_checkout_clean(
        source_root,
        "retained MicroPython",
        allow_micropython_generated=True,
    )
    _require(
        micropython["commit"] == commit
        and lock_micropython.get("commit") == commit
        and lock_micropython.get("repo") == origin,
        "RP2 retained MicroPython commit/origin differs from provenance",
    )
    return {
        "micropython_commit": commit,
        "rp2_port_tree_sha256": _audit_v060_tree_sha256(
            source_root / "ports" / "rp2",
            "retained MicroPython/rp2 source",
        ),
        "arm_gnu_toolchain": copy.deepcopy(provenance.get("arm_gnu_toolchain")),
    }


def _audit_rp2_logical_path(
    path: Path,
    *,
    repo_root: Path,
    build_root: Path,
) -> str:
    resolved = path.resolve()
    # A conventional build root may be nested below the checkout.  Persist it
    # in the narrower build namespace so receipts are independent of layout.
    for prefix, root in (("build", build_root), ("repo", repo_root)):
        try:
            relative = resolved.relative_to(root.resolve())
        except ValueError:
            continue
        return "%s/%s" % (prefix, relative.as_posix())
    raise ReleaseError("RP2 audit input is outside its logical namespaces")


def _audit_rp2_policy_asset_logical(path: str) -> str:
    return path if path.startswith(("repo/", "build/")) else "repo/" + path


def _audit_rp2_selected_license_ids(owner: dict[str, Any]) -> set[str]:
    return _AuditSpdxExpressionParser(
        owner["selected_spdx_expression"]
    ).parse()


def _audit_rp2_checkout_identity(
    owner: dict[str, Any],
    *,
    source_root: Path,
    repo_root: Path,
    provenance: dict[str, Any],
) -> None:
    namespaces = {item["namespace"] for item in owner["source_roots"]}
    if namespaces == {"repo"}:
        pyble = _exact_keys(
            provenance.get("pyble"),
            {"commit", "clean"},
            "RP2 PyBLE provenance",
        )
        source_version = _read_lock(Path(repo_root))["pyble"]["agent_version"]
        _require(
            pyble["clean"] is True
            and isinstance(pyble["commit"], str)
            and COMMIT_RE.fullmatch(pyble["commit"]) is not None
            and owner["source_ref"] == source_version
            and owner["source_url"] == "https://github.com/PyBLE-dev/PyBLE",
            "RP2 first-party source identity changed",
        )
        if (Path(repo_root) / ".git").exists():
            head = _git_output(Path(repo_root), "PyBLE", "rev-parse", "HEAD")
            _require_checkout_clean(Path(repo_root), "PyBLE")
            _require(
                head == pyble["commit"],
                "RP2 PyBLE provenance commit is not checkout HEAD",
            )
        return
    if namespaces == {"arm-gnu-toolchain"}:
        toolchain = provenance.get("arm_gnu_toolchain")
        _require(
            isinstance(toolchain, dict)
            and toolchain.get("release") == owner["source_ref"],
            "RP2 ARM GNU runtime source identity changed",
        )
        return
    _require(
        namespaces == {"micropython"},
        "RP2 owner mixes source namespaces",
    )
    first = source_root / owner["source_roots"][0]["path"]
    probe = first if first.is_dir() else first.parent
    checkout = Path(
        _git_output(probe, "retained dependency", "rev-parse", "--show-toplevel")
    ).resolve()
    _require(
        checkout.is_relative_to(source_root.resolve()),
        "RP2 dependency resolves outside retained source",
    )
    _require_checkout_clean(
        checkout,
        "retained dependency %s" % owner["id"],
        allow_micropython_generated=(checkout == source_root.resolve()),
    )
    commit = _git_output(checkout, "retained dependency", "rev-parse", "HEAD")
    origin = _git_output(
        checkout, "retained dependency", "remote", "get-url", "origin"
    )
    _require(
        commit == owner["source_ref"] and origin == owner["source_url"],
        "RP2 retained dependency source identity changed for %s" % owner["id"],
    )


def _audit_rp2_frozen_inputs(
    *,
    manifest: Path,
    repo_root: Path,
    source_root: Path,
) -> tuple[list[tuple[str, Path]], list[Path]]:
    board_root = (
        source_root / "ports" / "rp2" / "boards" / "PYBLE_RPI_PICO2_W"
    )
    if not board_root.is_dir():
        board_root = manifest.parent
    macros = {
        "MPY_DIR": source_root,
        "PORT_DIR": source_root / "ports" / "rp2",
        "BOARD_DIR": board_root,
    }
    selected: dict[str, Path] = {}
    traversed: set[Path] = set()

    def resolve_path(value: Any, *, relative_to: Path, label: str) -> Path:
        _require(isinstance(value, str) and bool(value), "%s is invalid" % label)
        expanded = value
        for name, replacement in macros.items():
            expanded = expanded.replace("$(%s)" % name, os.fspath(replacement))
        _require("$(" not in expanded and "\x00" not in expanded, "%s is unsafe" % label)
        return _audit_rp2_admitted_path(
            expanded,
            relative_to=relative_to,
            roots=(source_root, repo_root),
            label=label,
        )

    def add(destination: str, source: Path) -> None:
        destination = _safe_relative_path(destination, "RP2 frozen destination")
        source = _audit_rp2_admitted_path(
            source,
            relative_to=manifest.parent,
            roots=(source_root, repo_root),
            label="RP2 frozen module",
        )
        _audit_regular_compile_file(source, "RP2 frozen module")
        _require(destination not in selected, "RP2 frozen manifest duplicates a destination")
        selected[destination] = source

    def resolve(current: Path) -> None:
        current = _audit_rp2_admitted_path(
            current,
            relative_to=manifest.parent,
            roots=(source_root, repo_root),
            label="RP2 frozen manifest",
        )
        _require(current not in traversed, "RP2 frozen manifest is included twice")
        traversed.add(current)
        try:
            syntax = ast.parse(
                current.read_text(encoding="utf-8", errors="strict"),
                filename=os.fspath(current),
                mode="exec",
            )
        except (OSError, UnicodeError, SyntaxError) as exc:
            raise ReleaseError("RP2 frozen manifest is not literal UTF-8 Python") from exc
        for statement in syntax.body:
            _require(
                isinstance(statement, ast.Expr)
                and isinstance(statement.value, ast.Call)
                and isinstance(statement.value.func, ast.Name),
                "RP2 frozen manifest contains dynamic syntax",
            )
            call = statement.value
            operation = call.func.id
            _require(
                operation in {"module", "package", "include", "freeze", "metadata"},
                "RP2 frozen manifest contains an unknown operation",
            )
            if operation == "metadata":
                _audit_manifest_call_arguments(
                    call,
                    operation=operation,
                    positional=(),
                    allowed_keywords={"description", "version"},
                )
                continue
            if operation == "include":
                values = _audit_manifest_call_arguments(
                    call,
                    operation=operation,
                    positional=("manifest_path",),
                    allowed_keywords={"manifest_path"},
                )
                included = resolve_path(
                    values.get("manifest_path"),
                    relative_to=current.parent,
                    label="RP2 included manifest",
                )
                if included.is_dir():
                    included /= "manifest.py"
                resolve(included)
                continue
            if operation == "module":
                values = _audit_manifest_call_arguments(
                    call,
                    operation=operation,
                    positional=("module_path", "base_path", "opt"),
                    allowed_keywords={"module_path", "base_path", "opt"},
                )
                destination = _safe_relative_path(
                    values.get("module_path"), "RP2 manifest module"
                )
                base = resolve_path(
                    values.get("base_path", "."),
                    relative_to=current.parent,
                    label="RP2 manifest module base",
                )
                add(destination, base / destination)
                continue
            if operation == "package":
                values = _audit_manifest_call_arguments(
                    call,
                    operation=operation,
                    positional=("package_path", "files", "base_path", "opt"),
                    allowed_keywords={"package_path", "files", "base_path", "opt"},
                )
                package = _safe_relative_path(
                    values.get("package_path"), "RP2 manifest package"
                )
                files = values.get("files")
                _require(
                    isinstance(files, (list, tuple))
                    and bool(files)
                    and all(isinstance(item, str) for item in files),
                    "RP2 manifest package file list is not literal",
                )
                base = resolve_path(
                    values.get("base_path", "."),
                    relative_to=current.parent,
                    label="RP2 manifest package base",
                )
                for filename in files:
                    safe_file = _safe_relative_path(filename, "RP2 manifest package file")
                    add("%s/%s" % (package, safe_file), base / package / safe_file)
                continue
            values = _audit_manifest_call_arguments(
                call,
                operation=operation,
                positional=("path", "script", "opt"),
                allowed_keywords={"path", "script", "opt"},
            )
            frozen_root = resolve_path(
                values.get("path"),
                relative_to=current.parent,
                label="RP2 frozen source",
            )
            script = values.get("script")
            if script is None:
                raise ReleaseError(
                    "RP2 freeze directory recursion is forbidden; manifest must "
                    "select an explicit literal file list"
                )
            else:
                scripts = script if isinstance(script, (list, tuple)) else (script,)
                _require(
                    bool(scripts) and all(isinstance(item, str) for item in scripts),
                    "RP2 freeze script selection is not literal",
                )
                for filename in scripts:
                    safe_file = _safe_relative_path(filename, "RP2 frozen script")
                    add(safe_file, frozen_root / safe_file)

    resolve(manifest)
    _require(bool(selected), "RP2 frozen manifest selects no literal module")
    return (
        [(name, selected[name]) for name in sorted(selected)],
        sorted(traversed),
    )


def _audit_rp2_role_for_source(namespace: str, logical_path: str) -> str:
    if namespace == "arm-gnu-toolchain":
        return "arm-gnu-runtime"
    if namespace == "micropython":
        if logical_path.startswith("lib/btstack/"):
            return "btstack"
        if logical_path.startswith("lib/cyw43-driver/"):
            return "cyw43"
        if logical_path.startswith("lib/tinyusb/"):
            return "tinyusb"
        if logical_path.startswith("lib/pico-sdk/"):
            return "pico-sdk"
    return "linked-inputs"


def _audit_rp2_control_input_paths(
    *,
    repo_root: Path,
    build_root: Path,
    validated_policy: dict[str, Any],
) -> dict[str, Path]:
    """Bind complete RP2 policy and tool-lock bytes when they are present."""

    lock_path = Path(repo_root) / "firmware" / "release-tools.lock"
    if not lock_path.is_file():
        # Small historical fixtures predate the independently locked policy.
        # Every real v0.6 checkout has this file and enters the strict branch.
        return {}
    lock_raw = _read_regular_file_bytes(lock_path, "RP2 release tool lock")
    try:
        lock_value = tomllib.loads(lock_raw.decode("utf-8", errors="strict"))
    except (UnicodeError, tomllib.TOMLDecodeError) as exc:
        raise ReleaseError("RP2 release tool lock is invalid TOML") from exc
    inputs = lock_value.get("inputs")
    _require(isinstance(inputs, dict), "RP2 release tool lock inputs are missing")
    policy_relative = inputs.get("rp2_license_policy_path")
    policy_sha256 = inputs.get("rp2_license_policy_sha256")
    _require(
        isinstance(policy_relative, str)
        and isinstance(policy_sha256, str)
        and SHA256_RE.fullmatch(policy_sha256) is not None,
        "RP2 release tool lock lacks the complete policy binding",
    )
    policy_path = _audit_repo_file(
        Path(repo_root), policy_relative, "RP2 release license policy"
    )
    policy_raw = _read_regular_file_bytes(policy_path, "RP2 release license policy")
    _require(
        _sha256_bytes(policy_raw) == policy_sha256,
        "RP2 release license policy differs from release-tools.lock",
    )
    try:
        policy_value = json.loads(policy_raw.decode("utf-8", errors="strict"))
    except (UnicodeError, TypeError, ValueError) as exc:
        raise ReleaseError("RP2 release license policy is invalid JSON") from exc
    _require(
        policy_raw == _canonical_json_bytes(policy_value),
        "RP2 release license policy is not canonical JSON",
    )
    rebound = _audit_validate_rp2_license_policy(
        policy_value,
        repo_root=Path(repo_root),
        build_root=Path(build_root),
    )
    _require(
        rebound == validated_policy,
        "RP2 release license policy object differs from its locked bytes",
    )
    return {
        "repo/firmware/release-tools.lock": lock_path,
        _audit_rp2_logical_path(
            policy_path,
            repo_root=Path(repo_root),
            build_root=Path(build_root),
        ): policy_path,
    }


def _audit_rp2_retained_board_inputs(
    *,
    repo_root: Path,
    build_root: Path,
    source_root: Path,
) -> list[dict[str, str]]:
    """Prove the exact output of prepare.sh and its lock-derived version."""

    board = (
        Path(source_root)
        / "ports"
        / "rp2"
        / "boards"
        / "PYBLE_RPI_PICO2_W"
    )
    if not board.is_dir():
        return []
    overlay = Path(repo_root) / "firmware" / "board_overlays" / "rpi-pico2-w"
    pyble = Path(repo_root) / "firmware" / "pyble"
    _require(
        overlay.is_dir() and pyble.is_dir(),
        "RP2 retained board copy lacks canonical source directories",
    )

    overlay_names = (
        "_boot.py",
        "manifest.py",
        "mpconfigboard.cmake",
        "mpconfigboard.h",
        "mpconfigvariant.cmake",
    )
    pyble_names = (
        "__init__.py",
        "pyble_agent.py",
        "pyble_ble.py",
        "pyble_boot.py",
        "pyble_console.py",
        "pyble_device_config.py",
        "pyble_fs.py",
        "pyble_info.py",
        "pyble_proto.py",
        "pyble_runner.py",
    )
    expected_copies = {
        **{name: overlay / name for name in overlay_names},
        **{"pyble/%s" % name: pyble / name for name in pyble_names},
    }
    for canonical in expected_copies.values():
        _audit_no_symlink_components(
            overlay if canonical.is_relative_to(overlay) else pyble,
            canonical,
            "RP2 canonical board input",
        )
        _audit_regular_compile_file(canonical, "RP2 canonical board input")

    expected_paths = set(expected_copies) | {
        "pyble/_version.py",
        "pble_version.h",
    }
    actual_paths: set[str] = set()
    for candidate in sorted(board.rglob("*")):
        try:
            mode = candidate.lstat().st_mode
        except OSError as exc:
            raise ReleaseError("RP2 retained board inventory changed") from exc
        _require(
            not stat_module.S_ISLNK(mode),
            "RP2 retained board inventory contains a symlink",
        )
        if stat_module.S_ISDIR(mode):
            continue
        _require(
            stat_module.S_ISREG(mode),
            "RP2 retained board inventory contains a special file",
        )
        actual_paths.add(candidate.relative_to(board).as_posix())
    _require(
        actual_paths == expected_paths,
        "RP2 retained board inventory contains unowned or missing generated files",
    )

    records: list[dict[str, str]] = []
    for relative, canonical in sorted(expected_copies.items()):
        copied = board / relative
        _require(
            copied.read_bytes() == canonical.read_bytes(),
            "RP2 retained board copy changed: %s" % relative,
        )
        for observed, kind in (
            (copied, "retained-board-copy"),
            (canonical, "canonical-board-input"),
        ):
            records.append(
                {
                    "kind": kind,
                    "logical_path": _audit_rp2_logical_path(
                        observed,
                        repo_root=Path(repo_root),
                        build_root=Path(build_root),
                    ),
                    "sha256": _sha256_path(observed),
                }
            )

    source_lock = _read_lock(Path(repo_root))
    expected_version = (
        "# SPDX-License-Identifier: MIT\n"
        "# GENERATED by firmware/scripts/build_rp2.sh from "
        "firmware/versions.lock [pyble] — do not edit.\n"
        'AGENT_VERSION = "%s"\n'
        'PROTOCOL_VERSION = "%s"\n'
        % (
            source_lock["pyble"]["agent_version"],
            source_lock["pyble"]["protocol_version"],
        )
    ).encode("utf-8")
    generated_version = board / "pyble" / "_version.py"
    expected_header = (
        "// SPDX-License-Identifier: MIT\n"
        "// GENERATED by firmware/scripts/build_rp2.sh from "
        "firmware/versions.lock [pyble] — do not edit.\n"
        "#ifndef PBLE_VERSION_H\n"
        "#define PBLE_VERSION_H\n"
        '#define PBLE_AGENT_VERSION "%s"\n'
        '#define PBLE_PROTOCOL_VERSION "%s"\n'
        "#endif  // PBLE_VERSION_H\n"
        % (
            source_lock["pyble"]["agent_version"],
            source_lock["pyble"]["protocol_version"],
        )
    ).encode("utf-8")
    generated_header = board / "pble_version.h"
    _require(
        generated_version.read_bytes() == expected_version
        and generated_header.read_bytes() == expected_header,
        "RP2 retained board generated version/config changed",
    )
    for generated, kind in (
        (generated_version, "lock-derived-agent-version"),
        (generated_header, "lock-derived-version-header"),
    ):
        _audit_regular_compile_file(generated, "RP2 retained board generated input")
        records.append(
            {
                "kind": kind,
                "logical_path": _audit_rp2_logical_path(
                    generated,
                    repo_root=Path(repo_root),
                    build_root=Path(build_root),
                ),
                "sha256": _sha256_path(generated),
            }
        )
    return sorted(records, key=lambda item: (item["kind"], item["logical_path"]))


def _audit_rp2_make_tokens(value: str, label: str) -> list[str]:
    """Parse the strict escaped-token subset emitted in compiler depfiles."""

    result: list[str] = []
    token: list[str] = []
    index = 0
    while index < len(value):
        character = value[index]
        if character == "\\":
            _require(index + 1 < len(value), "%s has a dangling escape" % label)
            token.append(value[index + 1])
            index += 2
            continue
        _require(character not in "#$", "%s contains make syntax" % label)
        if character.isspace():
            if token:
                result.append("".join(token))
                token = []
            index += 1
            continue
        token.append(character)
        index += 1
    if token:
        result.append("".join(token))
    return result


def _audit_rp2_depfile_rule(path: Path) -> tuple[str, list[str]]:
    raw = _read_regular_file_bytes(path, "RP2 compiler depfile")
    try:
        text = raw.decode("utf-8", errors="strict")
    except UnicodeError as exc:
        raise ReleaseError("RP2 compiler depfile is not UTF-8") from exc
    _require(
        "\x00" not in text and "\r" not in text,
        "RP2 compiler depfile contains control bytes",
    )
    logical = text.replace("\\\n", " ")
    if logical.endswith("\n"):
        logical = logical[:-1]
    _require(
        "\n" not in logical,
        "RP2 compiler depfile contains multiple rules or directives",
    )
    separator: int | None = None
    escaped = False
    for index, character in enumerate(logical):
        if escaped:
            escaped = False
            continue
        if character == "\\":
            escaped = True
            continue
        if character == ":":
            separator = index
            break
    _require(separator is not None, "RP2 compiler depfile has no rule separator")
    targets = _audit_rp2_make_tokens(logical[:separator], "RP2 depfile target")
    dependencies = _audit_rp2_make_tokens(
        logical[separator + 1 :], "RP2 depfile dependencies"
    )
    _require(
        len(targets) == 1 and bool(dependencies),
        "RP2 compiler depfile rule is incomplete",
    )
    return targets[0], dependencies


